/* Generated by content/permit/build_permit.py from content/permit/permit_src.py. Edit the source, then re-run the build. */
/* Massachusetts learner's permit guide (8 chapters), questions and FAQ. Facts: Massachusetts Driver's Manual, Class D, April 2026 (S7); pg = manual page numbers. */
window.PERMIT = [
{"ch": 1, "bp": ["Chapit 1 nan mànyèl la. Nan egzamen RMV a: vyolasyon JOL ak règ pou moun ki gen pèmi apranti.", "Manual chapter 1. On the RMV test: JOL violations and the rules for permit holders."], "title": ["Pèmi apranti w, egzamen an ak lwa Jèn Chofè a", "Your permit, the test and the Junior Operator law"], "src": ["S7"], "sections": [{"h": ["Jwenn yon pèmi apranti", "Getting a learner's permit"], "src": ["S7"], "pg": "14–16", "b": [["li", "Ou dwe gen omwen 16 an pou w aplike pou yon pèmi apranti Klas D (machin).", "You must be at least 16 years old to apply for a Class D (car) learner's permit."], ["li", "Pou w jwenn li: ranpli yon aplikasyon (yon paran oswa gadyen siyen si w poko gen 18 an), montre dokiman idantite w, peye frè egzamen $30 la, pase yon tès vizyon, epi pase egzamen pèmi a.", "To get it: fill out an application (a parent or guardian signs if you are under 18), show your ID documents, pay the $30 exam fee, pass a vision test, and pass the permit exam."], ["li", "Yon pèmi valab pou jiska dezan. Si l ekspire, ou dwe repase egzamen pèmi a epi peye frè a ankò.", "A permit is valid for up to two years. If it expires, you must take the permit exam again and pay the fee again."], ["li", "Yon pèmi apranti se pa yon pyès idantite pou vwayaj: pifò konpayi avyon p ap aksepte l.", "A learner's permit is not an ID for travel: most airlines will not accept it."]]}, {"h": ["Egzamen pèmi a", "The permit exam"], "src": ["S7"], "pg": "16–17", "b": [["li", "25 kesyon a chwa miltip. Ou dwe reponn 18 kòrèkteman nan 25 minit, anviwon yon minit pou chak kesyon.", "25 multiple-choice questions. You must answer 18 correctly within 25 minutes, about one minute per question."], ["li", "Sijè yo: move itilizasyon alkòl, sispansyon, vyolasyon JOL, règ wout yo ak siy wout yo.", "Topics: alcohol misuse, suspensions, JOL violations, rules of the road and road signs."], ["li", "Ou ka pran l nan anpil lang, tankou Kreyòl Ayisyen, Franse ak Panyòl. Nenpòt moun ka chwazi yon egzamen odyo: pote kas ou.", "You may take it in many languages, including Haitian Creole, French and Spanish. Anyone can choose an audio exam: bring headphones."], ["li", "Pa gen mànyèl, nòt, telefòn ni lòt aparèy elektwonik, e pa gen chapo (sof pou rezon medikal oswa relijye). Si yo jwenn ou ap pran poul, ou echwe epi ou pa ka gen okenn lisans ni pèmi pandan 60 jou.", "No manuals, notes, phones or other electronic devices, and no hats (except for medical or religious reasons). Cheating means you fail and cannot hold any license or permit for 60 days."]]}, {"h": ["Kondui ak pèmi apranti w", "Driving with your permit"], "src": ["S7"], "pg": "18", "b": [["li", "Pote pèmi w sou ou chak fwa w ap kondui.", "Carry your permit every time you drive."], ["li", "Yon chofè ki gen lisans dwe chita sou chèz pasaje devan an bò kote w. Moun sa a dwe gen omwen 21 an, yon lisans valab nan nenpòt eta, ak omwen yon ane eksperyans kondui.", "A licensed driver must sit in the front passenger seat next to you. That person must be at least 21, hold a valid license from any U.S. state, and have at least one year of driving experience."], ["li", "Si w poko gen 18 an ak yon pèmi: pa kondui ant 12:00 a.m. ak 5:00 a.m. sof si yon paran oswa gadyen legal ki gen lisans ak yon ane eksperyans avè w.", "Under 18 with a permit: no driving between 12:00 a.m. and 5:00 a.m. unless a parent or legal guardian with a license and one year of experience is with you."]]}, {"h": ["Jwenn yon Lisans pou Jèn Chofè (JOL)", "Getting a Junior Operator License (JOL)"], "src": ["S7"], "pg": "9–10, 19", "b": [["li", "Nenpòt chofè ki gen ant 16 an edmi ak 18 an se yon Jèn Chofè.", "Any driver from 16½ to 18 years old is a Junior Operator."], ["li", "Anvan Egzamen Pratik la: kenbe pèmi w pandan sis mwa youn dèyè lòt san okenn vyolasyon sou dosye w.", "Before the road test: hold your permit for six months in a row with a clean driving record."], ["li", "Fini edikasyon chofè: 30 èdtan klas, 12 èdtan dèyè volan, ak 6 èdtan ap obsève lòt elèv k ap kondui. Apre sa, pase egzamen final la.", "Complete driver's education: 30 hours of class, 12 hours behind the wheel and 6 hours observing other student drivers. Then pass the final exam."], ["li", "Kondui omwen 40 èdtan anplis ak yon paran oswa gadyen (30 èdtan si w te fini yon pwogram devlopman konpetans kondui). Yon paran oswa gadyen pran yon klas 2 èdtan tou.", "Drive at least 40 more hours with a parent or guardian (30 hours if you finished a driver skills program). A parent or guardian also takes a 2-hour class."]]}, {"h": ["Règ JOL ak penalite yo", "JOL rules and penalties"], "src": ["S7"], "pg": "10–11", "b": [["li", "Sis premye mwa yo: pa gen pasaje ki poko gen 18 an sof fanmi pwòch, sof si yon chofè ki gen lisans, 21 an oswa plis ak yon ane eksperyans, chita bò kote w.", "First six months: no passengers under 18 except immediate family, unless a licensed driver 21 or older with one year of experience sits beside you."], ["li", "Pa kondui ant 12:30 a.m. ak 5:00 a.m. sof si yon paran oswa gadyen legal avè w. Si w vyole règ sa a, yo ka akize w kòmkwa w t ap kondui san lisans, yon vyolasyon kriminèl.", "No driving from 12:30 a.m. to 5:00 a.m. unless a parent or legal guardian is with you. Breaking this rule can be charged as driving without a license, a criminal violation."], ["li", "Si w vyole règ pasaje oswa règ lannwit lan: lisans sispann 60 jou premye fwa, 180 jou dezyèm fwa, ak yon ane apre sa.", "Breaking the passenger or night rule: license suspended 60 days the first time, 180 days the second time, and one year after that."], ["li", "Lòt sispansyon JOL: premye fwa pou vitès 90 jou (apre sa yon ane); kous machin yon ane (apre sa twazan); kèk vyolasyon ak alkòl oswa dwòg yon ane.", "Other JOL suspensions: first speeding offense 90 days (then one year); drag racing one year (then three years); certain offenses with alcohol or drugs one year."], ["li", "Si w poko gen 18 an: pa gen okenn aparèy elektwonik pandan w ap kondui, menm san men. Sèl eksepsyon se pou rapòte yon ijans.", "Under 18: no mobile electronic devices at all while driving, even hands-free. The only exception is reporting an emergency."]]}, {"h": ["Egzamen Pratik la", "The road test"], "src": ["S7"], "pg": "20–27, 32", "b": [["li", "Pote pèmi w enprime, yon machin ki anrejistre epi ki pase enspeksyon, ak yon sipèvizè ki gen omwen 21 an, yon lisans valab nan eta kote l abite ak yon ane eksperyans. Yon lisans etranje pa kalifye yon sipèvizè.", "Bring your printed permit, a registered and inspected car, and a sponsor who is at least 21, has a valid license from their home state and one year of experience. A foreign license does not qualify a sponsor."], ["li", "Frè Egzamen Pratik la se $35. W ap peye l ankò si w echwe, si w an reta, si w pa vini, oswa si w anile mwens pase 72 èdtan davans.", "The road test fee is $35. You pay it again if you fail, are late, do not show up, or cancel with less than 72 hours' notice."], ["li", "Si w echwe oswa w rate yon Egzamen Pratik, tann omwen 14 jou anvan pwochen an. Pa plis pase sis egzamen pratik Klas D nan 12 mwa.", "If you fail or miss a road test, wait at least 14 days before the next one. No more than six Class D road tests in 12 months."], ["li", "Pare pou: fè siyal ak men, pake paralèl, fè bak anviwon 50 pye, fè yon vire an twa mouvman, demare ak kanpe sou yon mòn, epi respekte siy ak siyal yo.", "Be ready to: use hand signals, parallel park, back up about 50 feet, make a three-point turn, start and stop on a hill, and obey signs and signals."]]}], "terms": [["learner's permit", "pèmi apranti"], ["Junior Operator License (JOL)", "Lisans pou Jèn Chofè (JOL)"], ["road test", "Egzamen Pratik"], ["sponsor", "sipèvizè"], ["suspension", "sispansyon"], ["audio exam", "egzamen odyo"]], "qs": [["p12", 2, ["permit exam", "egzamen pèmi"], ["Konbyen kesyon ki gen nan egzamen pèmi Massachusetts la, e konbyen ou dwe jwenn bon?", "20 kesyon, 15 bon", "30 kesyon, 24 bon", "25 kesyon, 18 bon", "50 kesyon, 40 bon", "Egzamen an gen 25 kesyon a chwa miltip. Ou dwe reponn 18 kòrèkteman (72%) nan 25 minit."], ["How many questions are on the Massachusetts permit test, and how many must you get right?", "20 questions, 15 right", "30 questions, 24 right", "25 questions, 18 right", "50 questions, 40 right", "The test has 25 multiple-choice questions. You must answer 18 correctly (72%) within 25 minutes."]], ["pm101", 0, ["learner's permit", "pèmi apranti"], ["Ki laj minimòm pou w aplike pou yon pèmi apranti Klas D?", "16 an", "15 an edmi", "16 an edmi", "17 an", "Ou dwe gen omwen 16 an pou w aplike pou yon pèmi apranti Klas D oswa M."], ["What is the minimum age to apply for a Class D learner's permit?", "16", "15½", "16½", "17", "You must be at least 16 to apply for a Class D or M learner's permit."]], ["pm102", 3, ["expire", "ekspire"], ["Pandan konbyen tan yon pèmi apranti Massachusetts valab?", "Sis mwa", "Yon ane", "Jiskaske w gen 18 an", "Jiska dezan", "Yon pèmi valab pou jiska dezan. Si l ekspire, ou dwe repase egzamen an epi peye frè a ankò."], ["How long is a Massachusetts learner's permit valid?", "Six months", "One year", "Until you turn 18", "Up to two years", "A permit is valid for up to two years. If it expires, you must retake the permit exam and pay the fee again."]], ["pm103", 1, ["cheating", "pran poul"], ["Pandan egzamen pèmi a, yo kenbe yon kandida ap gade nòt sou telefòn li. Kisa k ap rive?", "Se sèlman kesyon sa a yo konte fò", "Li echwe epi li pa ka gen okenn lisans ni pèmi pandan 60 jou", "Yo ba l yon avètisman epi l kontinye", "Li dwe tann 14 jou pou l repase l", "Sèvi ak mànyèl, nòt oswa aparèy elektwonik se pran poul. Ou echwe, epi si yo jwenn ou responsab, ou pa ka gen okenn lisans ni pèmi pandan 60 jou."], ["During the permit exam, a candidate is caught looking at notes on a phone. What happens?", "Only that question is marked wrong", "They fail and cannot hold any license or permit for 60 days", "They get a warning and continue", "They must wait 14 days to retest", "Using a manual, notes or an electronic device is cheating. You fail, and if found responsible you cannot hold any license or permit for 60 days."]], ["pm104", 2, ["audio exam", "egzamen odyo"], ["Kiyès nan bagay sa yo ou ka itilize pandan egzamen pèmi a?", "Mànyèl kondiktè a", "Yon telefòn an silans", "Kas pou tande, si w ap pran yon egzamen odyo", "Yon kaskèt", "Mànyèl ak aparèy elektwonik pa otorize. Kas pou tande otorize sèlman pou yon egzamen odyo, e chapo sèlman pou rezon medikal oswa relijye."], ["Which of these may you use during the permit exam?", "The driver's manual", "A phone on silent", "Headphones, if you are taking an audio exam", "A baseball cap", "Manuals and electronic devices are not allowed. Headphones are allowed only for an audio exam, and hats only for medical or religious reasons."]], ["pm105", 3, ["supervising driver", "chofè ki akonpaye w"], ["Ou gen yon pèmi apranti. Kiyès ki ka chita bò kote w pandan w ap pratike?", "Nenpòt zanmi ki gen lisans", "Yon chofè ki gen lisans ki gen omwen 18 an", "Nenpòt granmoun, kit li gen lisans kit li pa genyen", "Yon chofè ki gen lisans, omwen 21 an, ak yon ane eksperyans", "Moun ki bò kote w la dwe gen omwen 21 an, yon lisans valab nan nenpòt eta, omwen yon ane eksperyans, epi chita sou chèz pasaje devan an."], ["You have a learner's permit. Who may sit next to you while you practice?", "Any friend who has a license", "A licensed driver who is at least 18", "Any adult, licensed or not", "A licensed driver at least 21 with one year of experience", "The person beside you must be at least 21, hold a valid license from any U.S. state, have at least one year of experience, and sit in the front passenger seat."]], ["pm106", 1, ["night restriction", "restriksyon lannwit"], ["Ou gen 17 an epi ou gen yon pèmi apranti. Nan ki lè ou PA ka kondui san yon paran oswa gadyen?", "12:30 a.m. rive 5:00 a.m.", "12:00 a.m. rive 5:00 a.m.", "10:00 p.m. rive 6:00 a.m.", "1:00 a.m. rive 4:00 a.m.", "Moun ki gen pèmi epi ki poko gen 18 an pa ka kondui ant 12:00 a.m. ak 5:00 a.m. san yon paran oswa gadyen ki gen lisans. Règ lannwit JOL la (12:30 a.m.) diferan: pa melanje yo."], ["You are 17 and have a learner's permit. During which hours may you NOT drive without a parent or guardian?", "12:30 a.m. to 5:00 a.m.", "12:00 a.m. to 5:00 a.m.", "10:00 p.m. to 6:00 a.m.", "1:00 a.m. to 4:00 a.m.", "Permit holders under 18 may not drive from 12:00 a.m. to 5:00 a.m. without a licensed parent or guardian. The JOL night rule (12:30 a.m.) is different: do not mix them up."]], ["pm107", 0, ["clean driving record", "dosye kondui pwòp"], ["Ou gen 16 an edmi. Pandan konbyen tan ou dwe kenbe pèmi w anvan w ka pase Egzamen Pratik la?", "Sis mwa youn dèyè lòt, san vyolasyon sou dosye w", "Twa mwa", "Yon ane", "Pa gen okenn tan pou tann", "Moun k ap aplike pou JOL dwe kenbe yon pèmi valab sis mwa youn dèyè lòt san vyolasyon. Yon sispansyon fè sis mwa yo rekòmanse."], ["You are 16½. How long must you hold your permit before you can take the road test?", "Six months in a row, with a clean driving record", "Three months", "One year", "There is no waiting period", "Junior Operator applicants must hold a valid permit for six consecutive months with a clean record. A suspension restarts the six months."]], ["pm108", 2, ["supervised driving", "kondui ak sipèvizyon"], ["Anplis edikasyon chofè, konbyen èdtan kondui ak yon paran oswa gadyen yon jèn chofè dwe fè?", "10 èdtan", "20 èdtan", "40 èdtan", "100 èdtan", "Omwen 40 èdtan kondui ak sipèvizyon, oswa 30 èdtan si w te fini yon pwogram devlopman konpetans kondui."], ["Besides driver's ed, how many hours of supervised driving with a parent or guardian must a junior operator complete?", "10 hours", "20 hours", "40 hours", "100 hours", "At least 40 hours of supervised driving, or 30 hours if you completed a driver skills development program."]], ["pm109", 1, ["driver's education", "edikasyon chofè"], ["Konbyen èdtan klas ki genyen nan yon pwogram edikasyon chofè Massachusetts?", "12 èdtan", "30 èdtan", "6 èdtan", "40 èdtan", "Edikasyon chofè gen 30 èdtan klas, 12 èdtan dèyè volan, ak 6 èdtan ap obsève lòt elèv k ap kondui."], ["How many hours of classroom instruction are in a Massachusetts driver's education program?", "12 hours", "30 hours", "6 hours", "40 hours", "Driver's ed includes 30 hours of class, 12 hours behind the wheel, and 6 hours observing other student drivers."]], ["p1", 2, ["Junior Operator License (JOL)", "Lisans pou Jèn Chofè (JOL)"], ["Yon chofè ki poko gen 18 an ak yon Lisans pou Jèn Chofè (JOL) pa ka kondui nan ki lè san yon paran oswa yon gadyen?", "10:00 p.m.–5:00 a.m.", "11:00 p.m.–6:00 a.m.", "12:30 a.m.–5:00 a.m.", "1:00 a.m.–4:00 a.m.", "Jèn chofè pa ka kondui ant 12:30 a.m. ak 5:00 a.m. sof si yon paran oswa yon gadyen legal nan machin nan."], ["A driver under 18 with a Junior Operator License may not drive during which hours without a parent or guardian?", "10:00 p.m.–5:00 a.m.", "11:00 p.m.–6:00 a.m.", "12:30 a.m.–5:00 a.m.", "1:00 a.m.–4:00 a.m.", "Junior operators may not drive from 12:30 a.m. to 5:00 a.m. unless a parent or legal guardian is in the car."]], ["p6", 1, ["passenger restriction", "restriksyon pasaje"], ["Pandan 6 premye mwa Lisans pou Jèn Chofè a, kiyès ki pa ka monte avè w san yon granmoun kalifye bò kote w?", "Paran w", "Pasaje ki poko gen 18 an ki pa fanmi pwòch", "Frè w oswa sè w", "Nenpòt moun ki gen plis pase 65 an", "Pandan 6 mwa, jèn chofè pa ka pote pasaje ki poko gen 18 an ki pa fanmi pwòch, sof si yon chofè ki gen lisans, 21 an oswa plis ak omwen 1 ane eksperyans, chita bò kote yo."], ["For the first 6 months of a Junior Operator License, who may not ride with you without a qualified adult beside you?", "Your parents", "Passengers under 18 who are not immediate family", "Your brother or sister", "Anyone over 65", "For 6 months, junior operators may not carry passengers under 18 who are not immediate family, unless a licensed driver age 21 or older with at least 1 year of experience sits beside them."]], ["pm110", 3, ["suspension", "sispansyon"], ["Yon jèn chofè vyole règ pasaje a pou premye fwa. Konbyen tan lisans li sispann?", "30 jou", "180 jou", "Yon ane", "60 jou", "Vyole règ pasaje oswa lannwit: 60 jou premye fwa, 180 jou dezyèm fwa, yon ane apre sa."], ["A junior operator breaks the passenger rule for the first time. What is the license suspension?", "30 days", "180 days", "One year", "60 days", "Breaking the passenger or night rule: 60 days the first time, 180 days the second, one year after that."]], ["pm111", 0, ["speeding", "depase limit vitès"], ["Yon jèn chofè jwenn premye kontravansyon pou vitès. Pandan konbyen tan lisans li sispann?", "90 jou", "Pa gen sispansyon, se amann sèlman", "Twazan", "14 jou", "Premye vyolasyon vitès pou yon moun ki gen JOL bay yon sispansyon 90 jou; pwochen an bay yon ane."], ["A junior operator gets a first speeding violation. How long is the license suspended?", "90 days", "No suspension, only a fine", "Three years", "14 days", "A JOL holder's first speeding offense brings a 90-day suspension; a later one brings one year."]], ["pm112", 2, ["criminal violation", "vyolasyon kriminèl"], ["Yon jèn chofè ap kondui poukont li a 2:00 a.m. Ak kisa yo ka akize l?", "Anyen, si l kondui avèk prekosyon", "Se sèlman yon vyolasyon pakin", "Kondui san lisans, yon vyolasyon kriminèl", "Depase limit vitès", "Kondui ant 12:30 a.m. ak 5:00 a.m. san paran oswa gadyen ka konte kòm kondui san lisans, yon vyolasyon kriminèl."], ["A junior operator drives alone at 2:00 a.m. What can they be charged with?", "Nothing, if they drive carefully", "Only a parking violation", "Driving without a license, a criminal violation", "Speeding", "Driving from 12:30 a.m. to 5:00 a.m. without a parent or guardian can be charged as operating without a license, which is a criminal violation."]], ["pm113", 1, ["road test", "Egzamen Pratik"], ["Ou echwe Egzamen Pratik ou. Pandan konbyen tan ou dwe tann anvan w repase l?", "Ou ka repase l menm jou a", "Omwen 14 jou", "Sis mwa", "Jiskaske pèmi w ekspire", "Apre w echwe oswa w rate yon Egzamen Pratik, tann omwen 14 jou. Ou pa ka pase plis pase sis egzamen pratik Klas D nan 12 mwa."], ["You failed your road test. How long must you wait before taking it again?", "You can retake it the same day", "At least 14 days", "Six months", "Until your permit expires", "After failing or missing a road test, wait at least 14 days. You may take no more than six Class D road tests in 12 months."]], ["pm114", 0, ["sponsor", "sipèvizè"], ["Kiyès ki ka sipèvizè w pou yon Egzamen Pratik Klas D?", "Yon chofè omwen 21 an ki gen yon lisans valab nan eta kote l abite ak yon ane eksperyans", "Nenpòt granmoun ki gen yon lisans etranje", "Yon zanmi 18 an ki fèk gen lisans", "Ou pa bezwen sipèvizè", "Sipèvizè a dwe gen omwen 21 an, yon lisans valab nan eta kote l abite, ak yon ane eksperyans. Yon lisans etranje pa kalifye. San sipèvizè, pa gen Egzamen Pratik Klas D."], ["Who can be your sponsor for a Class D road test?", "A driver at least 21 with a valid U.S. state license and one year of experience", "Any adult with a foreign license", "A friend who is 18 with a new license", "You do not need a sponsor", "The sponsor must be at least 21, have a valid license from their home state, and have one year of experience. A foreign license does not qualify. Without a sponsor, there is no Class D road test."]], ["pm115", 3, ["road test fee", "frè Egzamen Pratik"], ["Kilè ou dwe peye frè $35 Egzamen Pratik la ankò?", "Sèlman si w pase", "Sèlman si RMV anile akoz move tan", "Janm; se yon sèl fwa ou peye", "Si w echwe, si w an reta, si w pa vini, oswa si w anile mwens pase 72 èdtan davans", "Y ap fè w peye ankò si w echwe, si w an reta oswa absan, oswa si w anile mwens pase 72 èdtan davans. Si yo anile akoz move tan oswa yon eta ijans, ou repran randevou gratis."], ["When do you have to pay the $35 road test fee again?", "Only if you pass", "Only if the RMV cancels for bad weather", "Never; it is a one-time fee", "If you fail, are late, do not show up, or cancel with less than 72 hours' notice", "You are charged again if you fail, are late or absent, or cancel with less than 72 hours' notice. A test canceled for bad weather or a state of emergency is rescheduled free."]], ["pm116", 1, ["three-point turn", "vire an twa mouvman"], ["Ki konpetans ki fè pati Egzamen Pratik Massachusetts la?", "Kondui sou otowout a 65 mph", "Fè siyal ak men epi fè bak anviwon 50 pye", "Chanje yon kawoutchou ki plat", "Kondui lannwit", "Egzaminatè a tcheke siyal ak men, pake paralèl, fè bak anviwon 50 pye, vire an twa mouvman, demare sou mòn, kafou, ak respè siy yo. Pa konnen siyal ak men se yon rezon komen pou echwe."], ["Which skill is part of the Massachusetts road test?", "Driving on the highway at 65 mph", "Using hand signals and backing up about 50 feet", "Changing a flat tire", "Driving at night", "The examiner checks hand signals, parallel parking, backing about 50 feet, a three-point turn, hill starts, intersections, and obeying signs. Not knowing hand signals is a common reason for failing."]]]},
{"ch": 2, "bp": ["Chapit 2 nan mànyèl la, paj 34–48: senti sekirite, chèz timoun, telefòn, distans, limyè ak move tan.", "Manual chapter 2, pages 34–48: belts, child seats, phones, following distance, lights and bad weather."], "title": ["Sekirite an premye", "Safety first"], "src": ["S7"], "sections": [{"h": ["Senti sekirite, chèz timoun ak airbag", "Seat belts, child seats and air bags"], "src": ["S7"], "pg": "35–38", "b": [["li", "Tout moun nan yon machin pasaje dwe mete senti sekirite oswa chita nan yon chèz timoun. Yon chofè, oswa yon pasaje 16 an oswa plis, ki pa mete senti ka peye $25 amann. Chofè a ka peye $25 tou pou chak pasaje 12 a 15 an ki pa mete senti.", "Everyone in a passenger vehicle must wear a seat belt or ride in a child seat. An unbelted driver, or passenger 16 or older, can be fined $25. The driver can also be fined $25 for each unbelted passenger aged 12 to 15."], ["li", "Timoun yo chita nan yon chèz timoun oswa yon booster apwouve jiskaske yo gen omwen 8 an oswa omwen 57 pous wotè. Apre sa, yo mete senti sekirite.", "Children ride in an approved child seat or booster until they are at least 8 years old or at least 57 inches tall. After that, they wear seat belts."], ["li", "Pa janm mete yon chèz timoun ki gade dèyè sou yon chèz devan ki gen airbag. Pi bon kote pou yon timoun se chèz dèyè a, pi bon nan mitan.", "Never put a rear-facing child seat in a front seat that has an air bag. The safest place for a child is the back seat, best in the middle."], ["li", "Senti ki sou ren an dwe ba, sere epi plat sou anch yo. Senti zepòl la travèse zepòl ak pwatrin, pa janm anba bra a ni sou kou a. Airbag yo travay ansanm ak senti yo, yo pa ranplase yo.", "A lap belt goes low, tight and flat across the hips. A shoulder belt crosses the shoulder and chest, never under the arm or across the neck. Air bags work with belts, not instead of them."]]}, {"h": ["Distraksyon ak lwa san men an", "Distractions and the hands-free law"], "src": ["S7"], "pg": "38–40", "b": [["li", "Anyen pa dwe bloke wè w ni woule anba pedal yo. Kas pou tande entèdi pandan w ap kondui; chofè 18 an oswa plis ka mete yon sèl ti bouchon nan zòrèy pou telefòn.", "Nothing may block your view or roll under the pedals. Headphones are illegal while driving; drivers 18 and older may use one earplug for a phone."], ["li", "Chofè 18 an oswa plis ka sèvi ak telefòn sèlman san men: li tache sou vit devan, tablodbò oswa konsòl mitan an, epi ou touche l sèlman pou limen mòd san men an.", "Drivers 18 and older may use a phone only in hands-free mode: mounted on the windshield, dashboard or center console, and touched only to turn on hands-free mode."], ["li", "Ou ka kenbe yon aparèy sèlman lè machin nan kanpe epi li pa nan yon vwa sikilasyon, pa janm nan limyè wouj ni nan siy STOP. Pa gen tèks, imèl ni entènèt pandan w ap kondui. Yon GPS ki tache otorize.", "Holding a device is allowed only when the car is stopped and out of a travel lane, never at a red light or stop sign. No texting, email or internet while driving. A mounted GPS is allowed."], ["li", "Amann pou kenbe yon aparèy: $100 premye fwa, $250 dezyèm fwa (plis yon klas), $500 apre sa (plis yon ogmantasyon asirans ak yon klas).", "Fines for holding a device: $100 the first time, $250 the second (plus a class), $500 after that (plus an insurance surcharge and a class)."], ["li", "Chofè ki poko gen 18 an pa ka sèvi ak okenn aparèy, sof pou rapòte yon ijans. Timoun ki poko gen 12 an pa ka monte nan dèyè yon kamyonèt (pickup).", "Drivers under 18 may not use any mobile device at all, except to report an emergency. Children under 12 may not ride in the bed of a pickup truck."]]}, {"h": ["Kondui ak prekosyon ak kondisyon w", "Driving defensively and your condition"], "src": ["S7"], "pg": "41–42", "b": [["li", "Atann ou pou lòt chofè fè erè, kenbe espas toutotou machin ou, epi sonje: dwa de pasaj se yon bagay ou bay.", "Expect other drivers to make mistakes, keep space around your car, and remember: right-of-way is something you give."], ["li", "Pa kondui apre w fin bwè, apre w fin pran medikaman ki ka ba w dòmi, lè w fatige anpil, oswa lè w fache anpil.", "Do not drive after drinking, after taking medicine that can make you drowsy, when you are very tired, or when you are very upset."], ["li", "Kawoutchou yo bezwen omwen 2/32 pous tredd. Tès penny a: si w ka wè tèt Lincoln nèt, kawoutchou yo fin itilize.", "Tires need at least 2/32 inch of tread. Penny test: if you can see the top of Lincoln's head, the tires are worn out."]]}, {"h": ["Distans dèyè lòt machin ak kanpe", "Following distance and stopping"], "src": ["S7"], "pg": "43–45", "b": [["li", "Sèvi ak règ twa segonn lan kòm minimòm. Kenbe omwen kat segonn dèyè yon moto ak dis segonn dèyè gwo ekipman tankou kamyon fatra.", "Use the three-second rule as a minimum. Keep at least four seconds behind a motorcycle and ten seconds behind heavy equipment such as dump trucks."], ["li", "Kole dèyè lòt machin entèdi epi se prensipal kòz aksidan pa dèyè; amann lan ka rive $100. Si yon moun kole dèyè w, chanje vwa oswa rale sou kote pou kite l pase.", "Tailgating is illegal and the main cause of rear-end crashes; the fine can be up to $100. If someone tailgates you, change lanes or pull over to let them pass."], ["li", "Reyaksyon pran anviwon twa ka segonn. A 50 mph, tout distans pou w kanpe sou wout sèk se anviwon 215 pye; a 30 mph anviwon 104 pye. Gwo kamyon ka bezwen de fwa distans sa a.", "Reaction takes about three-quarters of a second. At 50 mph your total stopping distance on dry pavement is about 215 feet; at 30 mph about 104 feet. Large trucks may need twice the distance."], ["li", "Fren bonè epi dousman, pa kite pye w poze sou fren an, epi pa janm ponpe fren antiblokaj (ABS). Ralanti anvan koub yo.", "Brake early and gently, do not rest your foot on the brake, and never pump antilock brakes. Slow down before curves."]]}, {"h": ["Limyè, klaksòn ak pàn", "Lights, horn and breakdowns"], "src": ["S7"], "pg": "43, 45–46", "b": [["li", "Limyè devan yo dwe limen depi demi èdtan apre solèy kouche rive demi èdtan anvan solèy leve, lè w pa ka wè 500 pye devan, chak fwa esuiglas yo ap mache (limyè lajounen pa ase), nan tinèl, ak lè lapli, nèj oswa bwouya.", "Headlights must be on from half an hour after sunset to half an hour before sunrise, when you cannot see 500 feet ahead, whenever your wipers are on (daytime running lights are not enough), in a tunnel, and in rain, snow or fog."], ["li", "Pase soti nan gwo limyè pou limyè ba lè w a 500 pye yon machin k ap vin sou ou, ak 200 pye yon machin w ap swiv. Si limyè k ap vini yo avegle w, gade sou bò dwat anba vwa w.", "Switch from high beams to low beams within 500 feet of an oncoming vehicle and within 200 feet of a vehicle you are following. If oncoming lights blind you, look toward the lower right side of your lane."], ["li", "Sèvi ak klaksòn nan pou avèti moun epi evite aksidan, pa pou montre kòlè oswa prese lòt moun.", "Use the horn to warn people and avoid crashes, not to show anger or hurry others."], ["li", "Si machin nan tonbe an pàn, rale toutotan ou kapab sou kote wout la epi limen limyè ijans yo. Pa janm chanje yon kawoutchou plat nan yon vwa sikilasyon. Plak ou dwe li ka li a 60 pye lannwit.", "If you break down, move as far off the road as you can and turn on your emergency flashers. Never change a flat tire in a traffic lane. Your plate must be readable from 60 feet at night."]]}, {"h": ["Lannwit, lapli, bwouya, livè ak dòmi sou volan", "Night, rain, fog, winter and drowsy driving"], "src": ["S7"], "pg": "46–48", "b": [["li", "Aksidan akoz dòmi rive plis ant minwi ak 6 a.m. Kafe oswa yon ti dòmi ede pou yon ti tan sèlman: sèl vrè solisyon an se dòmi ase.", "Drowsy-driving crashes happen most between midnight and 6 a.m. Coffee or a nap helps only for a short time: the only real fix is enough sleep."], ["li", "Wout yo pi glise lè lapli fèk kòmanse melanje ak pousyè ak lwil. Si machin nan glise sou dlo (hydroplaning), lage gaz la dousman; pa fren ni vire sanzatann. Fèy mouye ka glise tankou glas. Nan bwouya, sèvi ak limyè ba.", "Roads are most slippery when rain first mixes with dirt and oil. If you hydroplane, ease off the gas; do not brake or turn suddenly. Wet leaves can be as slippery as ice. In fog, use low beams."], ["li", "Apre w fin pase nan yon gwo flak dlo, fren tou dousman pou seche fren yo.", "After driving through a deep puddle, brake lightly to dry the brakes."], ["li", "Nan livè: ralanti, pa janm bloke fren yo sou glas, epi si machin nan ap glise, vire volan an nan direksyon machin nan ap glise a. Pon yo jele anvan rès wout la. Retire tout nèj ak glas, menm sou do machin nan, sinon yo ka akize w de neglijans nan kondui.", "In winter: slow down, never lock the brakes on ice, and in a skid turn into the direction of the skid. Bridges and overpasses freeze first. Clear all snow and ice, including the roof, or you can be charged with negligent operation."]]}], "terms": [["seat belt", "senti sekirite"], ["booster seat", "chèz booster"], ["hands-free", "san men"], ["tailgating", "kole dèyè lòt machin"], ["high beams", "gwo limyè"], ["hydroplaning", "glise sou dlo"]], "qs": [["pm201", 3, ["seat belt", "senti sekirite"], ["Pasaje w ki gen 14 an pa mete senti sekirite, epi lapolis kanpe w pou yon vyolasyon. Kiyès ki ka peye amann?", "Se sèlman pasaje a", "Pèsonn: lwa a konsène chofè sèlman", "Paran pasaje a", "Ou menm, chofè a: $25", "Chofè a ka peye $25 pou chak pasaje 12 a 15 an ki pa mete senti. Pasaje 16 an oswa plis peye pwòp amann pa yo."], ["Your 14-year-old passenger is not wearing a seat belt and you are stopped for a traffic violation. Who can be fined?", "Only the passenger", "Nobody: the law only covers drivers", "The passenger's parents", "You, the driver: $25", "The driver can be fined $25 for each unbelted passenger aged 12 to 15. Passengers 16 and older are fined themselves."]], ["p8", 2, ["booster seat", "chèz booster"], ["Jiska ki laj oswa wotè yon timoun dwe chita nan yon chèz machin oswa yon booster?", "5 an", "6 an oswa 50 pous wotè", "8 an oswa 57 pous wotè", "12 an", "Timoun yo dwe sèvi ak yon chèz timoun oswa yon booster apwouve jiskaske yo gen omwen 8 an oswa omwen 57 pous wotè."], ["Until when must a child ride in a car seat or booster seat?", "Age 5", "Age 6 or 50 inches tall", "Age 8 or 57 inches tall", "Age 12", "Children must use a federally approved child seat or booster until they are at least 8 years old or at least 57 inches tall."]], ["pm202", 0, ["air bag", "airbag"], ["Ki kote li pa janm san danje pou w mete yon chèz bebe ki gade dèyè?", "Sou yon chèz devan ki gen airbag", "Nan mitan chèz dèyè a", "Dèyè chofè a", "Dèyè pasaje devan an", "Yon airbag ki louvri sou yon chèz ki gade dèyè ka blese bebe a grav. Timoun yo pi an sekirite nan chèz dèyè, pi bon nan mitan."], ["Where is it never safe to put a rear-facing infant seat?", "In a front seat with an air bag", "In the back middle seat", "Behind the driver", "Behind the front passenger", "An air bag opening against a rear-facing seat can seriously hurt the baby. Children are safest in the back seat, best in the middle."]], ["pm203", 1, ["lap belt", "senti ren"], ["Kijan senti ki sou ren an dwe chita sou ou?", "Sou vant ou, lach", "Ba, sere epi plat sou anch yo", "Tòde, pou l kenbe pi byen", "Anba bra w", "Senti ren an dwe ba, sere epi plat sou anch yo, san l pa tòde. Senti zepòl la travèse zepòl ak pwatrin, pa janm anba bra a ni sou kou a."], ["How should a lap belt fit?", "Across the stomach, loose", "Low, tight and flat across the hips", "Twisted, so it holds better", "Under your arm", "A lap belt goes low, tight and flat over the hips, not twisted. A shoulder belt crosses the shoulder and chest, never under the arm or across the neck."]], ["p2", 3, ["hands-free", "san men"], ["Èske yon chofè ki poko gen 18 an ka sèvi ak telefòn pandan l ap kondui si se san men (hands-free)?", "Wi, pou apèl sèlman", "Wi, pou GPS sèlman", "Wi, nan limyè wouj", "Non, pou okenn rezon sof pou rapòte yon ijans", "Chofè ki poko gen 18 an pa ka sèvi ak okenn aparèy elektwonik pandan y ap kondui, menm san men. Sèl eksepsyon se pou rapòte yon ijans."], ["Can a driver under 18 use a phone while driving if it is hands-free?", "Yes, for calls only", "Yes, for GPS only", "Yes, at red lights", "No, not for any reason except reporting an emergency", "Drivers under 18 may not use any mobile electronic device while driving, even hands-free. The only exception is reporting an emergency."]], ["p10", 1, ["mounted phone", "telefòn ki tache"], ["Pou chofè ki gen 18 an oswa plis, kijan yo ka sèvi ak telefòn pandan y ap kondui?", "Voye tèks nan limyè wouj", "Sèlman san men, tankou kòmand vwa", "Kenbe telefòn nan sou opalè", "Gade videyo si sikilasyon an lan", "Massachusetts entèdi kenbe telefòn pandan w ap kondui. Granmoun ka sèvi ak telefòn nan sèlman san men: li dwe tache, epi ou ka touche l sèlman pou limen mòd san men an."], ["For drivers 18 and older, which phone use is allowed while driving?", "Texting at red lights", "Hands-free use only, such as voice commands", "Holding the phone on speaker", "Watching a video in slow traffic", "Massachusetts bans holding a phone while driving. Adults may use a phone only in hands-free mode: it must be mounted, and touched only to turn on hands-free mode."]], ["pm204", 2, ["travel lane", "vwa sikilasyon"], ["Ou gen 25 an. Kilè ou ka kenbe telefòn ou nan men pou w li yon mesaj?", "Pandan w kanpe nan yon limyè wouj", "Sou bò yon otowout ki gen anpil machin", "Lè machin nan kanpe epi li pa nan vwa sikilasyon, nan yon kote ki san danje", "Lè sikilasyon an ap mache dousman", "Ou ka kenbe aparèy la sèlman lè machin nan kanpe epi li pa nan yon vwa sikilasyon piblik, pa janm nan limyè wouj ni nan siy STOP. Pa kanpe sou bò yon wout ki gen anpil machin pou w sèvi ak telefòn."], ["You are 25. When may you hold your phone in your hand to read a message?", "While stopped at a red light", "On the shoulder of a busy highway", "When the car is stopped and out of a travel lane, in a safe place", "In slow traffic", "Handheld use is allowed only when the vehicle is stopped and not in a public travel lane, never at red lights or stop signs. Do not stop on the side of a busy road to use a phone."]], ["pm205", 0, ["headphones", "kas pou tande"], ["Kisa ki vre sou kas pou tande pandan w ap kondui?", "Yo entèdi; chofè 18 an oswa plis ka mete yon sèl ti bouchon pou telefòn", "Yo otorize si volim nan ba", "Yo otorize sou otowout sèlman", "Kas san fil toujou otorize", "Kas oswa nenpòt aparèy ki anpeche w tande sa k ap pase bò kote w entèdi pandan w ap kondui. Chofè 18 an oswa plis ka mete yon sèl ti bouchon pou telefòn."], ["Which is true about headphones while driving?", "They are illegal; drivers 18 and older may use one earplug for a phone", "They are allowed at low volume", "They are allowed only on highways", "Wireless headphones are always allowed", "Headphones or any device that cuts you off from the sounds around you are illegal while driving. Drivers 18 and older may use one earplug for a cell phone."]], ["pm206", 1, ["fine", "amann"], ["Konbyen amann lan ye pou premye fwa yo kenbe w ap kenbe telefòn pandan w ap kondui?", "$25", "$100", "$250", "$500", "$100 premye fwa, $250 plis yon klas sou distraksyon dezyèm fwa, $500 plis yon klas ak yon ogmantasyon asirans apre sa."], ["What is the fine for a first offense of holding a phone while driving?", "$25", "$100", "$250", "$500", "$100 for a first offense, $250 plus a distracted-driving class for a second, $500 plus a class and an insurance surcharge after that."]], ["pm207", 0, ["right-of-way", "dwa de pasaj"], ["Kondui ak prekosyon gen ladan ki lide?", "Dwa de pasaj se yon bagay ou bay, pou evite sitiyasyon ki danjere", "Lòt chofè yo ap toujou respekte siyal yo", "Gade sèlman machin ki devan w lan", "Pran dwa de pasaj chak fwa lalwa ba ou l", "Atann ou pou lòt moun fè erè epi kenbe espas toutotou machin ou. Mànyèl la raple w dwa de pasaj se yon bagay ou bay."], ["Driving defensively includes which idea?", "Right-of-way is something you give, to prevent unsafe situations", "Other drivers will always obey signals", "Watch only the car in front of you", "Take the right-of-way whenever the law gives it to you", "Expect mistakes from others and keep space around your car. The manual reminds you that right-of-way is something you give."]], ["pm208", 2, ["tread", "tredd kawoutchou"], ["Ki pwofondè tredd minimòm lalwa mande pou kawoutchou yo?", "1/32 pous", "4/32 pous", "2/32 pous", "1/2 pous", "Kawoutchou yo bezwen omwen 2/32 pous tredd. Si w mete yon penny nan tredd la epi w wè tèt Lincoln nèt, kawoutchou yo fin itilize."], ["What is the minimum legal tire tread depth?", "1/32 inch", "4/32 inch", "2/32 inch", "1/2 inch", "Tires need at least 2/32 inch of tread. If you put a penny in the groove and see the top of Lincoln's head, the tires are worn out."]], ["pm209", 3, ["three-second rule", "règ twa segonn"], ["Lè kondisyon yo bon, ki distans minimòm pou w kenbe dèyè yon machin?", "Longè yon machin", "Yon segonn", "Dis segonn", "Twa segonn", "Sèvi ak règ twa segonn lan: lè machin devan an pase yon bagay ki pa bouje, konte twa segonn anvan w rive la. Se yon minimòm; ajoute tan lè kondisyon yo pa bon."], ["In good conditions, what is the minimum following distance behind a car?", "One car length", "One second", "Ten seconds", "Three seconds", "Use the three-second rule: when the car ahead passes a fixed object, count three seconds before you reach it. It is a minimum; add time in bad conditions."]], ["pm210", 1, ["following distance", "distans dèyè"], ["Ki distans ou dwe kenbe dèyè yon moto?", "De segonn", "Omwen kat segonn", "Menm jan ak yon machin", "Longè yon machin", "Kenbe omwen kat segonn dèyè yon moto, konpare ak twa segonn dèyè lòt veyikil."], ["How much following distance should you keep behind a motorcycle?", "Two seconds", "At least four seconds", "Same as a car", "One car length", "Keep at least four seconds behind a motorcycle, compared with three seconds behind other vehicles."]], ["pm211", 2, ["heavy equipment", "gwo ekipman"], ["Ou dèyè yon kamyon fatra (dump truck). Ki distans mànyèl la rekòmande?", "Twa segonn", "Kat segonn", "Omwen dis segonn", "Senk longè machin", "Kenbe omwen dis segonn dèyè gwo ekipman tankou kamyon fatra ak traktè, epi pa janm koupe devan yo: yo bezwen plis espas pou yo kanpe."], ["You are behind a dump truck. What following distance does the manual recommend?", "Three seconds", "Four seconds", "At least ten seconds", "Five car lengths", "Keep at least ten seconds behind heavy equipment such as dump trucks and tractors, and never cut in front of them: they need much more space to stop."]], ["pm212", 0, ["stopping distance", "distans pou kanpe"], ["Sou yon wout sèk a 50 mph, anviwon ki distans sa pran pou w reyaji epi kanpe?", "Anviwon 215 pye", "Anviwon 50 pye", "Anviwon 100 pye", "Anviwon 500 pye", "Anviwon 55 pye pandan w ap reyaji plis anviwon 160 pye fren: anviwon 215 pye an tout. Li pi long sou wout mouye oswa glise."], ["On dry pavement at 50 mph, about how far does it take to react and stop?", "About 215 feet", "About 50 feet", "About 100 feet", "About 500 feet", "About 55 feet while you react plus about 160 feet of braking: about 215 feet in total. It is longer on wet or slippery roads."]], ["pm213", 3, ["antilock brakes (ABS)", "fren antiblokaj (ABS)"], ["Machin ou gen fren antiblokaj (ABS). Kisa ou PA dwe fè lè w ap fren fò?", "Kenbe je w sou wout la", "Dirije machin nan kote w vle ale", "Kenbe de men w sou volan an", "Ponpe fren yo", "Pa janm ponpe fren antiblokaj. Fren bonè epi dousman lè w kapab, epi pa kite pye w poze sou pedal fren an."], ["Your car has antilock brakes. What should you NOT do when braking hard?", "Keep your eyes on the road", "Steer where you want to go", "Keep both hands on the wheel", "Pump the brakes", "Never pump antilock brakes. Also brake early and gently when you can, and do not rest your foot on the brake pedal."]], ["p5", 1, ["headlights", "limyè devan"], ["Nan Massachusetts, lè w limen esuiglas ou (wipers), ou dwe tou:", "Limen limyè ijans yo", "Limen limyè devan ou", "Desann a 25 mph", "Sèvi ak gwo limyè", "Chak fwa w sèvi ak esuiglas yo, limyè devan ak limyè dèyè yo dwe limen. Limyè lajounen pa ase."], ["In Massachusetts, when you turn on your windshield wipers, you must also:", "Turn on your hazard lights", "Turn on your headlights", "Slow to 25 mph", "Use your high beams", "Whenever you use your wipers, your headlights and taillights must be on. Daytime running lights are not enough."]], ["pm214", 2, ["headlights", "limyè devan"], ["Kilè limyè devan w yo dwe limen, menm lè pa gen lapli?", "Sèlman apre 9:00 p.m.", "Sèlman sou otowout", "Depi demi èdtan apre solèy kouche rive demi èdtan anvan solèy leve", "Sèlman lè l fè nwa nèt", "Limyè yo limen depi demi èdtan apre solèy kouche rive demi èdtan anvan solèy leve, ak chak fwa w pa ka wè 500 pye devan, nan tinèl, ak lè lapli, nèj oswa bwouya."], ["When must your headlights be on, even without rain?", "Only after 9:00 p.m.", "Only on highways", "From half an hour after sunset to half an hour before sunrise", "Only when it is completely dark", "Headlights go on from half an hour after sunset to half an hour before sunrise, and any time you cannot see 500 feet ahead, in tunnels, and in rain, snow or fog."]], ["pm215", 0, ["low beams", "limyè ba"], ["Yon machin ap vin sou ou lannwit. Kilè ou dwe pase soti nan gwo limyè pou limyè ba?", "Lè w a 500 pye de li", "Lè w a 100 pye de li", "Sèlman si l fè limyè l kliyote", "Ou pa janm oblije", "Pase nan limyè ba lè w a 500 pye yon machin k ap vin sou ou, ak 200 pye yon machin w ap swiv."], ["A car is coming toward you at night. When must you switch from high beams to low beams?", "Within 500 feet of it", "Within 100 feet of it", "Only if it flashes its lights", "You never have to", "Dim to low beams within 500 feet of an oncoming vehicle and within 200 feet of a vehicle you are following."]], ["pm216", 3, ["glare", "limyè ki avegle"], ["Limyè machin k ap vin sou ou yo ap avegle w. Ki kote ou dwe gade?", "Dirèkteman nan limyè yo", "Nan miwa w", "Fèmen je w yon ti moman", "Sou bò dwat anba vwa w", "Pa gade dirèkteman nan limyè yo. Gade sou bò dwat anba vwa w. Si lòt chofè a kenbe gwo limyè l, rete adwat epi pa limen pa w."], ["Oncoming headlights are blinding you. Where should you look?", "Straight into the lights", "At your mirror", "Close your eyes for a moment", "Toward the lower right side of your lane", "Do not look straight at headlights. Look toward the lower right side of your lane. If the other driver keeps high beams on, stay right and do not turn yours on."]], ["pm217", 1, ["emergency flashers", "limyè ijans"], ["Machin ou tonbe an pàn sou yon wout ki gen anpil machin. Kisa ou dwe fè?", "Kanpe nan vwa w epi chanje kawoutchou a rapid", "Rale toutotan ou kapab sou kote wout la epi limen limyè ijans yo", "Etenn tout limyè pou ekonomize batri a", "Kanpe dèyè machin nan pou fè siy machin yo pase", "Rale toutotan ou kapab sou kote, limen limyè ijans yo, epi rete lwen wout la. Pa janm chanje yon kawoutchou plat nan yon vwa sikilasyon."], ["Your car breaks down on a busy road. What should you do?", "Stop in your lane and change the tire quickly", "Move as far off the road as you can and turn on your emergency flashers", "Turn off all lights to save the battery", "Stand behind the car to wave traffic around", "Pull as far to the side as you can, use your emergency lights, and stay off the road. Never change a flat tire in a traffic lane."]], ["pm218", 2, ["drowsy driving", "dòmi sou volan"], ["Ki sèl vrè fason pou w evite kondui ak dòmi nan je?", "Bwè kafe", "Louvri vit yo epi mete mizik fò", "Dòmi ase, epi pa kondui lè w fatige", "Kondui pi vit pou w rive lakay pi vit", "Kafe oswa yon ti dòmi ede pou yon ti tan sèlman. Sèl vrè pwoteksyon an se dòmi ase. Aksidan akoz dòmi rive plis ant minwi ak 6 a.m."], ["What is the only real way to prevent drowsy driving?", "Drink coffee", "Open the windows and play loud music", "Get enough sleep, and do not drive when you are tired", "Drive faster to get home sooner", "Coffee or a nap helps only for a short time. The only true protection is enough sleep. Drowsy crashes happen most between midnight and 6 a.m."]], ["pm219", 0, ["hydroplaning", "glise sou dlo"], ["Machin ou kòmanse glise sou dlo sou yon wout mouye. Kisa ou dwe fè?", "Lage pedal gaz la dousman; pa fren ni vire sanzatann", "Fren fò", "Akselere pou w travèse dlo a", "Vire volan an fò", "Glise sou dlo vle di kawoutchou yo ap woule sou dlo. Ou twò vit: lage gaz la dousman. Si w fren oswa vire sanzatann, machin nan ka derape."], ["Your car starts to hydroplane on a wet road. What should you do?", "Slowly ease off the gas pedal; do not brake or turn suddenly", "Brake hard", "Speed up to get through the water", "Turn the wheel sharply", "Hydroplaning means your tires are riding on water. You are going too fast: ease off the gas slowly. Braking or turning suddenly can cause a skid."]], ["pm220", 3, ["slippery road", "wout ki glise"], ["Kilè wout yo pi glise anjeneral lè lapli ap tonbe?", "Apre lapli fin tonbe plizyè èdtan", "Sèlman lannwit", "Lè lapli a sispann", "Lè lapli a fèk kòmanse", "Wout yo souvan pi glise lè lapli fèk kòmanse melanje ak pousyè ak lwil sou wout la epi fè yon kouch grès. Ralanti depi lapli a kòmanse."], ["When are roads usually most slippery in the rain?", "After it has rained for several hours", "Only at night", "When the rain stops", "When the rain first starts", "Roads are often most slippery when rain first mixes with road dirt and oil and forms a greasy film. Slow down as soon as the rain starts."]], ["pm221", 1, ["overpass", "pon"], ["Nan livè, ki pati nan wout la ki konn jele anvan?", "Wout nan vil", "Pon ak pasaj anwo wout", "Wout k ap monte", "Pakin yo", "Pon ak pasaj anwo wout jele anvan rès wout la paske tè a pa izole yo."], ["In winter, which part of the road usually freezes first?", "Roads in town", "Bridges and overpasses", "Uphill roads", "Parking lots", "Bridges and overpasses freeze before the rest of the road because the ground does not insulate them."]], ["pm222", 2, ["skid", "derape"], ["Machin ou derape sou yon wout glase. Ki bò ou dwe vire volan an?", "Fò, nan direksyon opoze glisad la", "Kenbe volan an dwat epi fren fò", "Nan direksyon machin nan ap glise a", "Sou bò wout la", "Vire nan direksyon glisad la, epi pa janm bloke fren yo sou glas: fren ki bloke anpeche w dirije machin nan."], ["Your car skids on an icy road. Which way should you steer?", "Away from the skid, hard", "Keep the wheel straight and brake hard", "In the direction of the skid", "Toward the shoulder", "Turn into the direction of the skid, and never lock your brakes on ice: locked brakes take away your steering."]], ["pm223", 0, ["negligent operation", "neglijans nan kondui"], ["Gen nèj anpile sou do machin ou. Kisa lalwa mande?", "Retire l anvan w kondui, sinon yo ka akize w de neglijans nan kondui", "Anyen; se sèlman vit devan an ki dwe pwòp", "Kondui dousman pou l pa vole", "Retire l sèlman pou otowout", "Retire tout nèj ak glas: vit, esuiglas, limyè, do machin, kapo ak kòf, pou l pa vole sou machin dèyè w. Si w pa fè l, yo ka akize w de neglijans nan kondui."], ["Snow is piled on your car's roof. What does the law expect?", "Clear it before driving, or you can be charged with negligent operation", "Nothing; only the windshield must be clear", "Drive slowly so it does not blow off", "Clear it only on highways", "Remove all snow and ice: windows, wipers, lights, roof, hood and trunk, so it does not blow onto cars behind you. If you do not, you can be charged with negligent operation."]]]},
{"ch": 3, "bp": ["Chapit 2 nan mànyèl la, paj 49–54, ak chapit 4, paj 104–117. Nan egzamen RMV a: règ wout yo.", "Manual chapter 2, pages 49–54, and chapter 4, pages 104–117. On the RMV test: rules of the road."], "title": ["Pataje wout la", "Sharing the road"], "src": ["S7"], "sections": [{"h": ["Moun ki pi frajil sou wout la", "Vulnerable road users"], "src": ["S7"], "pg": "49", "b": [["li", "Moun ki pi frajil sou wout la gen ladan pyeton, travayè bò wout, siklis, moun ki monte cheval, ak moun ki sèvi ak chèz woulant, moped, eskoutè, skateboard oswa paten.", "Vulnerable road users include pedestrians, roadside workers, bicyclists, horse riders, and people using wheelchairs, mopeds, scooters, skateboards or roller skates."], ["li", "Lè w ap depase youn, kite omwen kat pye. Si l san danje, ou ka sèvi ak yon pati nan vwa bò kote a oswa travèse liy mitan an, epi ou toujou dwe respekte limit vitès la.", "When you pass one, leave at least four feet. If it is safe, you may use part of the next lane or cross the center line, and you must still obey the speed limit."]]}, {"h": ["Pyeton", "Pedestrians"], "src": ["S7"], "pg": "49–50, 112", "b": [["li", "Veye timoun toupre lekòl, pak, arè bis ak teren jwèt, ak granmoun toupre sant pou granmoun. Gade si gen moun ki kache dèyè koub, mòn oswa machin ki pake.", "Watch for children near schools, parks, bus stops and playgrounds, and for older people near senior centers. Look for people hidden by curves, hills or parked cars."], ["li", "Anvan w fè bak, gade dèyè machin nan epi vire tèt ou pou w gade. Pa konte sèlman sou miwa oswa detektè yo.", "Before backing up, check behind the car and turn your head to look. Do not rely only on mirrors or sensors."], ["li", "Ou pa ka konnen lè w gade yon moun si l soud oswa si l gen difikilte pou tande. Pa sipoze moun yo ka tande machin ou: li toujou pi san danje pou w bay dwa de pasaj.", "You cannot tell by looking whether someone is Deaf or hard of hearing. Do not assume people can hear your car: it is always safer to yield."]]}, {"h": ["Bisiklèt", "Bicycles"], "src": ["S7"], "pg": "50–51, 112–117", "b": [["li", "Siklis yo gen menm dwa sou wout la ak chofè yo epi yo ka sèvi ak tout vwa a, menm kote gen yon vwa bisiklèt. Lalwa pèmèt yo woule sou bò dwat machin yo.", "Bicyclists have the same right to the road as drivers and may use the full lane, even where there is a bike lane. They may legally ride to the right of traffic."], ["li", "Depase yon siklis dousman ak omwen kat pye espas, tann si vwa a twò etwat, epi pa koupe devan l ni vire adwat sanzatann devan l apre w fin depase l.", "Pass a bicyclist slowly with at least four feet of space, wait if the lane is too narrow, and do not cut back in or turn right sharply in front of them after passing."], ["li", "Lè w ap vire agoch, bay siklis k ap vini yo dwa de pasaj. Anvan w louvri pòt machin nan, gade miwa yo epi sèvi ak men ki pi lwen pòt la (Dutch Reach). Louvri yon pòt sou yon siklis ka koute w jiska $100 amann.", "Turning left, yield to oncoming bicyclists. Before opening a car door, check mirrors and use the hand farther from the door (the Dutch Reach). Opening a door into a bicyclist can bring a fine of up to $100."], ["li", "Kanpe dèyè yon bwat bisiklèt vèt nan limyè wouj, menm lè l vid. Siklis ak pasaje ki poko gen 16 an dwe mete yon kas bisiklèt.", "Stop behind a green bicycle box at a red light, even when it is empty. Riders and passengers under 16 must wear a bicycle helmet."]]}, {"h": ["Moto ak moped", "Motorcycles and mopeds"], "src": ["S7"], "pg": "51–53", "b": [["li", "Chofè yo konn pa wè moto. Gade de fwa anvan w chanje vwa oswa vire agoch, epi kite yon moto k ap vini pase nan kafou a anvan.", "Drivers often overlook motorcycles. Check twice before changing lanes or turning left, and let an oncoming motorcycle pass through the intersection first."], ["li", "Yon moto gen dwa sèvi ak tout lajè yon vwa. Pa janm pataje yon vwa ak yon moto. Kenbe kat segonn distans dèyè l.", "A motorcycle has the right to the full width of a lane. Never share a lane with one. Keep a four-second following distance."], ["li", "Yon moped (bisiklèt ak motè) pa ka depase 25 mph epi li mande yon lisans oswa yon pèmi apranti. Yon eskoutè ak motè limite a 20 mph. Moun ki monte tou de dwe mete yon kas DOT.", "A moped (motorized bicycle) may not go faster than 25 mph and needs a driver's license or learner's permit. A motorized scooter is limited to 20 mph. Riders of both must wear a DOT helmet."]]}, {"h": ["Bis lekòl, trole ak transpò piblik", "School buses, trolleys and transit"], "src": ["S7"], "pg": "105, 107", "b": [["li", "Lè yon bis lekòl gen limyè wouj li k ap limen etèn epi siy stop li louvri, ou dwe kanpe, kèlkeswa bò wout ou ye a, epi rete kanpe jiskaske limyè yo sispann epi siy la fèmen.", "When a school bus has its red lights flashing and stop sign out, you must stop, whichever side of the road you are on, and stay stopped until the lights stop and the sign folds back."], ["li", "Sèl eksepsyon an se yon bis ki sou lòt bò yon otowout divize ki gen yon baryè. Premye vyolasyon ka bay yon sispansyon lisans ak yon amann $250.", "The only exception is a bus on the other side of a divided highway with a barrier. A first violation can bring a license suspension and a $250 fine."], ["li", "Rete omwen uit pye de mach pasaje yon trole pandan moun ap monte oswa desann. Kite bis yo soti nan arè yo.", "Stay at least eight feet from a trolley's passenger step while people get on or off. Let buses pull out from their stops."]]}, {"h": ["Kamyon, machin ki lan, bèt ak lòt chofè", "Trucks, slow vehicles, animals and other drivers"], "src": ["S7"], "pg": "104–109", "b": [["li", "Gwo kamyon gen gwo kwen avèg sou kat bò yo. Si w pa ka wè miwa yon kamyon, chofè a pa ka wè w. Kamyon ka bezwen de fwa distans pou kanpe, kidonk pa janm koupe devan youn.", "Large trucks have big blind spots on all four sides. If you cannot see a truck's mirrors, the driver cannot see you. Trucks may need twice the stopping distance, so never cut in front of one."], ["li", "Kamyon ak bis vire adwat byen laj epi yo ka ale agoch anvan. Pa depase yo sou bò dwat; rete dèyè jiskaske w konnen sa chofè a pral fè.", "Trucks and buses make wide right turns and may swing left first. Do not pass them on the right; stay behind until you know what the driver is doing."], ["li", "Yon triyang zoranj dèyè yon veyikil make se yon veyikil ki mache dousman: ralanti. Kòtèj fineray gen dwa de pasaj nan kafou yo; pa antre nan youn ni pase ant machin li yo.", "An orange triangle on the back marks a slow-moving vehicle: slow down. Funeral processions have the right-of-way at intersections; do not join one or drive between its vehicles."], ["li", "Bay bèt yon moun ap mennen, monte oswa kondui dwa de pasaj. Ralanti, pa klaksonnen, epi rale sou kote epi kanpe si bèt la sanble l pè.", "Give the right-of-way to animals being led, ridden or driven. Slow down, do not honk, and pull over and stop if an animal looks scared."], ["li", "Si yon chofè agresif fè w fas, retire kò w nan chemen l, pa defye l, evite gade l nan je epi pa okipe jès li yo. Rele 911 pou rapòte yon ijans.", "If an aggressive driver confronts you, get out of their way, do not challenge them, avoid eye contact and ignore gestures. Call 911 to report an emergency."]], "sign": "smv"}], "terms": [["vulnerable road user", "moun ki pi frajil sou wout la"], ["bicyclist", "siklis"], ["moped", "moped"], ["school bus", "bis lekòl"], ["blind spot", "kwen avèg"], ["slow-moving vehicle", "veyikil ki mache dousman"]], "qs": [["pm301", 2, ["vulnerable road user", "moun ki pi frajil sou wout la"], ["Konbyen espas ou dwe kite lè w ap depase yon siklis, yon pyeton oswa yon travayè bò wout?", "Yon pye", "De pye", "Omwen kat pye", "Dis pye", "Lwa Massachusetts mande omwen kat pye lè w ap depase yon moun ki frajil sou wout la. Si l san danje, ou ka sèvi ak yon pati nan vwa bò kote a oswa travèse liy mitan an, san w pa depase limit vitès la."], ["How much space must you leave when passing a bicyclist, pedestrian or roadside worker?", "One foot", "Two feet", "At least four feet", "Ten feet", "Massachusetts law requires at least four feet when passing a vulnerable road user. If safe, you may use part of the next lane or cross the center line, without speeding."]], ["pm302", 0, ["roadside worker", "travayè bò wout"], ["Kiyès nan moun sa yo ki se yon moun ki frajil sou wout la dapre lwa Massachusetts?", "Yon moun ki monte cheval", "Yon chofè kamyon", "Yon pasaje bis", "Yon chofè nan yon machin ki pake", "Moun ki frajil sou wout la gen ladan pyeton, travayè bò wout, siklis, moun ki monte cheval, ak moun ki sèvi ak chèz woulant, moped, eskoutè, skateboard oswa paten."], ["Which of these is a vulnerable road user under Massachusetts law?", "A person riding a horse", "A truck driver", "A bus passenger", "A driver in a parked car", "Vulnerable road users include pedestrians, roadside workers, bicyclists, people riding horses, and people using wheelchairs, mopeds, scooters, skateboards or roller skates."]], ["pm303", 3, ["backing up", "fè bak"], ["Machin ou gen yon kamera pou fè bak. Kisa ou toujou dwe fè anvan w fè bak soti nan yon antre kay?", "Anyen; kamera a ase", "Klaksonnen twa fwa", "Fè bak vit pou w pa pase twòp tan nan wout la", "Gade dèyè machin nan epi vire tèt ou pou w gade", "Kwen avèg yo ka kache timoun oswa bèt. Gade dèyè machin nan anvan w monte, epi vire tèt ou gade nan fenèt la pandan w ap fè bak. Pa konte sèlman sou miwa oswa detektè."], ["Your car has a backup camera. What should you still do before backing out of a driveway?", "Nothing; the camera is enough", "Honk three times", "Back up quickly to limit the time in the road", "Check behind the car and turn your head to look", "Blind spots can hide children or animals. Check behind the vehicle before getting in, and turn your head and look out the window as you back up. Do not rely only on mirrors or sensors."]], ["pm304", 1, ["Deaf or hard of hearing", "soud oswa difikilte pou tande"], ["Yon pyeton antre nan ri a san l pa gade machin ou. Ki sa ki pi san danje pou w panse?", "Li tande w epi l ap kanpe", "Li ka pa tande machin ou, kidonk bay dwa de pasaj", "L ap vyole lalwa, kidonk ou ka kontinye", "Klaksonnen ap toujou rezoud sa", "Ou pa ka konnen lè w gade yon moun si l soud oswa si l gen difikilte pou tande. Li toujou pi san danje pou w bay dwa de pasaj, menm si se ou ki gen dwa a."], ["A pedestrian steps into the street without looking toward your car. What is the safest assumption?", "They heard you and will stop", "They may not hear your car, so yield", "They are breaking the law, so you may continue", "Honking will always solve it", "You cannot tell by looking whether someone is Deaf or hard of hearing. It is always safer to yield, even if you have the right-of-way."]], ["pm305", 2, ["full lane", "tout vwa a"], ["Yon siklis ap woule nan mitan vwa a sou yon ri ki gen yon vwa bisiklèt. Kisa ki vre?", "Li oblije sèvi ak vwa bisiklèt la", "Ou ka klaksonnen jiskaske l deplase", "Siklis yo ka sèvi ak tout vwa a, menm kote gen yon vwa bisiklèt", "Bisiklèt pa gen dwa sou ri ki gen vwa bisiklèt", "Siklis yo ka sèvi ak tout vwa a nenpòt kote, nenpòt lè, sou nenpòt ri sof otowout ak aksè limite ki make, menm kote gen yon vwa bisiklèt. Depase sèlman lè w ka kite omwen kat pye."], ["A bicyclist is riding in the middle of the lane on a street that has a bike lane. Which is true?", "They must use the bike lane", "You may honk until they move", "Bicyclists may use the full lane, even where there is a bike lane", "Bicycles are not allowed on streets with bike lanes", "Bicyclists can use the full lane anywhere, anytime, on any street except posted limited-access highways, even where there is a bike lane. Pass only when you can leave at least four feet."]], ["pm306", 3, ["Dutch Reach", "Dutch Reach (louvri ak lòt men an)"], ["Ou pake sou yon ri ki gen anpil moun. Ki pi bon fason pou w louvri pòt ou?", "Pouse l louvri vit", "Louvri l yon ti kras epi tann", "Mete siyal agoch, apre sa louvri l", "Gade miwa yo, apre sa louvri l ak men ki pi lwen pòt la", "Gade miwa dèyè a ak miwa sou kote a, apre sa sèvi ak men ki pi lwen an (Dutch Reach). Kò w vire konsa ou wè siklis k ap vini yo. Louvri yon pòt sou yon siklis ka koute jiska $100."], ["You parked on a busy street. What is the best way to open your door?", "Push it open quickly", "Open it a little and wait", "Signal left, then open it", "Check your mirrors, then open it with the hand farther from the door", "Check your rear-view and side mirrors, then use the far hand (the Dutch Reach). Your body turns so you see bicyclists coming. Opening a door into a bicyclist can cost up to $100."]], ["pm307", 1, ["right hook", "vire adwat devan siklis"], ["Ou fèk depase yon siklis epi ou vle vire adwat nan pwochen antre a. Kisa ou dwe fè?", "Vire touswit devan l", "Vire sèlman lè w byen lwen devan l, oswa kite l pase anvan", "Klaksonnen pou l kanpe", "Akselere, apre sa fren fò pou vire", "Pa vire adwat sanzatann apre w fin depase yon siklis. Vire sèlman lè w byen lwen epi a yon vitès rezonab. Lalwa pèmèt bisiklèt woule sou bò dwat ou."], ["You just passed a bicyclist and want to turn right at the next driveway. What should you do?", "Turn right away in front of them", "Turn only when you are a safe distance ahead, or let them pass first", "Honk so they stop", "Speed up, then brake hard to turn", "Do not make an abrupt right turn after passing a bicyclist. Turn only at a safe distance and a reasonable speed. Bicycles may legally ride on your right."]], ["pm308", 0, ["bicycle box", "bwat bisiklèt"], ["Nan yon limyè wouj, gen yon bwat vèt ak yon desen bisiklèt pentire devan pasaj pyeton an. Ki kote ou kanpe?", "Dèyè bwat bisiklèt la, menm si l vid", "Anndan bwat la si pa gen bisiklèt", "Sou pasaj pyeton an", "Nenpòt kote, depi w kanpe", "Chofè yo dwe kanpe dèyè yon bwat bisiklèt, menm lè l vid, epi tann limyè vèt la."], ["At a red light, a green box with a bicycle symbol is painted ahead of the crosswalk. Where do you stop?", "Behind the bicycle box, even if it is empty", "Inside the box if no bicycles are there", "On the crosswalk", "Anywhere, as long as you stop", "Drivers must stop behind a bicycle box, even when it is empty, and wait for the green light."]], ["pm309", 2, ["bicycle helmet", "kas bisiklèt"], ["Kiyès ki dwe mete yon kas bisiklèt nan Massachusetts?", "Tout moun", "Sèlman moun ki gen plis pase 18 an", "Siklis ak pasaje ki poko gen 16 an", "Pèsonn; se opsyonèl", "Yon siklis oswa pasaje ki poko gen 16 an dwe mete yon kas apwouve sou wout piblik ak chemen bisiklèt. Kas yo diminye anpil lanmò ak blesi grav pou tout moun."], ["Who must wear a bicycle helmet in Massachusetts?", "Everyone", "Only riders over 18", "Riders and passengers under 16", "No one; it is optional", "A bicycle operator or passenger under 16 must wear an approved helmet on public ways and bike paths. Helmets greatly reduce deaths and serious injuries for everyone."]], ["pm310", 3, ["motorcycle", "moto"], ["Yon moto ap woule sou bò goch yon vwa ki laj. Èske w ka vin kanpe bò kote l nan menm vwa a?", "Wi, si vwa a laj ase", "Wi, men sèlman lè sikilasyon an lan", "Wi, si w mete siyal anvan", "Non; pa janm pataje yon vwa ak yon moto", "Yon moto gen dwa sèvi ak tout lajè yon vwa. Antre nan vwa li a ilegal epi danjere anpil, menm si vwa a laj."], ["A motorcycle is riding on the left side of a wide lane. May you pull up beside it in the same lane?", "Yes, if the lane is wide enough", "Yes, but only in slow traffic", "Yes, if you signal first", "No; never share a lane with a motorcycle", "A motorcycle has the right to the full width of a lane. Crowding into its lane is illegal and very dangerous, even if the lane is wide."]], ["pm311", 0, ["left turn", "vire agoch"], ["W ap tann pou vire agoch. Yon moto k ap vini ap pwoche kafou a. Kisa ou dwe fè?", "Kite moto a pase anvan", "Vire vit devan l", "Fè limyè w kliyote epi vire", "Vire; moto ka kanpe vit", "Machin ki vire agoch devan moto k ap vini lakoz anpil aksidan. Li difisil pou w konnen vitès yo, epi moun ki sou moto a ka pa gen tan ralanti. Kite moto a pase anvan."], ["You are waiting to turn left. An oncoming motorcycle is approaching the intersection. What should you do?", "Let the motorcycle pass through first", "Turn quickly in front of it", "Flash your lights and turn", "Turn; motorcycles can stop quickly", "Cars turning left in front of oncoming motorcycles cause many crashes. Their speed is hard to judge, and the rider may not have time to slow down. Let the motorcycle pass first."]], ["pm312", 1, ["moped", "moped"], ["Ki règ ki aplike pou kondui yon moped (bisiklèt ak motè) nan Massachusetts?", "Ou pa bezwen lisans ni pèmi", "Ou bezwen yon lisans oswa yon pèmi apranti, epi ou pa ka depase 25 mph", "Ou ka monte sou otowout", "Kas se opsyonèl", "Yon moped mande yon lisans (nenpòt klas) oswa yon pèmi apranti. Pa kondui pi vit pase 25 mph, mete yon kas DOT, epi pa monte sou otowout ak aksè limite. Ak yon pèmi, pa pote pasaje."], ["Which rule applies to driving a moped (motorized bicycle) in Massachusetts?", "No license or permit is needed", "You need a license or learner's permit, and may not exceed 25 mph", "You may ride on highways", "Helmets are optional", "A moped needs a valid driver's license (any class) or learner's permit. Do not drive faster than 25 mph, wear a DOT helmet, and stay off limited-access highways. With a permit, carry no passengers."]], ["pm313", 2, ["school bus", "bis lekòl"], ["Sou yon wout de vwa, yon bis lekòl k ap vin sou ou kanpe ak limyè wouj k ap limen etèn epi siy stop li louvri. Kisa ou dwe fè?", "Ralanti epi pase avèk prekosyon", "Anyen; li sou lòt bò a", "Kanpe epi rete kanpe jiskaske limyè yo sispann epi siy la fèmen", "Klaksonnen pou avèti timoun yo", "Ou dwe kanpe pou yon bis lekòl ki gen limyè wouj k ap limen etèn ak siy stop li louvri, kèlkeswa bò wout ou ye a. Menm apre l fin ale, kondui dousman epi veye timoun yo."], ["On a two-lane road, a school bus coming toward you stops with red lights flashing and its stop sign out. What must you do?", "Slow down and pass carefully", "Nothing; it is on the other side", "Stop and stay stopped until the lights stop and the sign folds back", "Honk to warn the children", "You must stop for a school bus with flashing red lights and its stop sign out, whichever side of the road you are on. Even after it moves, go slowly and watch for children."]], ["pm314", 3, ["divided highway", "otowout divize"], ["Kilè ou PA oblije kanpe pou yon bis lekòl ki gen limyè wouj k ap limen etèn?", "Lè w prese", "Lè w pa wè okenn timoun", "Sou nenpòt wout kat vwa", "Lè bis la sou lòt bò yon otowout divize ki gen yon baryè", "Sèl eksepsyon an se yon bis lekòl ki kanpe sou lòt bò yon otowout divize ki gen yon baryè ant de direksyon yo."], ["When are you NOT required to stop for a school bus with flashing red lights?", "When you are in a hurry", "When no children are visible", "On any four-lane road", "When the bus is on the other side of a divided highway with a barrier", "The only exception is a school bus stopped on the other side of a divided highway with a barrier between the directions."]], ["pm315", 0, ["school bus violation", "vyolasyon bis lekòl"], ["Kisa premye vyolasyon lwa sou kanpe pou bis lekòl ka bay?", "Yon sispansyon lisans ak yon amann $250", "Yon avètisman sèlman", "Yon amann $25", "Yon Egzamen Pratik obligatwa", "Premye vyolasyon lwa bis lekòl la ka lakoz yon sispansyon lisans ak yon amann $250."], ["What can a first violation of the school bus stopping law bring?", "A license suspension and a $250 fine", "A warning only", "A $25 fine", "A required road test", "A first violation of the school bus law can cause a license suspension and a $250 fine."]], ["pm316", 1, ["trolley", "trole"], ["Yon trole kanpe epi pasaje ap desann. A ki distans ou ka kondui bò mach pasaje li a?", "De pye", "Pa pi pre pase uit pye", "Nenpòt distans, si w kondui dousman", "Senkant pye", "Ou pa dwe kondui pi pre pase uit pye de mach pasaje yon trole pandan moun ap monte oswa desann. Yon trole pa ka devye pou evite w."], ["A trolley is stopped and passengers are getting off. How close may you drive to its passenger step?", "Two feet", "No closer than eight feet", "Any distance, if you go slowly", "Fifty feet", "You must not drive closer than eight feet to a trolley's passenger step while it is loading or unloading. A trolley cannot swerve to avoid you."]], ["pm317", 3, ["blind spot", "kwen avèg"], ["W ap swiv yon gwo kamyon epi ou pa ka wè miwa sou kote l yo. Kisa sa vle di?", "Ou nan yon bon distans", "Kamyon an pral vire", "Miwa yo kase", "Ou twò pre: chofè a pa ka wè w", "Si w pa ka wè miwa yon kamyon, ou kole twò pre epi w nan kwen avèg li. Kamyon gen kwen avèg sou bò dwat, bò goch, devan ak dèyè."], ["You are following a tractor-trailer and cannot see its side mirrors. What does that mean?", "You are at a safe distance", "The truck is about to turn", "The mirrors are broken", "You are too close: the driver cannot see you", "If you cannot see a truck's rearview mirrors, you are tailgating and in its blind spot. Trucks have blind spots on the right, left, front and behind."]], ["pm318", 2, ["wide turn", "vire laj"], ["Yon kamyon devan w deplase yon ti kras agoch ak siyal dwat li limen. Kisa ou dwe fè?", "Depase l sou bò dwat", "Klaksonnen pou avèti chofè a sou siyal la", "Rete dèyè; l ap louvri pou fè yon vire adwat ki laj", "Vin bò kote l sou bò goch", "Gwo veyikil vire laj epi yo ka ale agoch anvan yo vire adwat. Pa depase sou bò dwat; rete dèyè san danje jiskaske w konnen sa chofè a pral fè."], ["A truck ahead of you moves slightly left with its right signal on. What should you do?", "Pass it on the right", "Honk to warn the driver about the signal", "Stay behind; it is swinging out to make a wide right turn", "Pull up beside it on the left", "Large vehicles make wide turns and may move left before turning right. Do not pass on the right; stay safely behind until you know what the driver is doing."]], ["pm319", 0, ["slow-moving vehicle", "veyikil ki mache dousman"], ["Ou rive dèyè yon traktè fèm ki gen triyang zoranj sa a dèyè l. Kisa ou dwe fè?", "Ralanti, fè atansyon, epi kite anpil espas si w depase", "Depase touswit sou bò wout la", "Klaksonnen jiskaske l rale sou kote", "Swiv li pre pou lòt moun pa koupe devan w", "Yon triyang zoranj make yon veyikil ki mache dousman tankou yon machin fèm oswa konstriksyon. Ralanti, trete l tankou yon siklis, epi kite anpil espas si w depase."], ["You come up behind a farm tractor with this orange triangle on the back. What should you do?", "Slow down, use caution and leave plenty of space if you pass", "Pass immediately on the shoulder", "Honk until it pulls over", "Follow closely so others do not cut in", "An orange triangle marks a slow-moving vehicle such as farm equipment or a construction rig. Slow down, treat it like a bicyclist, and leave plenty of room if you pass."], "smv"], ["pm320", 1, ["funeral procession", "kòtèj fineray"], ["Yon kòtèj fineray ap pase nan yon limyè wouj nan yon kafou pandan limyè pa w la vèt. Kisa ou dwe fè?", "Ale, paske limyè w vèt", "Tann; pa travèse chemen l ni pase ant machin li yo", "Antre nan dènye bout kòtèj la", "Klaksonnen pou avèti yo", "Kòtèj fineray gen dwa de pasaj nan kafou yo. Ou pa ka travèse chemen yo menm ak limyè vèt, pase ant machin yo, ni antre nan kòtèj la."], ["A funeral procession is going through a red light at an intersection while your light is green. What should you do?", "Go, since your light is green", "Wait; do not cross its path or drive between its vehicles", "Join the end of the procession", "Honk to warn them", "Funeral processions have the right-of-way at intersections. You may not cross their path even on a green light, drive between their vehicles, or join the procession."]], ["pm321", 2, ["horse", "cheval"], ["Ou pral depase yon moun ki monte cheval, epi cheval la sanble l pè. Kisa ou dwe fè?", "Klaksonnen pou moun nan konnen ou la", "Depase vit pou sa fini", "Rale sou kote epi kanpe", "Fè limyè w kliyote", "Bay bèt yon moun ap monte oswa mennen dwa de pasaj. Ralanti epi pa klaksonnen. Si bèt la sanble l pè, ou dwe rale sou kote epi kanpe, epi ou dwe kanpe si moun ki sou li a fè w siy."], ["You are about to pass a person riding a horse, and the horse looks scared. What must you do?", "Honk so the rider knows you are there", "Pass quickly to get it over with", "Pull to the side and stop", "Flash your headlights", "Give the right-of-way to animals being ridden or led. Slow down and do not honk. If the animal looks scared, you must pull to the side and stop, and you must stop if the rider signals you to."]], ["pm322", 0, ["aggressive driver", "chofè agresif"], ["Yon chofè agresif ap kole dèyè w epi l ap fè jès malelve. Kisa ou dwe fè?", "Retire kò w nan chemen l, evite gade l nan je, epi pa okipe jès li yo", "Fren sanzatann pou ba l yon leson", "Akselere pou l pa ka swiv ou", "Fè l jès tou", "Eseye retire kò w nan chemen yon chofè agresif. Pa defye l, evite gade l nan je, pa okipe jès malelve yo, epi kenbe senti w mare. Rele 911 pou rapòte yon ijans."], ["An aggressive driver is tailgating you and making rude gestures. What should you do?", "Get out of the way, avoid eye contact and ignore the gestures", "Brake suddenly to teach a lesson", "Speed up so they cannot keep up", "Make a gesture back", "Try to get out of an aggressive driver's way. Do not challenge them, avoid eye contact, ignore rude gestures and keep your seat belt on. Call 911 to report an emergency."]]]},
{"ch": 4, "bp": ["Chapit 3 nan mànyèl la, paj 56–68. Nan egzamen RMV a: sispansyon ak vyolasyon JOL.", "Manual chapter 3, pages 56–68. On the RMV test: suspensions and JOL violations."], "title": ["Vyolasyon ak sispansyon", "Violations and suspensions"], "src": ["S7"], "sections": [{"h": ["Vyolasyon sivil ak kriminèl", "Civil and criminal violations"], "src": ["S7"], "pg": "56–58", "b": [["li", "Vyolasyon sivil, tankou depase limit vitès oswa pa respekte yon siyal, regle ak amann. Ou gen 20 jou pou w peye oswa mande yon odyans (frè $25, yo remèt li si yo jwenn ou pa responsab pou tout vyolasyon yo).", "Civil violations, like speeding or ignoring a signal, are settled with fines. You have 20 days to pay or to request a hearing ($25 filing fee, refunded if you are found not responsible on all violations)."], ["li", "Si w inyore yon kontravansyon pandan 20 jou, yo jwenn ou responsab, yo fè w peye yon frè reta, epi yo ka sispann lisans ou.", "If you ignore a citation for 20 days, you are found responsible, charged a late fee, and your license can be suspended."], ["li", "Vyolasyon kriminèl gen ladan kondui ak yon lisans sispann, kondui anba enfliyans (OUI), ak kite sèn yon aksidan. Yo ka arete w sou plas.", "Criminal violations include driving with a suspended license, operating under the influence (OUI) and leaving the scene of a crash. You can be arrested on the spot."], ["li", "Yo ka arete w si w refize bay non w ak adrès ou, montre lisans oswa anrejistreman w, oswa siyen non w devan yon polisye. Vyolasyon nan lòt eta konte menm jan ak si yo te fèt nan Massachusetts.", "You can be arrested if you refuse to give your name and address, show your license or registration, or sign your name for an officer. Out-of-state violations count as if they happened in Massachusetts."]]}, {"h": ["Amann pou vitès", "Speeding fines"], "src": ["S7"], "pg": "57, 59", "b": [["li", "Pi piti amann pou vitès se $100, plis $5 pou sekirite piblik. Lè w depase limit lan plis pase 10 mph, ajoute $10 pou chak mph anplis. Egzanp mànyèl la: 73 mph nan yon zòn 55 koute $185.", "The lowest speeding fine is $100, plus a $5 public safety surcharge. Above 10 mph over the limit, add $10 for each extra mph. The manual's example: 73 mph in a 55 zone costs $185."], ["li", "Amann pou vitès double nan yon zòn travay ki make.", "Speeding fines are doubled in a posted work zone."], ["li", "Twa vyolasyon vitès nan 12 mwa: sispansyon otomatik 30 jou.", "Three speeding violations within 12 months: automatic 30-day suspension."]]}, {"h": ["Evènman ki ka fè w peye plis ak aksidan kote w an tò", "Surchargeable events and at-fault crashes"], "src": ["S7"], "pg": "58–60, 62", "b": [["li", "Vyolasyon pandan w ap kondui ak aksidan kote w an tò se evènman ki ka fè w peye plis. Yo konte pou sispansyon epi yo fè asirans ou monte.", "Moving violations and at-fault crashes are surchargeable events. They count toward suspension and raise your insurance rate."], ["li", "Anjeneral ou an tò nan yon aksidan kote w frape yon machin pa dèyè, yon aksidan sou move bò wout la, oswa pandan w ap fè bak, pami lòt règ.", "You are usually at fault in a rear-end crash, a crash on the wrong side of the road, or while backing up, among other standards of fault."], ["li", "Twa evènman nan dezan: fè Kou Refòmasyon pou Chofè a nan 90 jou, sinon lisans ou sispann. Sèt nan twazan: sispansyon otomatik 60 jou.", "Three surchargeable events in two years: complete the Driver Retraining course within 90 days or your license is suspended. Seven in three years: automatic 60-day suspension."], ["li", "Moun ki abitye vyole lwa sikilasyon (3 gwo vyolasyon, oswa 12 gwo oswa piti, nan 5 an): sispansyon kat an.", "Habitual traffic offender (3 major violations, or 12 major or minor, within 5 years): four-year suspension."]]}, {"h": ["Sispansyon pou jèn chofè", "Junior operator suspensions"], "src": ["S7"], "pg": "63–65", "b": [["li", "Moun ki gen pèmi, ki poko gen 18 an, epi ki kondui san yon chofè ki gen lisans, oswa pandan restriksyon lannwit lan: 60 jou premye fwa, 180 jou dezyèm fwa, yon ane apre sa, epi yo dwe repase egzamen pèmi a.", "Permit holders under 18 who drive without a licensed driver, or during the night restriction: 60 days the first time, 180 days the second, one year after that, and they must retake the permit exam."], ["li", "Sèvi ak telefòn oswa voye tèks pandan w ap kondui (jèn chofè): 60 jou ak $100 amann premye fwa, plis yon kou refòmasyon atitid chofè ak yon nouvo egzamen pèmi.", "Using a phone or texting while driving (junior operator): 60 days and a $100 fine the first time, plus a Driver Attitudinal Retraining course and a new permit exam."], ["li", "Jèn chofè: vitès 90 jou (apre sa yon ane); kous machin yon ane (apre sa twazan). Gen 180 jou anplis pou vyolasyon tankou OUI, kite sèn aksidan, oswa prete lisans ou. Yo avèti paran yo.", "Junior operators: speeding 90 days (then one year); drag racing one year (then three years). An extra 180 days applies for offenses such as OUI, leaving the scene, or lending your license. Parents are notified."]]}, {"h": ["Lè lisans ou sispann", "When your license is suspended"], "src": ["S7"], "pg": "61–62, 66–68", "b": [["li", "Sispann kondui touswit. Kondui ak yon lisans sispann oswa revoke se yon vyolasyon kriminèl, isit la oswa nan nenpòt lòt eta.", "Stop driving immediately. Driving with a suspended or revoked license is a criminal violation, here or in any other state."], ["li", "Pou w jwenn li ankò, ou peye yon frè reyentegrasyon (souvan $100, jiska $1,200). Apre yon sispansyon dezan oswa plis, ou dwe repase egzamen pèmi a ak Egzamen Pratik la.", "To get it back you pay a reinstatement fee (usually $100, up to $1,200). After a suspension of two years or more, you must pass the permit exam and road test again."], ["li", "Sèvi ak yon fo kat idantite, lisans yon lòt moun, oswa fo enfòmasyon ka lakoz yon sispansyon jiska sis mwa san kondanasyon, ak yon ane apre yon kondanasyon.", "Using a fake ID, someone else's license or false information can bring a suspension of up to six months without a conviction, and one year after a conviction."]]}], "terms": [["civil motor vehicle infraction (CMVI)", "vyolasyon sivil"], ["surchargeable event", "evènman ki ka fè w peye plis"], ["Driver Retraining course", "Kou Refòmasyon pou Chofè"], ["reinstatement fee", "frè reyentegrasyon"], ["revoked", "revoke"]], "qs": [["pm401", 1, ["citation", "kontravansyon"], ["Ou resevwa yon kontravansyon pou yon vyolasyon sivil. Konbyen tan ou genyen pou w peye l oswa mande yon odyans?", "10 jou", "20 jou", "60 jou", "Sis mwa", "Ou gen 20 jou pou w peye oswa mande yon odyans. Si w pa fè anyen, yo jwenn ou responsab, yo fè w peye frè reta, epi yo ka sispann lisans ou."], ["You receive a citation for a civil violation. How long do you have to pay it or request a hearing?", "10 days", "20 days", "60 days", "Six months", "You have 20 days to pay or request a hearing. If you do nothing, you are found responsible, charged a late fee, and your license can be suspended."]], ["pm402", 3, ["hearing", "odyans"], ["Ou mande yon odyans pou w konteste yon kontravansyon sivil. Kisa k ap rive ak frè $25 la si yo jwenn ou pa responsab pou tout vyolasyon yo?", "Yo kenbe l", "Li double", "Li ale nan asirans ou", "Yo remèt ou li", "Mande yon odyans koute $25. Yo remèt ou frè a si tribinal la jwenn ou pa responsab pou tout vyolasyon ki sou kontravansyon an."], ["You request a hearing to dispute a civil citation. What happens to the $25 filing fee if you are found not responsible for all violations?", "It is kept", "It doubles", "It goes toward your insurance", "It is refunded", "A hearing request costs $25. The fee is refunded if the court finds you not responsible for all violations on the citation."]], ["pm403", 0, ["criminal violation", "vyolasyon kriminèl"], ["Kiyès nan sa yo ki yon vyolasyon kriminèl?", "Kite sèn yon aksidan", "Depase limit vitès la 5 mph", "Pa mete siyal", "Yon kontravansyon pakin", "Vyolasyon kriminèl gen ladan kite sèn yon aksidan, kondui anba enfliyans, ak kondui ak lisans sispann. Vitès ak pa mete siyal se vyolasyon sivil."], ["Which of these is a criminal motor vehicle violation?", "Leaving the scene of a crash", "Going 5 mph over the limit", "Failing to signal", "A parking ticket", "Criminal violations include leaving the scene of a crash, operating under the influence and driving with a suspended license. Speeding and failing to signal are civil."]], ["pm404", 2, ["arrest", "arestasyon"], ["Yon polisye kanpe w epi l mande lisans ou. Ou refize montre l. Kisa ki ka rive?", "Anyen, si w pa t ap fè vitès", "Sèlman yon avètisman ekri", "Yo ka arete w epi ou ka fè fas ak akizasyon kriminèl", "Polisye a oblije kite w ale", "Refize bay non ak adrès ou, montre lisans oswa anrejistreman, oswa siyen non w ka mennen nan arestasyon ak akizasyon kriminèl."], ["A police officer stops you and asks for your license. You refuse to show it. What can happen?", "Nothing, if you were not speeding", "Only a written warning", "You can be arrested and face criminal charges", "The officer must let you go", "Refusing to give your name and address, show your license or registration, or sign your name can lead to arrest and criminal charges."]], ["pm405", 1, ["out-of-state violation", "vyolasyon nan lòt eta"], ["Ou jwenn yon kontravansyon vitès nan New Hampshire. Kijan sa afekte dosye w nan Massachusetts?", "Li pa konte nan Massachusetts", "Li konte menm jan ak si l te rive nan Massachusetts", "Li konte sèlman si w te poko gen 18 an", "Li konte sèlman apre twa kontravansyon", "Vyolasyon nan lòt eta afekte dosye w menm jan ak si yo te fèt nan Massachusetts. Si w inyore yo, yo ka sispann lisans ou isit la."], ["You get a speeding ticket in New Hampshire. How does it affect your Massachusetts record?", "It does not count in Massachusetts", "It counts as if it happened in Massachusetts", "It counts only if you were under 18", "It counts only after three tickets", "Out-of-state violations affect your record as if they happened in Massachusetts. Ignoring them can lead to a suspension here."]], ["pm406", 3, ["work zone", "zòn travay"], ["Yo kenbe w ap fè vitès nan yon zòn travay ki make. Kisa k ap rive ak amann lan?", "Li menm jan ak tout lòt kote", "Yo koupe l an de", "Li tounen yon avètisman", "Li double", "Amann pou vitès double nan zòn travay ki make."], ["You are caught speeding in a posted work zone. What happens to the fine?", "It is the same as anywhere else", "It is cut in half", "It becomes a warning", "It is doubled", "Speeding fines are doubled in posted work zones."]], ["pm407", 0, ["speeding fine", "amann vitès"], ["Dapre egzanp mànyèl la, konbyen amann total la ye si w kondui 73 mph kote limit lan se 55 mph?", "$185", "$100", "$73", "$360", "Ou te depase limit lan 18 mph. Nan egzanp mànyèl la, 10 premye mph yo koute $105 (minimòm $100 plis $5 pou sekirite piblik), plis $10 pou chak nan 8 mph ki vin apre yo ($80): $185."], ["Using the manual's example, what is the total fine for driving 73 mph where the limit is 55 mph?", "$185", "$100", "$73", "$360", "You were 18 mph over. In the manual's example the first 10 mph cost $105 (the $100 minimum plus a $5 public safety surcharge), plus $10 for each of the next 8 mph ($80): $185."]], ["pm408", 2, ["speeding violation", "vyolasyon vitès"], ["Ou se yon chofè granmoun yo jwenn responsab pou twa vyolasyon vitès nan 12 mwa. Kisa k ap rive?", "Anyen anplis amann yo", "Yon sispansyon yon ane", "Yon sispansyon otomatik 30 jou", "Ou dwe repase Egzamen Pratik la", "Twa vyolasyon vitès nan 12 mwa bay yon sispansyon otomatik 30 jou. 12 mwa yo kòmanse lè w peye oswa yo jwenn ou responsab pou premye a."], ["You are an adult driver found responsible for three speeding violations within 12 months. What happens?", "Nothing more than the fines", "A one-year suspension", "An automatic 30-day suspension", "You must retake the road test", "Three speeding violations within 12 months bring an automatic 30-day suspension. The 12 months start when you pay or are found responsible for the first one."]], ["pm409", 1, ["surchargeable event", "evènman ki ka fè w peye plis"], ["Kisa yon evènman ki ka fè w peye plis ye?", "Nenpòt vwayaj sou yon wout peyan", "Yon vyolasyon pandan w ap kondui oswa yon aksidan kote w an tò", "Yon kontravansyon pakin", "Renouvle lisans ou an reta", "Vyolasyon pandan w ap kondui ak aksidan kote w an tò se evènman ki ka fè w peye plis. Chak konte pou yon sispansyon posib epi yo ka fè asirans ou monte."], ["What is a surchargeable event?", "Any trip on a toll road", "A moving violation or an at-fault crash", "A parking ticket", "Renewing your license late", "Moving violations and at-fault crashes are surchargeable events. Each one counts toward a possible suspension and can raise your insurance."]], ["pm410", 3, ["Driver Retraining course", "Kou Refòmasyon pou Chofè"], ["Ou gen twa evènman ki ka fè w peye plis nan dezan. Kisa ou dwe fè?", "Anyen; se sèt evènman ki konte", "Peye yon amann $500", "Repase Egzamen Pratik la", "Fè Kou Refòmasyon pou Chofè a nan 90 jou", "Twa evènman nan dezan: fini Kou Refòmasyon pou Chofè a nan 90 jou, sinon lisans ou rete sispann jiskaske w fè l. Sèt evènman nan twazan bay yon sispansyon otomatik 60 jou."], ["You have three surchargeable events within two years. What must you do?", "Nothing; it takes seven events", "Pay a $500 fine", "Retake the road test", "Complete the Driver Retraining course within 90 days", "Three surchargeable events in two years: finish the Driver Retraining course within 90 days, or your license stays suspended until you do. Seven events in three years bring an automatic 60-day suspension."]], ["pm411", 0, ["at-fault crash", "aksidan kote w an tò"], ["Ki aksidan yo konn konte kòm se fòt ou?", "Ou frape machin ki devan w lan pa dèyè", "Yon chofè pase limyè wouj epi l frape w", "Yon moun frape machin ou ki pake", "Yon machin frape w pa dèyè nan yon siy STOP", "Frape yon machin pa dèyè se youn nan règ ki di w an tò. Menm jan pou frape sou move bò wout la, pandan w ap fè bak, oswa frape yon machin ki pake."], ["Which crash is usually counted as your fault?", "You hit the car in front of you from behind", "A driver runs a red light and hits you", "Someone hits your parked car", "A car rear-ends you at a stop sign", "A rear-end collision is one of the standards of fault. So are crashing on the wrong side of the road, while backing up, or into a parked car."]], ["pm412", 2, ["night restriction", "restriksyon lannwit"], ["Yo kenbe yon jèn 17 an ki gen pèmi ap kondui san okenn chofè ki gen lisans nan machin nan. Kisa k ap rive pou premye fwa?", "Yon avètisman sèlman", "Yon amann $25", "Yon sispansyon 60 jou, epi li dwe repase egzamen pèmi a", "Yon sispansyon twazan", "Pou moun ki gen pèmi epi ki poko gen 18 an, kondui san chofè ki gen lisans bay yon sispansyon 60 jou premye fwa (180 jou, apre sa yon ane), epi chak fwa yo dwe repase egzamen pèmi a."], ["A 17-year-old with a permit is caught driving with no licensed driver in the car. What happens for a first offense?", "A warning only", "A $25 fine", "A 60-day suspension, and they must retake the permit exam", "A three-year suspension", "For permit holders under 18, driving without a licensed driver brings a 60-day suspension the first time (180 days, then one year), and every offense requires retaking the permit exam."]], ["pm413", 1, ["Driver Attitudinal Retraining", "kou refòmasyon atitid chofè"], ["Yo kondane yon jèn chofè pou voye tèks pandan l ap kondui, premye fwa. Konbyen tan sispansyon an?", "Okenn, se amann sèlman", "60 jou, plis $100 amann, yon kou refòmasyon ak yon nouvo egzamen pèmi", "Senk an", "Sèt jou", "Jèn chofè: 60 jou premye fwa, 180 jou dezyèm fwa, yon ane apre sa. Premye fwa a gen $100 amann tou, yon kou refòmasyon atitid ak yon nouvo egzamen pèmi."], ["A junior operator is convicted of texting while driving for the first time. What is the suspension?", "None, only a fine", "60 days, plus a $100 fine, a retraining course and a new permit exam", "Five years", "Seven days", "Junior operators: 60 days the first time, 180 days the second, one year after that. The first offense also brings a $100 fine, a Driver Attitudinal Retraining course and a new permit exam."]], ["pm414", 0, ["drag racing", "kous machin"], ["Yo kondane yon jèn chofè pou kous machin premye fwa. Konbyen tan sispansyon an?", "Yon ane", "30 jou", "90 jou", "Pou tout lavi", "Kous machin: yon ane pou premye fwa yon jèn chofè, twazan pou pwochen fwa, plis yon nouvo egzamen pèmi ak refòmasyon."], ["A junior operator is convicted of drag racing for the first time. How long is the suspension?", "One year", "30 days", "90 days", "Lifetime", "Drag racing: one year for a junior operator's first offense, three years for a later one, plus a new permit exam and retraining."]], ["pm415", 3, ["suspended license", "lisans sispann"], ["Lisans ou sispann. Kisa ki vre?", "Ou ka kondui pou w ale travay", "Ou ka kondui nan yon lòt eta", "Ou ka kondui ak yon granmoun ki gen lisans bò kote w", "Ou dwe sispann kondui; si w kondui kounye a se yon vyolasyon kriminèl", "Yon lisans ki sispann oswa revoke pa valab okenn kote. Kondui ak li se yon vyolasyon kriminèl ki ka bay gwo amann oswa prizon."], ["Your license is suspended. What is true?", "You may drive to work", "You may drive in another state", "You may drive with a licensed adult beside you", "You must stop driving; driving now is a criminal violation", "A suspended or revoked license is not valid anywhere. Driving with it is a criminal violation that can bring a large fine or jail."]], ["pm416", 2, ["reinstatement", "reyentegrasyon"], ["Yo te sispann lisans ou pou dezan. Kisa ou dwe fè pou w jwenn li ankò?", "Annik tann; l ap tounen otomatikman", "Peye yon frè sèlman", "Peye frè reyentegrasyon an epi repase egzamen pèmi a ak Egzamen Pratik la", "Fè yon tès vizyon sèlman", "Apre yon sispansyon dezan oswa plis, ou dwe repase egzamen pèmi a ak Egzamen Pratik la, epi peye yon frè reyentegrasyon."], ["Your license was suspended for two years. What must you do to get it back?", "Just wait; it comes back automatically", "Pay a fee only", "Pay the reinstatement fee and pass the permit exam and road test again", "Take a vision test only", "After a suspension of two years or more, you must pass the permit exam and the road test again, and pay a reinstatement fee."]], ["pm417", 1, ["fake ID", "fo kat idantite"], ["Yon moun sèvi ak lisans yon zanmi pou l eseye antre nan yon ba. Menm san kondanasyon, kisa RMV ka fè?", "Anyen san kondanasyon", "Sispann lisans li pou jiska sis mwa", "Bay yon avètisman sèlman", "Retire lisans zanmi an sèlman", "Sèvi ak lisans yon lòt moun oswa yon fo kat idantite ka bay yon sispansyon jiska sis mwa san kondanasyon, ak yon ane apre yon kondanasyon."], ["Someone uses a friend's license to try to get into a bar. Even without a conviction, what can the RMV do?", "Nothing without a conviction", "Suspend their license for up to six months", "Give a warning only", "Take away the friend's license only", "Using someone else's license or a fake ID can bring a suspension of up to six months without a conviction, and one year after a conviction."]]]},
{"ch": 5, "bp": ["Chapit 3 nan mànyèl la, paj 68–75. Nan egzamen RMV a: move itilizasyon alkòl.", "Manual chapter 3, pages 68–75. On the RMV test: alcohol misuse."], "title": ["Alkòl, dwòg ak kondui", "Alcohol, drugs and driving"], "src": ["S7"], "sections": [{"h": ["Kijan alkòl afekte jan w kondui", "How alcohol affects driving"], "src": ["S7"], "pg": "71–72", "b": [["li", "Alkòl se yon depresè. Li ralanti reflèks ou ak tan reyaksyon w, li twouble vizyon ak jijman w, pandan l fè w santi w gen plis konfyans.", "Alcohol is a depressant. It slows your reflexes and reaction time and distorts your vision and judgment, while making you feel more confident."], ["li", "Alkòl fè risk aksidan an senk fwa pi gwo; alkòl ak mariwana fè l douz fwa pi gwo. Alkòl lakoz anviwon 30% lanmò sou wout Etazini.", "Alcohol makes a crash five times more likely; alcohol plus marijuana makes it twelve times more likely. Alcohol causes about 30% of U.S. highway deaths."], ["li", "Si w ap bwè, planifye yon fason san danje pou w rive lakay: yon chofè ki p ap bwè, yon taksi, yon aplikasyon transpò, oswa yon moun nan fanmi oswa yon zanmi.", "If you will drink, plan a safe way home: a designated driver, a taxi, a rideshare app, or a ride from family or friends."]]}, {"h": ["Kantite alkòl nan san (BAC)", "Blood alcohol content (BAC)"], "src": ["S7"], "pg": "72", "b": [["li", "Yon bwat byè 12 ons, yon vè diven 5 ons ak yon ti vè 1.5 ons kleren 80 pwouf gen anviwon menm kantite alkòl. Chak ka fè BAC yon moun nòmal monte anviwon 0.02.", "A 12-ounce beer, a 5-ounce glass of wine and a 1.5-ounce shot of 80-proof liquor hold about the same amount of alcohol. Each can raise an average person's BAC by about 0.02."], ["li", "BAC depann de pwa w, konbyen ou bwè, manje, pandan konbyen tan ou bwè ak kò w. Kalite bwason an pa enpòtan.", "BAC depends on your weight, how much you drank, food, how long you drank and your body. The type of drink does not matter."], ["li", "Se tan sèlman ki retire alkòl. Kafe nwa, yon douch frèt, egzèsis oswa manje pa fè w vin pa sou.", "Only time removes alcohol. Black coffee, a cold shower, exercise or food do not sober you up."]]}, {"h": ["Limit lalwa ak tès chimik", "Legal limits and chemical tests"], "src": ["S7"], "pg": "69–70, 72–73", "b": [["li", "Ou depase limit lalwa a lè BAC ou 0.08 oswa plis. Chofè ki poko gen 21 an jwenn penalite depi 0.02 oswa plis: se lwa zewo tolerans lan.", "You are over the legal limit at a BAC of 0.08 or higher. Drivers under 21 face penalties at 0.02 or higher: the zero-tolerance law."], ["li", "Konsantman implisit: lè w kondui nan Massachusetts, ou dakò fè yon tès souf oswa san si yo arete w pou OUI. Polisye a ka mande yon tès sobriyete sou plas tou.", "Implied consent: by driving in Massachusetts you agree to a breath or blood test if you are arrested for OUI. Officers may also ask for a field sobriety test."], ["li", "Si BAC ou depase limit lan oswa ou refize tès la, polisye a pran lisans ou sou plas. Si w echwe tès la: 30 jou (granmoun), plis 180 jou (18–21 an) oswa plis yon ane (anba 18 an).", "If your BAC is over the limit or you refuse the test, the officer takes your license on the spot. Failed test: 30 days (adults), plus 180 days (ages 18–21) or plus one year (under 18)."], ["li", "Refize tès la san okenn OUI anvan: 180 jou si w gen plis pase 21 an; twazan plis 180 jou pou 18–21 an; twazan plis yon ane si w poko gen 18 an.", "Refusing the test with no prior OUI: 180 days over 21; three years plus 180 days for ages 18–21; three years plus one year under 18."]]}, {"h": ["Penalite pou OUI", "OUI penalties"], "src": ["S7"], "pg": "68", "b": [["li", "Premye kondanasyon OUI: amann $500 a $5,000, jiska 2 an edmi prizon, ak yon sispansyon lisans yon ane (yon pwogram edikasyon sou alkòl ka diminye l).", "First OUI conviction: $500 to $5,000 fine, up to 2½ years in prison, and a one-year license suspension (an alcohol education program may shorten it)."], ["li", "Dezyèm OUI: dezan. Twazyèm: uit an (yon krim grav). Katriyèm: dis an. Senkyèm: pou tout lavi. Menm penalite yo aplike pou kondui anba enfliyans mariwana oswa lòt dwòg.", "Second OUI: two years. Third: eight years (a felony). Fourth: ten years. Fifth: lifetime. The same penalties apply to driving under the influence of marijuana or other drugs."]]}, {"h": ["Anba 21 an: lwa sou alkòl", "Under 21: alcohol laws"], "src": ["S7"], "pg": "73–74", "b": [["li", "Si w poko gen 21 an, li ilegal pou w achte alkòl, fè yon moun achte l pou ou, oswa pote l sof si yon paran oswa gadyen avè w: sispansyon 90 jou a yon ane. Achte oswa eseye achte: 180 jou.", "Under 21, it is illegal to buy alcohol, have someone buy it for you, or carry it unless a parent or guardian is with you: 90 days to one year suspension. Buying or trying to buy: 180 days."], ["li", "Lwa sou veso ki louvri: pa gen okenn bwason alkòl ki louvri anndan machin nan, menm si se yon pasaje ki kenbe l. Amann $100 a $500; anba 21 an, arestasyon ak sispansyon.", "Open container law: no open alcoholic drink anywhere inside the vehicle, even if a passenger holds it. Fine $100 to $500; under 21, arrest and suspension."]]}, {"h": ["Mariwana, medikaman ak lòt dwòg", "Marijuana, medicine and other drugs"], "src": ["S7"], "pg": "74–75", "b": [["li", "Kondui anba enfliyans mariwana toujou yon krim nan Massachusetts. Mariwana ralanti jan w reyaji devan sa k rive sanzatann epi li fè w wè mal lannwit.", "Driving under the influence of marijuana is still a crime in Massachusetts. Marijuana slows your response to sudden events and harms night vision."], ["li", "Medikaman preskripsyon ak medikaman san preskripsyon, tankou anpil medikaman pou grip, alèji oswa doulè, ka ba w dòmi. Yo ka akize w de OUI ak medikaman preskripsyon. Li etikèt yo epi mande yon famasyen.", "Prescription and over-the-counter medicines, like many cold, allergy or pain medicines, can make you drowsy. You can be charged with OUI on prescription drugs. Read labels and ask a pharmacist."], ["li", "Melanje alkòl ak lòt dwòg fè efè yo vin pi grav anpil.", "Mixing alcohol with other drugs makes the effects much worse."]]}], "terms": [["blood alcohol content (BAC)", "kantite alkòl nan san (BAC)"], ["operating under the influence (OUI)", "kondui anba enfliyans (OUI)"], ["implied consent", "konsantman implisit"], ["zero tolerance", "zewo tolerans"], ["open container", "veso ki louvri"]], "qs": [["p11", 1, ["blood alcohol (BAC)", "alkòl nan san (BAC)"], ["Ki limit alkòl nan san (BAC) pou yon chofè ki poko gen 21 an nan Massachusetts?", "0.00%", "0.02%", "0.05%", "0.08%", "Chofè ki poko gen 21 an jwenn penalite depi BAC 0.02 (zewo tolerans). Pou chofè 21 an oswa plis, limit lan se 0.08."], ["What is the blood alcohol limit for a driver under 21 in Massachusetts?", "0.00%", "0.02%", "0.05%", "0.08%", "Drivers under 21 face penalties starting at a BAC of 0.02 (zero tolerance). For drivers 21 and older, the limit is 0.08."]], ["pm501", 3, ["legal limit", "limit lalwa"], ["Pou chofè 21 an oswa plis, nan ki BAC ou depase limit lalwa a?", "0.02", "0.05", "0.10", "0.08", "Ou depase limit lalwa a depi 0.08 oswa plis. Menm yon sèl vè ka afekte jan w kondui."], ["For drivers 21 and older, at what BAC are you over the legal limit?", "0.02", "0.05", "0.10", "0.08", "You are over the legal limit at 0.08 or higher. Even one drink can affect your driving."]], ["pm502", 0, ["standard drink", "yon vè alkòl"], ["Ki bwason ki gen anviwon menm kantite alkòl?", "Yon byè 12 ons, yon vè diven 5 ons ak 1.5 ons kleren 80 pwouf", "Yon byè 12 ons ak yon vè diven 12 ons", "Byè toujou gen mwens alkòl pase kleren, kidonk li pi san danje", "Yon bwason melanje ak soda pa gen efè sou BAC", "Yon byè 12 ons, yon vè diven 5 ons ak 1.5 ons kleren 80 pwouf (menm melanje ak soda) chak gen anviwon mwatye yon ons alkòl. Kalite bwason an pa enpòtan; se kantite a ki enpòtan."], ["Which drinks hold about the same amount of alcohol?", "A 12-ounce beer, a 5-ounce glass of wine and 1.5 ounces of 80-proof liquor", "A 12-ounce beer and a 12-ounce glass of wine", "Beer always has less alcohol than liquor, so it is safer", "A mixed drink with soda has no effect on BAC", "A 12-ounce beer, a 5-ounce glass of wine and a 1.5-ounce serving of 80-proof liquor (even mixed with soda) each hold about half an ounce of alcohol. The type of drink does not matter; the amount does."]], ["pm503", 2, ["sober up", "dezoule"], ["Ki sèl bagay ki retire alkòl nan kò w?", "Kafe nwa", "Yon douch frèt", "Tan", "Manje yon gwo plat", "Fwa w ak ren w bezwen tan pou yo trete alkòl la. Kafe, yon douch frèt, egzèsis oswa manje ka fè w santi w pi reveye, men yo pa bese BAC ou."], ["What is the only thing that removes alcohol from your body?", "Black coffee", "A cold shower", "Time", "Eating a big meal", "Your liver and kidneys need time to process alcohol. Coffee, a cold shower, exercise or food may make you feel more alert but do not lower your BAC."]], ["pm504", 1, ["BAC", "BAC"], ["Anviwon konbyen yon vè alkòl ka fè BAC yon moun nòmal monte?", "0.08", "0.02", "0.10", "Li pa gen efè ou ka mezire", "Chak vè ka fè BAC yon moun nòmal monte anviwon 0.02. Plis pase yon vè pa èdtan fè l monte; se tan sèlman ki fè l desann."], ["About how much can one standard drink raise an average person's BAC?", "0.08", "0.02", "0.10", "It has no measurable effect", "Each standard drink can raise an average person's BAC by about 0.02. More than one drink an hour makes it rise; only time brings it down."]], ["pm505", 0, ["implied consent", "konsantman implisit"], ["Kisa Lwa Konsantman Implisit la vle di?", "Lè w kondui, ou dakò fè yon tès souf oswa san si yo arete w pou OUI", "Lapolis bezwen lòd tribinal pou nenpòt tès", "Ou ka refize san okenn penalite", "Pasaje yo dwe fè tès tou", "Chak chofè ki gen lisans dakò fè yon tès souf oswa san si yo arete l paske yo sispèk OUI. Si w refize, yo sispann lisans ou touswit."], ["What does the Implied Consent Law mean?", "By driving, you agree to a breath or blood test if arrested for OUI", "Police need a court order for any test", "You may refuse with no penalty", "Passengers must also be tested", "Every licensed driver agrees to a breath or blood test if arrested on suspicion of OUI. Refusing brings an immediate license suspension."]], ["pm506", 2, ["chemical test", "tès chimik"], ["Ou gen 30 an, ou pa janm gen OUI, epi ou refize yon tès souf apre yo arete w pou OUI. Pandan konbyen tan lisans ou sispann?", "30 jou", "Pa gen sispansyon", "180 jou", "Pou tout lavi", "Refize yon tès chimik san okenn OUI anvan vle di 180 jou pou chofè ki gen plis pase 21 an. Polisye a pran lisans ou sou plas."], ["You are 30, with no prior OUI, and you refuse a breath test after an OUI arrest. How long is your license suspended?", "30 days", "No suspension", "180 days", "Lifetime", "Refusing a chemical test with no prior OUI means 180 days for drivers over 21. The officer takes your license on the spot."]], ["pm507", 1, ["refusal", "refi"], ["Yon jèn 17 an ki pa janm gen OUI refize yon tès chimik. Konbyen tan sispansyon an?", "180 jou", "Twazan plis yon ane", "30 jou", "Pa gen sispansyon akoz laj li", "Anba 18 an, refize san OUI anvan vle di twazan plis yon ane. Ane anplis la ka desann a 180 jou ak yon pwogram edikasyon sou alkòl apwouve si se premye ka OUI."], ["A 17-year-old with no prior OUI refuses a chemical test. What is the suspension?", "180 days", "Three years plus one year", "30 days", "No suspension because of age", "Under 18, refusing with no prior OUI means three years plus one year. The extra year can be cut to 180 days with an approved alcohol education program if this is a first OUI case."]], ["pm508", 3, ["OUI", "OUI"], ["Konbyen tan yo sispann lisans pou premye kondanasyon OUI?", "30 jou", "Sis mwa", "Pou tout lavi", "Yon ane", "Premye OUI bay yon sispansyon yon ane, amann $500 a $5,000 ak jiska 2 an edmi prizon. Tribinal la ka pèmèt yon pwogram edikasyon sou alkòl pou diminye sispansyon an."], ["What is the license suspension for a first OUI conviction?", "30 days", "Six months", "Lifetime", "One year", "A first OUI brings a one-year suspension, a $500 to $5,000 fine and up to 2½ years in prison. The court may allow an alcohol education program to shorten the suspension."]], ["pm509", 0, ["crash risk", "risk aksidan"], ["Dapre mànyèl la, bwè alkòl fè risk aksidan an konbyen fwa pi gwo?", "Senk fwa", "De fwa", "Li pa chanje risk la si w fè atansyon", "Senkant fwa", "Alkòl fè risk aksidan an senk fwa pi gwo; alkòl ak mariwana ansanm, douz fwa pi gwo."], ["According to the manual, drinking alcohol makes a crash how much more likely?", "Five times", "Twice", "It does not change the risk if you are careful", "Fifty times", "Alcohol makes a crash five times more likely; alcohol combined with marijuana, twelve times more likely."]], ["pm510", 2, ["open container", "veso ki louvri"], ["Pasaje w ki gen 25 an ap kenbe yon bwat byè ki louvri pandan w ap kondui. Kisa ki vre?", "Sa legal paske se pa ou k ap bwè", "Sa legal si bwat la nan yon sache", "Sa ilegal: pa dwe gen okenn alkòl ki louvri anndan machin nan", "Sa ilegal sèlman lannwit", "Ou pa gen dwa gen yon bwason alkòl ki louvri anndan machin nan, menm si se yon lòt moun ki kenbe l. Amann lan se $100 a $500."], ["Your 25-year-old passenger is holding an open can of beer while you drive. What is true?", "It is legal because you are not drinking", "It is legal if the can is in a bag", "It is illegal: no open alcohol may be inside the vehicle", "It is illegal only at night", "You may not have an open alcoholic drink inside the vehicle, even if someone else holds it. The fine is $100 to $500."]], ["pm511", 3, ["underage purchase", "achte anba laj"], ["Yon jèn 19 an eseye achte alkòl. Kisa k ap rive ak lisans li?", "Anyen, paske li pa t ap kondui", "Yon avètisman sèlman", "Yon sispansyon 30 jou", "Yon sispansyon 180 jou", "Anba 21 an, achte oswa eseye achte alkòl bay yon sispansyon lisans 180 jou, menm si pa t gen kondui."], ["A 19-year-old tries to buy alcohol. What happens to their license?", "Nothing, because they did not drive", "A warning only", "A 30-day suspension", "A 180-day suspension", "Under 21, buying or trying to buy alcohol brings a 180-day license suspension, even though no driving was involved."]], ["pm512", 1, ["marijuana", "mariwana"], ["Ki deklarasyon sou mariwana ak kondui nan Massachusetts ki vre?", "Li legal pou w kondui apre w fin sèvi avè l, paske posede l legal", "Kondui anba enfliyans li se yon krim, ak menm penalite ak OUI alkòl", "Li amelyore vizyon lannwit", "Li enpòtan sèlman pou chofè ki poko gen 21 an", "Posede kèk mariwana pa yon krim ankò, men kondui anba enfliyans li toujou yon krim. Tablo penalite OUI a aplike pou mariwana. Li fè w wè mal lannwit tou."], ["Which statement about marijuana and driving in Massachusetts is true?", "It is legal to drive after using it, since it is legal to possess", "Driving under its influence is a crime, with the same penalties as alcohol OUI", "It improves night vision", "It only matters for drivers under 21", "Some marijuana possession is decriminalized, but driving under its influence is still a criminal offense. The OUI penalty chart applies to marijuana. It also harms night vision."]], ["pm513", 0, ["over-the-counter medicine", "medikaman san preskripsyon"], ["Ou pran yon medikaman grip ki di li ka ba w dòmi. Kisa ou dwe fè?", "Pa kondui; ou ka pa an kondisyon e yo ka menm akize w de OUI", "Kondui, paske li pa ilegal", "Bwè kafe epi kondui", "Kondui sèlman sou otowout", "Anpil medikaman pou grip, alèji ak doulè ba w dòmi. Li ilegal pou w kondui lè yon sibstans, menm medikaman preskripsyon oswa san preskripsyon, afekte w."], ["You took a cold medicine that warns it can cause drowsiness. What should you do?", "Not drive; you can be impaired and even charged with OUI", "Drive, since it is not illegal", "Drink coffee and then drive", "Drive only on highways", "Many cold, allergy and pain medicines cause drowsiness. It is illegal to drive impaired by any substance, including prescription and over-the-counter drugs."]], ["pm514", 2, ["failed test", "echwe tès la"], ["Yon jèn 17 an echwe yon tès souf ak BAC 0.03 (premye ka OUI). Konbyen tan sispansyon an?", "Okenn: 0.03 anba limit lan", "Sèt jou", "30 jou plis yon ane (ane a ka desann a 180 jou ak yon pwogram alkòl apwouve)", "Pou tout lavi", "Anba 21 an, yon BAC 0.02 oswa plis bay penalite. Anba 18 an: 30 jou plis yon ane, ki ka desann a 180 jou ak yon pwogram edikasyon sou alkòl DPH apwouve nan yon premye ka OUI."], ["A 17-year-old fails a breath test with a BAC of 0.03 (first OUI case). What is the license suspension?", "None: 0.03 is under the limit", "Seven days", "30 days plus one year (the year can drop to 180 days with an approved alcohol program)", "Lifetime", "Under 21, a BAC of 0.02 or higher brings penalties. Under 18: 30 days plus one year, which can be cut to 180 days with a DPH-approved alcohol education program in a first OUI case."]]]},
{"ch": 6, "bp": ["Chapit 4 nan mànyèl la, paj 80–92. Nan egzamen RMV a: règ wout yo ak idantifye siy wout yo. Desen siy yo swiv estanda federal pou siy (MUTCD).", "Manual chapter 4, pages 80–92. On the RMV test: rules of the road and identifying road signs. Sign drawings follow the federal sign standards (MUTCD)."], "title": ["Limyè sikilasyon, siy ak liy sou wout", "Signals, signs and pavement markings"], "src": ["S7"], "sections": [{"h": ["Limyè sikilasyon", "Traffic lights"], "src": ["S7"], "pg": "80–82", "b": [["li", "Wouj fiks: kanpe. Ou ka vire adwat nan wouj apre w fin kanpe nèt epi bay pyeton ak machin yo dwa de pasaj, sof si gen yon siy NO TURN ON RED. Ou ka vire agoch nan wouj sèlman soti nan yon wout yon sèl sans pou antre nan yon lòt wout yon sèl sans.", "Steady red: stop. You may turn right on red after a complete stop, yielding to pedestrians and traffic, unless a NO TURN ON RED sign is posted. You may turn left on red only from a one-way street onto another one-way street."], ["li", "Wouj k ap limen etèn: menm jan ak yon siy STOP. Jòn fiks: limyè a pral vin wouj; kanpe si w ka fè l san danje. Jòn k ap limen etèn: ralanti epi pase avèk prekosyon.", "Flashing red: same as a STOP sign. Steady yellow: the light is about to turn red; stop if you can do so safely. Flashing yellow: slow down and go with caution."], ["li", "Flèch jòn k ap limen etèn: ou ka vire, men sèlman lè gen yon espas san danje nan machin k ap vini yo epi pa gen pyeton. Flèch vèt: yon vire pwoteje.", "Flashing yellow arrow: you may turn, but only when there is a safe gap in oncoming traffic and no pedestrians. Green arrow: a protected turn."], ["li", "Vèt fiks: ale, men anvan, bay machin, bisiklèt ak pyeton ki deja nan wout la dwa de pasaj, epi pa janm bloke kafou a. Lè w ap vire agoch sou yon limyè vèt won, bay machin k ap vini yo dwa de pasaj.", "Steady green: go, but first yield to vehicles, bicycles and pedestrians already in the road, and never block the intersection. Turning left on a green circle, yield to oncoming traffic."], ["li", "Si yon limyè sikilasyon fin etenn nèt, trete kafou a kòmsi te gen yon siy STOP nan chak direksyon.", "If a signal is completely dark, treat the intersection as if there were a stop sign in every direction."]]}, {"h": ["Siyal ak pasaj pou pyeton", "Pedestrian signals and crossings"], "src": ["S7"], "pg": "82–83", "b": [["li", "Bay pyeton k ap antre oswa ki sou yon pasaj pyeton nan chemen w dwa de pasaj, epi pa janm bloke yon pasaj pyeton.", "Yield to pedestrians entering or using a crosswalk in your path, and never block a crosswalk."], ["li", "Pa janm depase yon machin ki kanpe oswa k ap ralanti pou yon pyeton. Bay pyeton dwa de pasaj lè w ap vire antre nan yon antre kay oswa yon pakin.", "Never pass a vehicle that is stopped or slowing for a pedestrian. Yield to pedestrians when you turn into a driveway or parking lot."], ["li", "Pyeton ki deja nan pasaj la lè kontaj la rive a zewo gen dwa de pasaj.", "Pedestrians already in the crosswalk when the countdown reaches zero have the right-of-way."], ["li", "Yon limyè rektang ki kliyote vit (limyè jòn zoranj ki limen etèn san ritm) vle di kanpe pou pyeton. Nan yon limyè ibrid pou pyeton, wouj fiks vle di kanpe; wouj k ap limen etèn vle di kanpe, apre sa ale si pa gen moun.", "A rectangular rapid flashing beacon (amber lights flashing in an irregular pattern) means stop for pedestrians. At a pedestrian hybrid beacon, solid red means stop; flashing red means stop, then go if clear."]]}, {"h": ["Koulè ak fòm siy yo", "Sign colors and shapes"], "src": ["S7"], "pg": "83–86", "b": [["li", "Wouj: kanpe oswa entèdi. Nwa ak blan: règleman. Jòn: avètisman jeneral. Zoranj: konstriksyon oswa antretyen. Jòn-vèt fliyoresan: avètisman pou lekòl, pyeton, bisiklèt ak koub.", "Red: stop or not allowed. Black and white: regulation. Yellow: general warning. Orange: construction or maintenance. Fluorescent yellow-green: school, pedestrian, bicycle and curve warnings."], ["li", "Vèt: direksyon. Ble: sèvis pou chofè tankou gaz, manje ak lojman. Mawon: pak, lwazi ak sit istorik oswa bèl peyizaj.", "Green: directions. Blue: motorist services such as gas, food and lodging. Brown: parks, recreation and scenic or historic sites."], ["li", "Yon sèk wouj ak yon ba an dyagonal vle di yon bagay entèdi, tankou NO U-TURN (pa fè demi-tou).", "A red circle with a diagonal slash means something is prohibited, such as NO U-TURN."], ["li", "Konnen siy yo pa fòm yo: yon oktagòn uit kote se STOP; yon triyang ki pwent anba se YIELD (bay dwa de pasaj); yon pantagòn senk kote se zòn oswa pasaj lekòl; yon dyaman se yon avètisman; yon siy jòn won avèti gen yon wout tren devan; yon fanyon kouche make yon zòn kote w pa ka depase.", "Know signs by shape: an eight-sided octagon is STOP; a downward triangle is YIELD; a five-sided pentagon is a school zone or crossing; a diamond is a warning; a round yellow sign warns of a railroad crossing ahead; a sideways pennant marks a no-passing zone."], ["li", "Wout leta Massachusetts yo sèvi ak rektang blan ak lèt nwa. Wout entèetatik yo sèvi ak yon pwotèj ble, wouj ak blan.", "Massachusetts state routes use white rectangles with black letters. Interstate routes use a blue, red and white shield."]], "sign": "stop"}, {"h": ["STOP ak YIELD", "STOP and YIELD"], "src": ["S7"], "pg": "86, 91", "b": [["li", "Nan yon siy STOP, kanpe nèt anvan liy stop la oswa pasaj pyeton an. Ralanti sèlman pa ase. Apre sa bay dwa de pasaj epi ale avèk prekosyon.", "At a STOP sign, come to a complete stop before the stop line or crosswalk. Just slowing down is not enough. Then yield and go carefully."], ["li", "Nan yon kafou STOP nan tout direksyon (4-WAY), tout machin kanpe, epi premye machin ki rive nan kafou a pase anvan.", "At an all-way (4-WAY) stop, every vehicle stops, and the first vehicle to reach the intersection goes first."], ["li", "Nan yon siy YIELD, ralanti epi pare pou kanpe. Kite machin, siklis ak pyeton pase anvan, epi kanpe nèt si sikilasyon an mande l. Yon liy yield sanble ak yon ranje triyang.", "At a YIELD sign, slow down and be ready to stop. Let vehicles, bicyclists and pedestrians go first, and stop completely if traffic requires it. A yield line looks like a row of triangles."]], "sign": "yield"}, {"h": ["Wout tren ak zòn travay", "Railroad crossings and work zones"], "src": ["S7"], "pg": "86–89", "b": [["li", "Yon siy avètisman jòn won vini anvan yon wout tren: ralanti epi pare pou kanpe. Kote tren an travèse a make ak yon kwa blan an fòm X. Pa janm eseye pase devan yon tren.", "A round yellow warning sign comes before a railroad crossing: slow down and be ready to stop. The crossing itself is marked with a white X-shaped crossbuck. Never try to beat a train."], ["li", "Lè limyè yo ap limen etèn, kanpe omwen 15 pye de baryè a oswa poto limyè a epi rete kanpe jiskaske baryè a leve epi limyè yo sispann. Pa janm fè wonn yon baryè ki desann.", "When the lights flash, stop at least 15 feet from the gate or light post and stay stopped until the gate rises and the lights stop. Never drive around a lowered gate."], ["li", "Nan yon zòn travay, premye bagay pou w fè se ralanti. Obeyi moun ki gen drapo ak polisye yo, menm lè sa yo di diferan de siy oswa limyè yo.", "In a work zone, the first thing to do is slow down. Obey flaggers and police officers, even when their directions overrule signs or signals."]], "sign": "rr"}, {"h": ["Liy ak mak sou wout la", "Pavement markings"], "src": ["S7"], "pg": "89–92", "b": [["li", "Liy blan separe vwa ki ale menm direksyon. Blan an tire: ou ka travèse l pou chanje vwa apre w fin mete siyal. Blan solid: pa travèse l sof pou evite danje. De liy blan solid: pa janm travèse.", "White lines separate lanes going the same way. Broken white: you may cross it to change lanes after signaling. Solid white: do not cross unless you must avoid danger. Double solid white: never cross."], ["li", "Liy jòn separe machin k ap ale nan direksyon opoze. Ou ka travèse yon liy jòn an tire pou depase lè l san danje. Si yon liy jòn solid sou bò kote w, pa travèse l. De liy jòn solid: pa gen depase; ou ka travèse sèlman pou vire agoch lè l san danje.", "Yellow lines separate traffic going opposite ways. You may cross a broken yellow line to pass when safe. If a solid yellow line is on your side, do not cross it. Double solid yellow: no passing; you may cross only to turn left when safe."], ["li", "Yon dyaman blan make yon vwa espesyal, tankou HOV oswa bis sèlman. Wout wouj se pou bis ak transpò piblik. Vwa bisiklèt yo gen anviwon senk pye lajè; machin ka antre ladan yo sèlman pou vire antre oswa soti nan wout la, apre yo fin gade si gen siklis. Pa kanpe sou wout vèt la nan limyè wouj.", "A white diamond marks a special lane, such as HOV or bus only. Red pavement is for buses and transit. Bike lanes are about five feet wide; cars may enter them only to turn on or off the road, after checking for bicyclists. Do not stop on green pavement at a red light."], ["li", "Pa kondui sou yon zile ki dirije sikilasyon an ni pake sou li sof si yon polisye di w fè l.", "Do not drive over or park on a channelizing island unless a police officer tells you to."]]}], "terms": [["flashing", "k ap limen etèn"], ["crosswalk", "pasaj pyeton"], ["YIELD", "bay dwa de pasaj (YIELD)"], ["crossbuck", "kwa wout tren"], ["work zone", "zòn travay"], ["no-passing zone", "zòn kote w pa ka depase"]], "qs": [["p9", 0, ["flashing red light", "limyè wouj k ap limen etèn"], ["Kisa yon limyè wouj k ap limen etèn vle di?", "Kanpe nèt, apre sa ale lè l san danje", "Ralanti epi pase", "Limyè a pete; pa okipe l", "Kanpe sèlman si gen machin k ap vini", "Yon limyè wouj k ap limen etèn vle di menm bagay ak yon siy STOP: kanpe nèt, swiv règ dwa de pasaj yo, epi ale lè l san danje."], ["What does a flashing red traffic light mean?", "Stop completely, then go when it is safe", "Slow down and go through", "The light is broken; ignore it", "Stop only if cars are coming", "A flashing red light means the same as a STOP sign: come to a complete stop, follow the right-of-way rules, and go when it is safe."]], ["pm601", 2, ["turn on red", "vire nan wouj"], ["Kilè ou ka vire adwat nan yon limyè wouj fiks nan Massachusetts?", "Nenpòt ki lè, si w ralanti", "Pa janm", "Apre w fin kanpe nèt, epi bay pyeton ak machin dwa de pasaj, sof si yon siy entèdi l", "Sèlman lè yon polisye fè w siy", "Ou ka vire adwat nan wouj apre w fin kanpe nèt epi bay pyeton ak lòt machin dwa de pasaj, men pa kote gen yon siy NO TURN ON RED."], ["When may you turn right on a steady red light in Massachusetts?", "Any time, if you slow down", "Never", "After a complete stop, yielding to pedestrians and traffic, unless a sign forbids it", "Only when a police officer waves you on", "Right on red is allowed after a complete stop and yielding to pedestrians and other vehicles, but not where a NO TURN ON RED sign is posted."]], ["pm602", 1, ["one-way street", "wout yon sèl sans"], ["Kilè yo pèmèt vire agoch nan yon limyè wouj nan Massachusetts?", "Pa janm", "Soti nan yon wout yon sèl sans pou antre nan yon lòt wout yon sèl sans, apre w fin kanpe nèt", "Nenpòt lè pa gen machin k ap vini", "Sèlman lannwit", "Ou ka vire agoch nan wouj sèlman soti nan yon wout yon sèl sans pou antre nan yon lòt wout yon sèl sans, apre w fin kanpe epi bay pyeton ak lòt machin dwa de pasaj."], ["When is a left turn on a red light allowed in Massachusetts?", "Never", "From a one-way street onto another one-way street, after a complete stop", "Any time there is no oncoming traffic", "Only at night", "You may turn left on red only from a one-way street onto another one-way street, after stopping and yielding to pedestrians and other vehicles."]], ["pm603", 3, ["steady yellow", "jòn fiks"], ["Limyè devan w lan vin jòn fiks. Kisa ou dwe fè?", "Akselere pou w pase", "Ale, paske jòn vle di prekosyon sèlman", "Kanpe menm si w deja nan kafou a", "Kanpe si w ka fè l san danje", "Yon jòn fiks vle di limyè a ap chanje soti vèt pou l vin wouj. Kanpe si l san danje. Si w deja kanpe, ou pa ka ale."], ["The light ahead turns steady yellow. What should you do?", "Speed up to get through", "Go, because yellow means caution only", "Stop even if you are already in the intersection", "Stop if you can do so safely", "A steady yellow means the light is changing from green to red. Stop if it is safe. If you are already stopped, you may not go."]], ["pm604", 0, ["flashing yellow", "jòn k ap limen etèn"], ["Kisa yon limyè jòn k ap limen etèn vle di?", "Ralanti epi pase avèk prekosyon", "Kanpe epi tann vèt", "Wout la fèmen", "Pyeton yo dwe kanpe", "Yon jòn k ap limen etèn se yon avètisman: pase avèk prekosyon, rete vijilan epi gade de bò nan kafou a."], ["What does a flashing yellow light mean?", "Slow down and go with caution", "Stop and wait for green", "The road is closed", "Pedestrians must stop", "A flashing yellow is a warning: proceed with caution, stay alert and look both ways at the intersection."]], ["pm605", 2, ["flashing yellow arrow", "flèch jòn k ap limen etèn"], ["Ou vle vire agoch epi ou wè yon flèch jòn k ap limen etèn. Kisa sa vle di?", "Machin k ap vini yo dwe kanpe pou ou", "Yo pa pèmèt vire agoch", "Ou ka vire lè gen yon espas san danje epi pa gen pyeton, ou bay machin k ap vini yo dwa de pasaj", "Ou dwe vire vit anvan limyè a chanje", "Yon flèch jòn k ap limen etèn pèmèt ou vire pandan machin k ap vini yo gen limyè vèt, sèlman lè gen ase espas epi pa gen pyeton nan chemen w."], ["You want to turn left and see a flashing yellow arrow. What does it mean?", "Oncoming traffic must stop for you", "Left turns are not allowed", "You may turn when there is a safe gap and no pedestrians, yielding to oncoming traffic", "You must turn quickly before the light changes", "A flashing yellow arrow lets you turn while oncoming traffic has a green light, only when there is an adequate gap and no pedestrians in your path."]], ["pm606", 1, ["dark signal", "limyè etenn"], ["Ou rive nan yon kafou kote limyè sikilasyon yo etenn nèt. Kisa ou dwe fè?", "Pase; ou gen dwa de pasaj", "Aji kòmsi gen yon siy STOP nan tout direksyon", "Desann a 20 mph epi kontinye", "Fè demi-tou", "Si limyè yo etenn nèt, fè atansyon epi aji kòmsi gen yon siy STOP nan tout direksyon. Si yo ap limen etèn, swiv règ pou limyè k ap limen etèn yo."], ["You reach an intersection where the traffic lights are completely dark. What should you do?", "Go through; you have the right-of-way", "Act as if there is a stop sign in all directions", "Slow to 20 mph and continue", "Turn around", "If signals are blacked out, be cautious and proceed as though there is a stop sign in all directions. If they flash, follow the rules for flashing lights."]], ["pm607", 3, ["oncoming traffic", "machin k ap vini"], ["W ap vire agoch sou yon limyè vèt won fiks (san flèch). Kiyès ou dwe bay dwa de pasaj?", "Pèsonn; vèt vle di ale", "Sèlman ak bis", "Sèlman ak machin dèyè w", "Machin k ap vini yo ak pyeton ki nan chemen w", "Sou yon limyè vèt won, vire agoch pa pwoteje: bay machin k ap vini ak pyeton yo dwa de pasaj, epi pa janm bloke kafou a."], ["You are turning left on a steady green circle (no arrow). Who must you yield to?", "No one; green means go", "Only to buses", "Only to vehicles behind you", "Oncoming traffic and pedestrians in your path", "On a green circle, a left turn is not protected: yield to oncoming traffic and pedestrians, and never block the intersection."]], ["pm608", 0, ["pedestrian beacon", "limyè pou pyeton"], ["Nan yon pasaj pyeton nan mitan yon blòk, limyè jòn zoranj ap limen etèn vit san ritm. Kisa ou dwe fè?", "Kanpe pou pyeton yo", "Akselere anvan yon moun travèse", "Klaksonnen epi kontinye", "Pa okipe l sof si gen yon limyè wouj tou", "Se yon limyè rektang ki kliyote vit. Yon pyeton limen l: ou dwe kanpe pou pyeton pandan l ap limen etèn."], ["At a mid-block crosswalk, amber lights are flashing rapidly in an irregular pattern. What must you do?", "Stop for pedestrians", "Speed up before someone steps out", "Honk and continue", "Ignore it unless there is also a red light", "That is a rectangular rapid flashing beacon. A pedestrian has activated it: you must stop for pedestrians while it flashes."]], ["pm609", 2, ["countdown timer", "kontaj"], ["Kontaj pyeton an rive a zewo pandan yon moun toujou nan pasaj la. Kiyès ki gen dwa de pasaj?", "Ou menm, paske limyè w vèt", "Moun ki klaksonnen anvan", "Pyeton ki deja nan pasaj la", "Machin k ap vire yo sèlman", "Pyeton ki deja nan pasaj la lè kontaj la rive a zewo gen dwa de pasaj. Kite yo fin travèse."], ["The pedestrian countdown reaches zero while a person is still in the crosswalk. Who has the right-of-way?", "You, because your light is green", "Whoever honks first", "The pedestrian already in the crosswalk", "Turning vehicles only", "Pedestrians who are already in the crosswalk when the countdown reaches zero have the right-of-way. Let them finish crossing."]], ["pm610", 1, ["crosswalk", "pasaj pyeton"], ["Machin ki nan vwa bò kote w lan kanpe nan yon pasaj pyeton. Kisa ou dwe fè?", "Depase l avèk prekosyon", "Ralanti epi kanpe: pa janm depase yon machin ki kanpe pou yon pyeton", "Klaksonnen pou avèti pyeton an", "Chanje vwa epi kontinye", "Yon machin ki kanpe ka ap kache yon pyeton. Pa janm depase yon machin ki kanpe oswa k ap ralanti pou yon pyeton."], ["The car in the lane next to you has stopped at a crosswalk. What should you do?", "Pass it carefully", "Slow down and stop: never pass a vehicle stopped for a pedestrian", "Honk to warn the pedestrian", "Change lanes and continue", "A stopped car may be hiding a pedestrian. Never pass a vehicle that is stopped or slowing for a pedestrian."]], ["pm611", 3, ["orange sign", "siy zoranj"], ["Kisa siy zoranj yo vle di?", "Sèvis pou chofè", "Zòn lwazi", "Zòn lekòl", "Konstriksyon oswa antretyen devan", "Siy zoranj avèti gen travay konstriksyon oswa antretyen. Ralanti epi veye travayè yo."], ["What do orange signs mean?", "Motorist services", "Recreation areas", "School zones", "Construction or maintenance ahead", "Orange signs warn of construction or maintenance work. Slow down and watch for workers."], "work"], ["pm612", 0, ["brown sign", "siy mawon"], ["Yon siy mawon anjeneral montre w:", "Yon pak, yon zòn lwazi oswa yon sit istorik", "Yon lopital", "Yon sòti otowout", "Yon detou konstriksyon", "Siy mawon mennen nan zòn lwazi piblik, pak leta ak nasyonal, kote enteresan ak bèl peyizaj. Siy ble montre sèvis; siy vèt bay direksyon."], ["A brown sign usually points you to:", "A park, recreation area or historic site", "A hospital", "A highway exit", "A construction detour", "Brown signs lead to public recreation areas, state and national parks, points of interest and scenic sites. Blue signs show services; green signs give directions."]], ["pm613", 1, ["prohibited", "entèdi"], ["Kisa siy sa a vle di?", "Ou ka fè demi-tou pi devan", "Pa fè demi-tou", "Wout la fè yon koub sere", "Detou devan", "Yon sèk wouj ak yon ba an dyagonal vle di aksyon ki montre a entèdi. Isit la: pa fè demi-tou."], ["What does this sign mean?", "U-turn allowed ahead", "No U-turn", "Road curves sharply", "Detour ahead", "A red circle with a diagonal slash means the action shown is prohibited. Here: no U-turns."], "nouturn"], ["pm614", 3, ["STOP sign", "siy STOP"], ["Ou rive devan siy sa a. Kisa ou dwe fè?", "Ralanti epi pase si pa gen moun k ap vini", "Kanpe sèlman si gen yon pyeton k ap tann", "Kanpe nan mitan pasaj pyeton an", "Kanpe nèt anvan liy stop la oswa pasaj pyeton an, bay dwa de pasaj, apre sa ale avèk prekosyon", "Siy wouj uit kote a toujou vle di kanpe nèt, anvan pasaj pyeton oswa liy stop la. Ralanti sèlman pa ase."], ["You come to this sign. What must you do?", "Slow down and go if no one is coming", "Stop only if a pedestrian is waiting", "Stop in the middle of the crosswalk", "Come to a complete stop before the stop line or crosswalk, yield, then go carefully", "The eight-sided red sign always means a complete stop, before any crosswalk or stop line. Just slowing down is not enough."], "stop"], ["pm615", 2, ["school zone", "zòn lekòl"], ["Ki sa siy senk kote sa a avèti w?", "Yon wout tren", "Yon zòn lopital", "Yon zòn lekòl oswa yon pasaj lekòl", "Yon zòn kote w pa ka depase", "Fòm pantagòn nan make yon zòn oswa yon pasaj lekòl. Limit vitès toupre lekòl se 20 mph; veye timoun ak gad travèse yo."], ["What does this five-sided sign warn you about?", "A railroad crossing", "A hospital zone", "A school zone or school crossing", "A no-passing zone", "The pentagon shape marks a school zone or school crossing. The speed limit near schools is 20 mph; watch for children and crossing guards."], "school"], ["pm616", 0, ["railroad crossing", "wout tren"], ["Ou wè siy jòn won sa a. Kisa ki devan?", "Yon wout tren: ralanti epi pare pou kanpe", "Yon kafou won", "Yon lopital", "Yon kafou ak yon siy STOP", "Yon siy avètisman won konn vini anvan yon wout tren. Ralanti, gade epi koute, epi pa janm eseye pase devan yon tren."], ["You see this round yellow sign. What is ahead?", "A railroad crossing: slow down and be ready to stop", "A traffic circle", "A hospital", "A crossroad with a stop sign", "A round warning sign usually comes before a railroad crossing. Slow down, look and listen, and never try to beat a train."], "rr"], ["pm617", 1, ["warning sign", "siy avètisman"], ["Kisa siy jòn an fòm dyaman sa a vle di?", "Vire adwat kounye a", "Wout la fè yon koub adwat pi devan: ralanti", "Vwa dwat la fini", "Pa vire adwat", "Siy jòn an fòm dyaman avèti gen danje oswa chanjman pi devan. Sa a avèti wout la fè yon koub adwat. Ralanti epi obeyi siy la."], ["What does this yellow diamond sign mean?", "Turn right now", "The road curves to the right ahead: slow down", "Right lane ends", "No right turn", "Yellow diamond signs warn of hazards or changes ahead. This one warns that the road curves right. Slow down and obey the sign."], "curve"], ["pm618", 2, ["all-way stop", "STOP nan tout direksyon"], ["Nan yon kafou STOP nan kat direksyon, de machin rive nan lè diferan. Kiyès ki pase anvan?", "Machin ki pi gwo a", "Machin k ap ale tou dwat la", "Premye machin ki rive nan kafou a", "Machin ki sou bò goch la", "Nan yon kafou STOP nan tout direksyon (4-WAY), chak machin dwe kanpe, epi premye machin ki rive nan kafou a gen dwa de pasaj."], ["At a four-way stop, two cars arrive at different times. Who goes first?", "The larger vehicle", "The car going straight", "The first car to reach the intersection", "The car on the left", "At an all-way (4-WAY) stop, every vehicle must stop, and the first vehicle to reach the intersection has the right-of-way."]], ["pm619", 3, ["YIELD sign", "siy YIELD"], ["Kisa siy sa a mande?", "Kanpe nèt chak fwa", "Akselere pou w antre", "Anyen, si w ap vire adwat", "Ralanti, kite lòt yo pase anvan, epi kanpe si sikilasyon an mande l", "Nan yon siy YIELD, ralanti epi pare pou kanpe. Kite machin, siklis ak pyeton pase anvan w, epi kanpe nèt si sikilasyon an mande l."], ["What does this sign require?", "A complete stop every time", "Speed up to merge", "Nothing, if you are turning right", "Slow down, let others go first, and stop if traffic requires it", "At a YIELD sign, slow down and be ready to stop. Let vehicles, bicyclists and pedestrians go before you, and stop completely if traffic requires it."], "yield"], ["pm620", 1, ["railroad gate", "baryè wout tren"], ["Limyè yo ap limen etèn nan yon wout tren. Ki kote ou dwe kanpe?", "Dirèkteman sou ray yo", "Omwen 15 pye de baryè a oswa poto limyè a", "Ou ka fè wonn baryè a si w pa wè tren", "Senk pye de ray yo", "Kanpe omwen 15 pye anvan poto limyè a oswa baryè a epi rete kanpe jiskaske baryè a leve epi limyè yo sispann. Pa janm fè wonn yon baryè ki desann."], ["The lights are flashing at a railroad crossing. Where must you stop?", "Right on the tracks", "At least 15 feet from the gate or light post", "You may drive around the gate if no train is visible", "Five feet from the tracks", "Stop at least 15 feet before the light post or gate and stay stopped until the gate rises and the lights stop. Never drive around a lowered gate."]], ["pm621", 0, ["work zone", "zòn travay"], ["W ap pwoche yon zòn travay. Ki premye bagay ou dwe fè?", "Ralanti", "Chanje vwa touswit", "Limen gwo limyè ou", "Gade travay y ap fè a", "Premye bagay pou w fè nan yon zòn travay se ralanti, apre sa gade enstriksyon pou w pase san danje. Pa kite travay la distrè w."], ["You are approaching a work zone. What is the first thing you must do?", "Slow down", "Change lanes immediately", "Turn on your high beams", "Look at the work being done", "The first thing to do in a work zone is slow down, then look for guidance on how to get through safely. Do not be distracted by the work."]], ["pm622", 3, ["flagger", "moun ki gen drapo"], ["Yon polisye k ap dirije sikilasyon an fè w siy pase nan yon limyè wouj. Kisa ou fè?", "Tann limyè vèt la", "Klaksonnen pou mande l si l sèten", "Vire adwat pito", "Swiv enstriksyon polisye a", "Ou dwe toujou obeyi yon polisye sikilasyon oswa moun ki gen drapo, menm lè sa yo di diferan de siy, limyè oswa liy sou wout la."], ["A police officer directing traffic waves you through a red light. What do you do?", "Wait for the green light", "Honk to ask if he is sure", "Turn right instead", "Follow the officer's direction", "You must always obey a traffic officer or flagger, even when their directions overrule signs, signals or pavement markings."]], ["pm623", 2, ["broken white line", "liy blan an tire"], ["Kisa yon liy blan an tire ant de vwa vle di?", "Machin yo ale nan direksyon opoze", "Ou pa janm ka travèse l", "Machin yo ale menm direksyon; ou ka travèse l pou chanje vwa lè l san danje, apre w fin mete siyal", "Li make yon vwa bis", "Liy blan an tire separe vwa ki ale menm direksyon. Lè w fin mete siyal epi l san danje, ou ka travèse pou chanje vwa."], ["What does a broken white line between two lanes mean?", "Traffic goes in opposite directions", "You may never cross it", "Traffic goes the same way; you may cross it to change lanes when safe, after signaling", "It marks a bus lane", "Broken white lines separate lanes going the same direction. Once you have signaled and it is safe, you may cross to change lanes."]], ["pm624", 1, ["double solid yellow", "de liy jòn solid"], ["Kilè ou ka travèse de liy jòn solid?", "Pou depase yon machin k ap mache dousman", "Sèlman pou vire agoch, lè l san danje", "Nenpòt lè pa gen machin k ap vini", "Pa janm", "De liy jòn solid entèdi depase. Ou ka travèse yo sèlman pou vire agoch lè l san danje."], ["When may you cross double solid yellow lines?", "To pass a slow vehicle", "Only to turn left, when it is safe", "Any time there is no oncoming traffic", "Never", "Two solid yellow lines prohibit passing. You may cross them only to turn left when it is safe."]], ["pm625", 0, ["solid yellow line", "liy jòn solid"], ["Gen yon liy jòn solid sou bò kote w ak yon liy jòn an tire sou lòt bò a. Èske w ka depase?", "Non; ou pa ka travèse lè liy solid la sou bò kote w", "Wi, si wout la klè", "Wi, men sèlman lannwit", "Wi, si w anba limit vitès la", "Si liy jòn solid la pi pre w, ou pa ka travèse. Si liy an tire a pi pre w, ou ka travèse pou depase lè l san danje."], ["There is a solid yellow line on your side and a broken yellow line on the other side. May you pass?", "No; you may not cross when the solid line is on your side", "Yes, if the road is clear", "Yes, but only at night", "Yes, if you are going under the limit", "If the solid yellow line is closer to you, you cannot cross. If the broken line is closer to you, you may cross to pass when it is safe."]], ["pm626", 3, ["bicycle lane", "vwa bisiklèt"], ["Kilè yon machin ka kondui nan yon vwa bisiklèt ki make?", "Pou depase sikilasyon ki lan", "Pou pake kèk minit", "Nenpòt lè pa gen bisiklèt", "Sèlman lè w ap vire antre oswa soti nan wout la, apre w fin gade si gen siklis", "Machin yo ka sèvi ak yon vwa bisiklèt sèlman lè y ap vire antre oswa soti nan wout la. Gade byen si gen siklis epi travèse avèk prekosyon."], ["When may a car drive in a marked bicycle lane?", "To pass slow traffic", "To park for a few minutes", "Any time no bicycles are there", "Only when turning on or off the road, after checking for bicyclists", "Motor vehicles may use a bike lane only when turning on or off the road. Look carefully for bicyclists and cross with care."]], ["pm627", 2, ["high occupancy vehicle (HOV)", "veyikil ak plizyè pasaje (HOV)"], ["Gen yon dyaman blan pentire nan yon vwa. Kisa sa vle di?", "Vwa a pral fini", "Wout tren devan", "Yon vwa espesyal, tankou HOV oswa bis sèlman", "Yon vwa pou depase", "Yon dyaman blan vle di yon vwa ki gen restriksyon espesyal, tankou machin ak plizyè pasaje sèlman (kovwatiraj) oswa bis sèlman."], ["A white diamond is painted in a lane. What does it mean?", "The lane ends soon", "Railroad crossing ahead", "A special lane, such as HOV or bus only", "A passing lane", "A white diamond means a special lane restriction, like high-occupancy vehicles (carpools) only or buses only."]], ["pm628", 0, ["yield line", "liy yield"], ["Kijan yon liy yield pentire atravè wout la sanble?", "Yon ranje triyang", "Yon sèl liy blan solid", "Yon liy jòn doub", "Yon dyaman blan", "Yon liy yield sanble ak yon seri triyang pentire youn bò lòt. Yon liy stop se yon sèl liy blan solid. Kanpe dèyè yo lè yon siy, yon limyè oswa yon pyeton mande l."], ["What does a yield line painted across the road look like?", "A row of triangles", "A single solid white line", "A double yellow line", "A white diamond", "A yield line looks like a series of triangles painted side by side. A stop line is one solid white line. Stop behind them when a sign, signal or pedestrian requires it."]]]},
{"ch": 7, "bp": ["Chapit 4 nan mànyèl la, paj 78–80 ak 93–111. Nan egzamen RMV a: règ wout yo.", "Manual chapter 4, pages 78–80 and 93–111. On the RMV test: rules of the road."], "title": ["Vitès, vwa, vire ak dwa de pasaj", "Speed, lanes, turns and right-of-way"], "src": ["S7"], "sections": [{"h": ["Limit vitès", "Speed limits"], "src": ["S7"], "pg": "78–80", "b": [["li", "Lwa debaz sou vitès: pa janm kondui pi vit pase sa ki san danje pou sikilasyon, wout, tan ak vizibilite, menm anba limit ki afiche a. Kondui 40 mph nan yon gwo lapli sou yon otowout 50 mph ka fè w jwenn yon kontravansyon.", "The basic speed law: never drive faster than is safe for traffic, road, weather and visibility, even below the posted limit. Driving 40 mph in a heavy rainstorm on a 50 mph highway can get you a ticket."], ["li", "Sof si yon siy di yon lòt bagay: 20 mph nan yon zòn lekòl, 30 mph nan yon zòn ki gen anpil kay oswa zòn biznis (25 mph nan kèk vil), 40 mph andeyò zòn sa yo, ak 50 mph sou yon otowout andeyò yo. Otowout entèetatik yo gen limit 50 a 65 mph.", "Unless posted otherwise: 20 mph in a school zone, 30 mph in a thickly settled or business district (25 mph in some towns), 40 mph outside those districts, and 50 mph on a highway outside them. Interstates are posted 50 to 65 mph."], ["li", "Yon zòn ki gen anpil kay se kote bilding yo mwens pase 200 pye youn de lòt sou yon ka mil oswa plis. Vitès minimòm: 40 mph sou Massachusetts Turnpike ak 20 mph nan tinèl Boston Harbor yo.", "A thickly settled district has buildings less than 200 feet apart for a quarter mile or more. Minimum speeds: 40 mph on the Massachusetts Turnpike and 20 mph in the Boston Harbor tunnels."], ["li", "Vitès touye pyeton: si yon machin frape yo a 20 mph, 13% blese grav oswa mouri; a 30 mph, 40%; a 40 mph, 73%.", "Speed kills pedestrians: hit at 20 mph, 13% are seriously injured or killed; at 30 mph, 40%; at 40 mph, 73%."]]}, {"h": ["Siyal, vwa ak otowout", "Signals, lanes and highways"], "src": ["S7"], "pg": "93–96", "b": [["li", "Mete siyal pou chanje vwa, vire, soti oswa rale bò twotwa a, ak antre oswa soti sou otowout. Anvan nenpòt mouvman: gade miwa yo ak kwen avèg la, mete siyal, apre sa fè mouvman an. Etenn siyal la apre.", "Signal to change lanes, turn, pull away from or over to the curb, and enter or exit a highway. Before any move: check mirrors and blind spot, signal, then move. Turn the signal off afterward."], ["li", "Si siyal yo pa mache, fè siyal ak men nan fenèt chofè a: bra lonje tou dwat pou vire agoch, bra pliye anlè pou vire adwat, bra pliye anba pou ralanti oswa kanpe.", "If your signals do not work, use hand signals through the driver's window: arm straight out for a left turn, arm bent up for a right turn, arm bent down to slow or stop."], ["li", "Sou wout ki gen de vwa oswa plis nan direksyon w, kondui nan vwa dwat la sof si w ap depase, w ap vire agoch, oswa vwa a bloke. Pa janm chanje vwa nan mitan yon kafou.", "On roads with two or more lanes your way, drive in the right lane unless you are passing, turning left, or the lane is blocked. Never change lanes in an intersection."], ["li", "Otowout: bay machin ki deja sou otowout la dwa de pasaj epi mache menm vitès ak yo lè w ap antre. Mete siyal omwen 500 pye anvan yon sòti. Si w rate sòti w, pa janm kanpe ni fè bak: pran pwochen an. Ak twa vwa oswa plis, vwa dwat la pi lan, vwa mitan an pi vit, vwa goch la pou depase.", "Highways: yield to traffic already on the highway and match its speed when you enter. Signal at least 500 feet before an exit. If you miss your exit, never stop or back up: take the next one. With three or more lanes, the right lane is slower, the middle faster, the left for passing."], ["li", "Nan yon long vwayaj, kanpe epi detire w chak dezè oswa chak 100 mil. Si machin nan tonbe an pàn sou otowout, rale toutotan ou kapab lwen machin yo epi rete andedan machin ou.", "On a long drive, stop and stretch every two hours or 100 miles. If you break down on a highway, move as far from traffic as you can and stay in your vehicle."]]}, {"h": ["Vire", "Turns"], "src": ["S7"], "pg": "97–99", "b": [["li", "Mete siyal omwen 100 pye anvan yon vire, oswa 500 pye sou otowout. Ralanti, gade miwa ak kwen avèg ou, bay dwa de pasaj lè sa nesesè, epi vire antre nan bon vwa a.", "Signal at least 100 feet before a turn, or 500 feet on a highway. Slow down, check mirrors and your blind spot, yield when needed, and turn into the proper lane."], ["li", "Vire adwat soti nan vwa ki pi adwat la, epi agoch soti nan vwa ki pi pre mitan an. Pa louvri twò laj. Lè w kòmanse yon vire, fini l.", "Turn right from the far right lane and left from the lane closest to the center. Do not swing wide. Once you start a turn, finish it."], ["li", "Demi-tou sèlman soti nan vwa ki pi pre liy mitan an, pa janm kote ou menm oswa lòt moun pa ka wè 500 pye, e pa janm kote gen yon siy NO U-TURN. Ou pa ka kondui tou dwat nan yon vwa mitan ki pou vire agoch.", "U-turns only from the lane closest to the center line, never where you or others cannot see 500 feet, and never where a NO U-TURN sign is posted. You may not drive along in a shared center left-turn lane."]]}, {"h": ["Dwa de pasaj", "Right-of-way"], "src": ["S7"], "pg": "99–101", "b": [["li", "Toujou bay pyeton ki nan wout la dwa de pasaj, ansanm ak sa ki deja nan pasaj la lè limyè w vin vèt. Kanpe pou yon pyeton avèg ki gen yon baton blan oswa yon chen gid epi rete kanpe jiskaske l travèse; pa klaksonnen ni fè l siy pase (Lwa Baton Blan an).", "Always yield to pedestrians in the roadway, including those already in the crosswalk when your light turns green. Stop for a blind pedestrian with a white cane or guide dog and stay stopped until they cross; do not honk or wave them on (the White Cane Law)."], ["li", "Nan yon kafou ki pa gen siy ni limyè, bay machin k ap vini sou bò dwat ou dwa de pasaj. Nan yon kafou STOP nan kat direksyon, pase nan lòd nou kanpe a; si de rive ansanm, bay machin sou bò dwat ou a dwa de pasaj.", "At an intersection with no signs or signals, yield to vehicles coming from your right. At a four-way stop, go in the order you stopped; if two arrive together, yield to the vehicle on your right."], ["li", "Lè w ap vire agoch, bay machin k ap vini, machin ki deja nan kafou a, ak pyeton oswa siklis ki nan chemen w dwa de pasaj. Lè w ap soti nan yon antre kay, yon wout prive oswa yon wout tè, kanpe epi bay dwa de pasaj. Yon wout de vwa ki rankontre yon otowout divize oswa yon wout twa vwa oswa plis dwe bay dwa de pasaj.", "Turning left, yield to oncoming vehicles, vehicles already in the intersection, and pedestrians or bicyclists in your path. Coming out of a driveway, private road or unpaved road, stop and yield. A two-lane road meeting a divided highway or a road with three or more lanes must yield."], ["li", "Aksidan politès: si yon moun fè w siy pase nan mitan machin ki kanpe, machin k ap vini yo toujou gen dwa de pasaj. Vire sèlman lè w wè wout la klè.", "Courtesy crashes: if someone waves you through stopped traffic, oncoming traffic still has the right-of-way. Turn only when you can see it is clear."]]}, {"h": ["Kafou won ak wonpwen piti", "Rotaries and roundabouts"], "src": ["S7"], "pg": "101–102", "b": [["li", "Sikilasyon nan yon kafou won fè wonn nan sans kontrè egui yon revèy. Bay machin ki deja nan kafou won an ak pyeton yo dwa de pasaj, epi sèvi ak siyal dwat ou pou w soti.", "Traffic in a rotary moves counterclockwise. Yield to vehicles already in the rotary and to pedestrians, and use your right signal to exit."], ["li", "Kafou won ak plizyè vwa san siy: pou fè yon ka vire oswa ale tou dwat, antre nan vwa dwat la epi rete adwat. Pou fè twa ka vire oswa demi-tou, antre nan vwa goch la, kondui nan vwa anndan an, epi soti nan vwa dwat la.", "Multi-lane rotary with no signs: to go a quarter turn or straight, enter from the right lane and stay right. For a three-quarter turn or U-turn, enter from the left lane, travel in the inner lane, and exit to the right lane."], ["li", "Ou rate sòti w? Fè yon lòt wonn. Pa janm kanpe nan yon kafou won. Wonpwen piti yo (roundabouts) pi piti epi yo mande vitès 25 mph oswa mwens.", "Missed your exit? Go around again. Never stop in a rotary. Roundabouts are smaller and need speeds of 25 mph or less."]]}, {"h": ["Depase", "Passing"], "src": ["S7"], "pg": "102–104", "b": [["li", "Depase sou bò goch, sèlman lè sa nesesè epi san danje, e pa janm pi vit pase limit vitès la. Pa janm depase sou bò wout la, nan vwa pàn nan oswa sou twotwa.", "Pass on the left, only when necessary and safe, and never above the speed limit. Never pass on a shoulder, breakdown lane or sidewalk."], ["li", "Lè w travèse yon liy jòn an tire pou depase, ou dwe ka wè omwen 400 pye devan. Retounen nan vwa w lè w ka wè limyè devan machin ou depase a nan miwa w, e anvan nenpòt machin k ap vini rive a 200 pye de ou.", "Crossing a broken yellow line to pass, you must see at least 400 feet ahead. Move back when you can see the passed vehicle's headlights in your mirror, and before any oncoming vehicle comes within 200 feet."], ["li", "Ou ka depase sou bò dwat sèlman lè machin devan an ap vire agoch, sou yon wout yon sèl sans, oswa sou yon wout kote tout machin ale nan menm direksyon. Lè yon moun ap depase w, ralanti epi rete adwat; pa akselere.", "Passing on the right is allowed only when the vehicle ahead is turning left, on a one-way street, or on a road where all traffic goes one way. When someone passes you, slow down and keep right; do not speed up."], ["li", "Lwa «move-over»: lè w ap pwoche yon veyikil ijans, otowout oswa remòkaj ki kanpe ak limyè k ap limen etèn, ralanti epi, sou yon wout ki gen de vwa oswa plis nan direksyon w, deplase pou kite yon vwa vid bò kote l. Pa depase machin ki kanpe oswa k ap vire.", "Move-over law: approaching a stopped emergency, highway or recovery vehicle with flashing lights, slow down and, on a road with two or more lanes your way, move over to leave an empty lane beside it. Do not pass vehicles that are stopped or turning."]]}, {"h": ["Pakin", "Parking"], "src": ["S7"], "pg": "109–111", "b": [["li", "Anvan w kite machin ou: etenn motè a, mete fren pakin nan, bloke kle kontak la, pran kle a epi fèmen pòt la a kle. Pake nan 12 pous de twotwa a epi kite omwen 12 pye wout klè.", "Before leaving your car: stop the motor, set the parking brake, lock the ignition, take the key and lock the door. Park within 12 inches of the curb and leave at least 12 feet of road clear."], ["li", "Sou yon mòn, mete fren pakin nan epi vire wou yo: desann ak twotwa, nan direksyon twotwa a; monte ak twotwa, nan direksyon opoze twotwa a; san twotwa, nan direksyon bò wout la.", "On a hill, set the parking brake and turn your wheels: downhill with a curb, toward the curb; uphill with a curb, away from the curb; with no curb, toward the edge of the road."], ["li", "Pa pake nan 20 pye yon kafou, nan 10 pye yon bouch ponpye, nan yon pasaj pyeton, devan yon antre kay, nan yon vwa bisiklèt oswa yon arè bis ($100), ni nan yon plas pou moun ki gen andikap san plak ($300 premye fwa).", "Do not park within 20 feet of an intersection, within 10 feet of a fire hydrant, in a crosswalk, in front of a driveway, in a bike lane or bus stop ($100), or in a disability space without a placard ($300 first offense)."]]}], "terms": [["thickly settled district", "zòn ki gen anpil kay"], ["blind spot", "kwen avèg"], ["rotary", "kafou won"], ["U-turn", "demi-tou"], ["move-over law", "lwa «move-over»"], ["fire hydrant", "bouch ponpye"]], "qs": [["pm701", 2, ["basic speed law", "lwa debaz sou vitès"], ["Limit ki afiche a se 50 mph, men gen yon gwo lapli. Kisa ki vre?", "Ou ka toujou kondui 50 mph", "Ou dwe limen limyè ijans ou epi kondui 50", "Ou dwe ralanti pou yon vitès ki san danje; menm 40 mph ka fè w jwenn yon kontravansyon", "Limit vitès pa aplike lè move tan", "Limit vitès yo baze sou bon kondisyon. Lwa debaz la se pa janm kondui pi vit pase sa ki san danje. Egzanp mànyèl la: 40 mph nan yon gwo lapli sou yon otowout 50 mph ka bay yon kontravansyon."], ["The posted limit is 50 mph, but there is a heavy rainstorm. Which is true?", "You may always drive 50 mph", "You must turn on your flashers and drive 50", "You must slow to a safe speed; even 40 mph could get you a ticket", "Speed limits do not apply in bad weather", "Speed limits assume ideal conditions. The basic law is never to drive faster than is safe. The manual's own example: 40 mph in a heavy rainstorm on a 50 mph highway can get a ticket."]], ["p4", 0, ["school zone", "zòn lekòl"], ["Ki limit vitès nan yon zòn lekòl?", "20 mph", "25 mph", "30 mph", "35 mph", "Sof si yon siy di yon lòt bagay, limit lan toupre lekòl se 20 mph. Li ka afiche ak limyè jòn k ap limen etèn oswa pou kèk lè nan jounen an. Veye timoun ak gad travèse yo."], ["What is the speed limit in a school zone?", "20 mph", "25 mph", "30 mph", "35 mph", "Unless posted otherwise, the limit near schools is 20 mph. It may be posted with flashing yellow lights or for certain hours. Watch for children and crossing guards."]], ["p7", 2, ["thickly settled", "zòn ki gen anpil kay"], ["Lè pa gen siy limit vitès, ki limit lan nan yon zòn ki gen anpil kay oswa zòn biznis?", "20 mph", "40 mph", "30 mph", "50 mph", "Limit leta a se 30 mph. Kèk vil mete 25 mph epi yo poze siy nan antre vil la, kidonk toujou swiv siy ki afiche yo."], ["With no speed limit sign, what is the limit in a thickly settled or business district?", "20 mph", "40 mph", "30 mph", "50 mph", "The state default is 30 mph. Some cities and towns have set 25 mph and post signs at their entrances, so always obey posted signs."]], ["pm702", 3, ["limited-access highway", "otowout ak aksè limite"], ["Ki limit vitès yo afiche sou otowout ak aksè limite tankou wout entèetatik yo?", "25 a 35 mph", "70 a 80 mph", "Pa gen limit", "50 a 65 mph", "Otowout ak aksè limite, tankou wout entèetatik yo, afiche ant 50 ak 65 mph. Ti otowout yo gen 55 mph oswa mwens."], ["What speed limits are posted on limited-access highways such as interstates?", "25 to 35 mph", "70 to 80 mph", "There is no limit", "50 to 65 mph", "Limited-access highways, like interstate routes, are posted from 50 to 65 mph. Smaller highways are 55 mph or lower."]], ["pm703", 1, ["minimum speed", "vitès minimòm"], ["Ki vitès minimòm sou Massachusetts Turnpike?", "Pa genyen", "40 mph", "20 mph", "55 mph", "Massachusetts Turnpike gen yon minimòm 40 mph; tinèl Boston Harbor yo gen yon minimòm 20 mph. Lapolis ka fè yon chofè k ap ralanti sikilasyon an rale sou kote tou."], ["What is the minimum speed on the Massachusetts Turnpike?", "There is none", "40 mph", "20 mph", "55 mph", "The Massachusetts Turnpike has a 40 mph minimum; the Boston Harbor tunnels have a 20 mph minimum. Police can also pull over a driver who is slowing traffic."]], ["pm704", 0, ["thickly settled district", "zòn ki gen anpil kay"], ["Kisa ki fè yon zòn se yon zòn ki gen anpil kay?", "Bilding yo mwens pase 200 pye youn de lòt sou yon ka mil oswa plis", "Nenpòt wout ki gen twotwa", "Plis pase 1,000 machin pa jou", "Nenpòt wout nan yon vil", "Yon zòn ki gen anpil kay gen bilding mwens pase 200 pye youn de lòt sou yon ka mil oswa plis. Limit pa defo a se 30 mph."], ["What makes an area a thickly settled district?", "Buildings less than 200 feet apart for a quarter mile or more", "Any road with a sidewalk", "More than 1,000 cars a day", "Any road inside a city", "A thickly settled district has buildings fewer than 200 feet apart for a quarter mile or more. The default limit there is 30 mph."]], ["pm705", 3, ["pedestrian", "pyeton"], ["Yon machin frape yon pyeton a 40 mph. Anviwon ki pòsyon pyeton ki blese grav oswa mouri nan vitès sa a?", "13%", "25%", "40%", "73%", "A 20 mph, 13% pyeton blese grav oswa mouri; a 30 mph, 40%; a 40 mph, 73%. Vitès machin yo se pi gwo menas pou pyeton."], ["A car hits a pedestrian at 40 mph. About what share of pedestrians are seriously injured or killed at that speed?", "13%", "25%", "40%", "73%", "At 20 mph, 13% of pedestrians are seriously injured or killed; at 30 mph, 40%; at 40 mph, 73%. Vehicle speed is the leading threat to pedestrians."]], ["pm706", 1, ["hand signal", "siyal ak men"], ["Siyal machin ou yo pa mache ankò. Kijan pou w fè siyal vire adwat ak men?", "Bra goch lonje tou dwat", "Bra goch pliye monte anlè nan koud la", "Bra goch pliye desann anba", "Fè bra w fè wonn", "Siyal ak men fèt nan fenèt chofè a: bra lonje tou dwat pou agoch, bra pliye anlè pou adwat, bra pliye anba pou ralanti oswa kanpe. Ou dwe konnen yo pou w pase Egzamen Pratik la."], ["Your turn signals stop working. How do you signal a right turn by hand?", "Left arm straight out", "Left arm bent up at the elbow", "Left arm bent down", "Wave your arm in a circle", "Hand signals are made through the driver's window: arm straight out for left, arm bent up for right, arm bent down to slow or stop. You must know them to pass the road test."]], ["pm707", 0, ["right lane", "vwa dwat"], ["Sou yon wout ki gen de vwa nan direksyon w, ki vwa ou dwe sèvi anjeneral?", "Vwa dwat la, sof si w ap depase, vire agoch, oswa l bloke", "Vwa goch la, paske li pi vit", "Nenpòt nan de yo, jan w vle", "Kondui ant de vwa yo", "Sèvi ak vwa dwat la sof si w ap depase, w ap vire agoch, oswa vwa dwat la bloke."], ["On a road with two lanes going your way, which lane should you normally use?", "The right lane, unless passing, turning left, or it is blocked", "The left lane, because it is faster", "Either lane, as you like", "Straddle both lanes", "Use the right lane unless you are passing, making a left turn, or the right lane is blocked."]], ["pm708", 2, ["exit", "sòti"], ["Ou rate sòti w sou otowout la. Kisa ou dwe fè?", "Kanpe sou bò wout la epi fè bak", "Fè demi-tou atravè mitan an", "Kontinye jiska pwochen sòti a", "Kanpe nan vwa a epi tann", "Si w rate sòti w, pa kanpe e pa janm fè bak sou otowout. Soti nan pwochen sòti a epi swiv siy yo pou w retounen."], ["You miss your exit on the highway. What should you do?", "Stop on the shoulder and back up", "Make a U-turn across the median", "Continue to the next exit", "Stop in the lane and wait", "If you miss your exit, do not stop and never back up on a highway. Get off at the next exit and follow signs back."]], ["pm709", 1, ["turn signal", "siyal vire"], ["A ki distans anvan yon vire sou yon wout nòmal ou dwe mete siyal?", "25 pye", "Omwen 100 pye", "Omwen 500 pye", "Sèlman lè w ap vire", "Mete siyal omwen 100 pye anvan yon vire, ak omwen 500 pye sou otowout. Mete siyal anvan w fren pou lòt moun konnen sa w pral fè."], ["How far before a turn on a regular road must you signal?", "25 feet", "At least 100 feet", "At least 500 feet", "Only as you turn", "Signal at least 100 feet before a turn, and at least 500 feet on a highway. Signal before you brake so others know what you plan."]], ["pm710", 3, ["highway exit", "sòti otowout"], ["A ki distans anvan yon sòti otowout ou dwe mete siyal?", "50 pye", "100 pye", "1 mil", "Omwen 500 pye", "Mete siyal sòti w omwen 500 pye anvan ranp lan, apre sa ralanti pou vitès ki afiche sou ranp lan lè w rive sou li."], ["How far before a highway exit should you signal?", "50 feet", "100 feet", "1 mile", "At least 500 feet", "Signal your exit at least 500 feet before the ramp, then slow to the posted ramp speed once you are on it."]], ["pm711", 2, ["passing lane", "vwa pou depase"], ["Sou yon otowout ki gen twa vwa nan direksyon w, pou kisa vwa ki pi agoch la ye?", "Kamyon", "Kondui dousman", "Depase", "Machin an pàn", "Ak twa vwa oswa plis: vwa ki pi adwat la pou kondui pi dousman, vwa mitan an pou kondui pi vit, vwa ki pi agoch la pou depase."], ["On an expressway with three lanes your way, what is the far left lane for?", "Trucks", "Slow driving", "Passing", "Breakdowns", "With three or more lanes: the far right lane for slower driving, the middle lane for faster driving, the far left lane for passing."]], ["pm712", 0, ["U-turn", "demi-tou"], ["Ki kote ou PA ka fè demi-tou, menm si pa gen siy?", "Toupre yon koub oswa tèt mòn kote chofè pa ka wè 500 pye", "Sou yon ri dwat ki klè", "Soti nan vwa ki pi pre liy mitan an", "Sou yon wout trankil ki gen ti kras machin", "Pa fè demi-tou sou tèt yon mòn, toupre yon koub, oswa nenpòt kote ou menm oswa lòt moun pa ka wè 500 pye. Fè l sèlman soti nan vwa ki pi pre liy mitan an."], ["Where may you NOT make a U-turn, even with no sign?", "Near a curve or hilltop where drivers cannot see 500 feet", "On a straight, clear street", "From the lane nearest the center line", "On a quiet road with light traffic", "Do not make a U-turn at the top of a hill, near a curve, or anywhere you or others cannot see 500 feet away. Make it only from the lane closest to the center line."]], ["pm713", 3, ["center turn lane", "vwa mitan pou vire"], ["Yon wout de sans gen yon vwa mitan pou vire agoch nan de direksyon. Kisa ki vre?", "Ou ka sèvi avè l pou depase", "Li pou yon sèl direksyon", "Ou ka kondui ladan l sou yon long distans", "Li sèlman pou vire agoch; ou pa ka kondui ladan l", "Yon vwa mitan ki make pou vire agoch se pou de direksyon yo pataje sèlman pou vire. Ou pa ka kondui ladan l."], ["A two-way road has a shared center left-turn lane. Which is true?", "You may use it to pass", "It is for one direction only", "You may drive in it for long distances", "It is only for left turns; you may not travel in it", "A center lane marked for left turns is shared by both directions for turning only. You may not travel in it."]], ["pm714", 1, ["turning lane", "vwa pou vire"], ["Ki vwa ou dwe sèvi pou vire agoch sou yon wout ki gen plizyè vwa?", "Vwa ki pi adwat la", "Vwa ki pi pre mitan an", "Nenpòt vwa, si w mete siyal", "Vwa pàn nan", "Vire soti nan vwa ki pi pre vwa w vle antre a: vire agoch soti nan vwa ki pi pre mitan an, vire adwat soti nan vwa ki pi adwat la. Chanje vwa apre vire a si w bezwen."], ["From which lane should you make a left turn on a multi-lane road?", "The far right lane", "The lane closest to the center", "Any lane, if you signal", "The breakdown lane", "Turn from the lane closest to the lane you want to enter: left turns from the lane nearest the center, right turns from the far right lane. Change lanes after the turn if you need to."]], ["pm715", 0, ["uncontrolled intersection", "kafou san siy"], ["Nan yon kafou ki pa gen siy ni limyè, yon lòt machin rive sou bò dwat ou an menm tan. Kiyès ki pase anvan?", "Machin ki sou bò dwat ou a", "Ou menm", "Machin ki pi vit la", "Moun ki klaksonnen an", "Nan yon kafou san siy, bay nenpòt machin ki antre oswa k ap vini sou bò dwat ou dwa de pasaj. Kontinye veye machin ki sou bò goch yo tou."], ["At an intersection with no signs or signals, another car arrives from your right at the same time. Who goes first?", "The car on your right", "You do", "The faster car", "Whoever honks", "At an uncontrolled intersection, yield to any vehicle that has entered from your right or is coming from your right. Still watch traffic from the left."]], ["pm716", 2, ["four-way stop", "STOP nan kat direksyon"], ["Nan yon kafou STOP nan kat direksyon, ou menm ak machin ki sou bò dwat ou kanpe an menm tan. Kisa ou fè?", "Pase anvan, paske w sou bò goch", "Nou toulède pase an menm tan", "Bay machin ki sou bò dwat ou a dwa de pasaj", "Klaksonnen epi pase", "Machin yo pase nan lòd yo te kanpe a. Si de kanpe an menm tan, bay sa ki sou bò dwat ou a dwa de pasaj. Gade chofè yo nan je ede evite konfizyon."], ["At a four-way stop, you and the car on your right stop at the same time. What do you do?", "Go first, since you are on the left", "Both go at once", "Yield to the car on your right", "Honk and go", "Vehicles go in the order they stopped. If two stop at the same time, yield to the one on your right. Eye contact helps avoid confusion."]], ["pm717", 3, ["White Cane Law", "Lwa Baton Blan"], ["Yon moun ki gen yon baton blan ap travèse ri a devan w. Kisa lalwa mande?", "Klaksonnen pou l konnen ou la", "Fè l siy pou l travèse", "Kondui dousman bò kote l", "Kanpe nèt epi rete kanpe jiskaske l fin travèse", "Lwa Baton Blan an mande pou w kanpe nèt pou yon pyeton avèg k ap travèse. Rete kanpe jiskaske l fin travèse; pa klaksonnen ni fè siy, epi pa janm depase yon lòt machin ki kanpe."], ["A person with a white cane is crossing the street in front of you. What does the law require?", "Honk so they know you are there", "Wave them across", "Drive slowly around them", "Stop completely and stay stopped until they have crossed", "The White Cane Law requires a complete stop for a blind pedestrian crossing. Stay stopped until they are across; do not honk or wave, and never pass another stopped vehicle."]], ["pm718", 1, ["driveway", "antre kay"], ["W ap soti nan yon antre kay pou antre sou yon ri asfalte. Kisa ou dwe fè?", "Klaksonnen epi soti", "Kanpe epi bay pyeton, siklis ak machin ki sou ri a dwa de pasaj", "Soti vit anvan machin yo rive", "Machin ki sou ri a dwe kanpe pou ou", "Lè w ap antre sou yon wout asfalte soti nan yon wout prive, yon antre kay oswa yon wout tè, ou dwe kanpe epi bay pyeton, siklis ak machin ki sou wout sa a dwa de pasaj."], ["You are pulling out of a driveway onto a paved street. What must you do?", "Honk and pull out", "Stop and yield to pedestrians, bicyclists and vehicles on the street", "Pull out quickly before traffic arrives", "Traffic on the street must stop for you", "Entering a paved road from a private road, driveway or unpaved road, you must stop and give the right-of-way to pedestrians, bicyclists and vehicles on that road."]], ["pm719", 0, ["divided highway", "otowout divize"], ["Ou sou yon wout de vwa epi w rive nan yon kafou ak yon otowout divize. Kiyès ki gen dwa de pasaj?", "Machin ki sou otowout divize a", "Ou menm, si w rive anvan", "Moun ki pi vit la", "Ou menm, paske w sou bò dwat", "Si w sou yon wout yon oswa de vwa epi w rive nan yon otowout divize oswa yon wout twa vwa oswa plis, ou dwe bay dwa de pasaj."], ["You are on a two-lane road and reach an intersection with a divided highway. Who has the right-of-way?", "Traffic on the divided highway", "You, if you arrive first", "Whoever is going faster", "You, because you are on the right", "If you are on a single or two-lane road and come to a divided highway or a road with three or more lanes, you must yield the right-of-way."]], ["p3", 1, ["rotary", "kafou won"], ["W ap antre nan yon kafou won. Kiyès ki gen dwa de pasaj?", "Ou menm, paske w sou bò dwat", "Machin ki deja nan kafou won an", "Machin ki pi gwo a", "Moun ki klaksonnen an premye", "Sikilasyon nan yon kafou won nan Massachusetts fè wonn nan sans kontrè egui yon revèy. Bay machin ki deja nan kafou won an ak pyeton yo dwa de pasaj, sof si siy oswa lapolis di yon lòt bagay."], ["You are entering a rotary. Who has the right-of-way?", "You, because you are on the right", "Vehicles already in the rotary", "The larger vehicle", "Whoever honks first", "Traffic in a Massachusetts rotary moves counterclockwise. Yield to vehicles already in the rotary and to pedestrians, unless signs or police say otherwise."]], ["pm720", 3, ["counterclockwise", "kontrè egui yon revèy"], ["Nan ki direksyon machin yo fè wonn nan yon kafou won Massachusetts?", "Nan sans egui yon revèy", "Nenpòt sans", "Sans ki pi kout la", "Nan sans kontrè egui yon revèy", "Sikilasyon nan yon kafou won toujou fè wonn nan sans kontrè egui yon revèy, toutotou zile mitan an."], ["Which way does traffic travel in a Massachusetts rotary?", "Clockwise", "Either way", "Whichever way is shorter", "Counterclockwise", "Traffic in a rotary always travels counterclockwise, around the central island."]], ["pm721", 0, ["multi-lane rotary", "kafou won ak plizyè vwa"], ["Nan yon kafou won ak plizyè vwa san siy, ou vle fè demi-tou. Nan ki vwa ou dwe antre?", "Vwa goch la, apre sa soti nan vwa dwat la", "Vwa dwat la, epi rete adwat tout chemen an", "Nenpòt vwa, apre sa koupe travèse", "Vwa pàn nan", "Pou twa ka vire oswa demi-tou san siy, antre nan vwa goch la, kondui nan vwa anndan an, epi soti nan vwa dwat la. Pou yon ka vire oswa tou dwat, sèvi ak vwa dwat la."], ["In a multi-lane rotary with no signs, you want to make a U-turn. Which lane should you enter from?", "The left lane, then exit to the right lane", "The right lane, and stay right the whole way", "Any lane, then cut across", "The breakdown lane", "For a three-quarter turn or U-turn with no signs, enter from the left lane, travel in the inner lane, and exit onto the right lane. For a quarter turn or straight ahead, use the right lane."]], ["pm722", 2, ["roundabout", "wonpwen piti"], ["Konpare ak yon kafou won, ki vitès yon wonpwen piti mande?", "Jiska 40 mph", "Vitès otowout", "25 mph oswa mwens", "Omwen 30 mph", "Wonpwen piti yo pi piti pase kafou won yo, ak liy yield ak pasaj pyeton, epi gwosè yo mande vitès 25 mph oswa mwens. Gwo kafou won yo ka resevwa machin jiska 40 mph."], ["Compared with a rotary, a roundabout requires what speed?", "Up to 40 mph", "Highway speed", "25 mph or less", "At least 30 mph", "Roundabouts are smaller than rotaries, with yield lines and crosswalks, and their size requires speeds of 25 mph or less. Big rotaries handle traffic up to 40 mph."]], ["pm723", 1, ["courtesy crash", "aksidan politès"], ["W ap tann pou vire agoch. Yon chofè nan machin ki kanpe yo fè w siy pase. Kisa ki vre?", "Siy la ba ou dwa de pasaj", "Machin k ap vini yo toujou gen dwa de pasaj; vire sèlman lè w wè wout la klè", "Ou dwe vire touswit pou w pa bloke sikilasyon an", "Chofè ki fè siy la responsab nenpòt aksidan", "Fè moun siy pase nan mitan machin ki kanpe lakoz aksidan politès. Machin k ap vini yo gen dwa de pasaj kit yon moun fè w siy kit li pa fè w siy."], ["You are waiting to turn left. A driver in stopped traffic waves you through. What is true?", "The wave gives you the right-of-way", "Oncoming traffic still has the right-of-way; turn only when you can see it is clear", "You must turn right away so you do not hold up traffic", "The waving driver is responsible for any crash", "Waving people through stopped traffic causes courtesy crashes. Oncoming traffic has the right-of-way whether or not someone waves at you."]], ["pm724", 3, ["passing", "depase"], ["Ou vle travèse yon liy jòn an tire pou depase. Ki distans devan ou dwe ka wè klè?", "100 pye", "200 pye", "1,000 pye", "Omwen 400 pye", "Pou travèse yon liy jòn an tire pou depase, ou dwe ka wè omwen 400 pye devan, epi ou dwe retounen nan vwa w anvan nenpòt machin k ap vini rive a 200 pye."], ["You want to cross a broken yellow line to pass. How far ahead must you be able to see clearly?", "100 feet", "200 feet", "1,000 feet", "At least 400 feet", "To cross a broken yellow line to pass, you must see at least 400 feet ahead, and you must be back in your lane before any oncoming vehicle comes within 200 feet."]], ["pm725", 2, ["returning to lane", "retounen nan vwa"], ["Apre w fin depase, kilè li san danje pou w retounen nan vwa dwat la?", "Depi pare-chòk devan w fin pase lòt machin nan", "Apre w fin klaksonnen", "Lè w ka wè limyè devan machin ou depase a nan miwa w", "Sèlman nan pwochen kafou a", "Tann omwen jiskaske w wè limyè devan machin ou depase a nan miwa w, mete siyal adwat, epi retounen anvan machin k ap vini yo rive a 200 pye."], ["After passing, when is it safe to move back into the right lane?", "As soon as your front bumper is past the other car", "After you honk", "When you can see the passed vehicle's headlights in your mirror", "Only at the next intersection", "Wait at least until you can see the passed vehicle's headlights in your mirror, signal right, and return before oncoming traffic is within 200 feet."]], ["pm726", 0, ["passing on the right", "depase sou bò dwat"], ["Kilè ou ka depase yon lòt machin sou bò dwat?", "Lè l ap vire agoch epi gen espas", "Nenpòt lè l ap mache twò dousman", "Sou bò wout la", "Pa janm", "Ou ka depase sou bò dwat sèlman lè machin nan ap vire agoch, sou yon wout yon sèl sans, oswa sou yon wout kote machin yo ale nan yon sèl direksyon, epi wout la laj e klè. Pa janm sèvi ak bò wout la."], ["When may you pass another vehicle on the right?", "When it is turning left and there is room", "Any time it is going too slowly", "Using the shoulder", "Never", "Passing on the right is allowed only when the vehicle is turning left, on a one-way street, or on a road where traffic moves one way, and the road is wide and clear. Never use the shoulder."]], ["pm727", 1, ["being passed", "yon moun ap depase w"], ["Yon lòt machin ap depase w. Kisa ou dwe fè?", "Akselere pou l pa ka pase devan w", "Ralanti epi rete adwat", "Deplase agoch pou bloke l", "Fren fò", "Lè yon moun ap depase w, ralanti, rete adwat, epi kite lòt chofè a pase san danje. Pa akselere."], ["Another car is passing you. What should you do?", "Speed up so it can't get in front", "Slow down and keep to the right", "Move to the left to block it", "Brake hard", "When you are being passed, slow down, stay to the right, and let the other driver pass safely. Do not speed up."]], ["pm728", 3, ["move-over law", "lwa «move-over»"], ["Sou yon otowout kat vwa, yon machin lapolis kanpe sou bò wout la ak limyè l k ap limen etèn. Kisa lwa «move-over» a mande?", "Anyen, si w rete nan vwa w", "Kanpe dèyè machin lapolis la", "Akselere pou w pase l vit", "Ralanti epi, si l san danje, deplase pou kite yon vwa vid bò kote l", "Lè w ap pwoche yon veyikil ijans, otowout oswa remòkaj ki kanpe ak limyè k ap limen etèn, ralanti a yon vitès san danje epi pran yon vwa ki pa kole ak li. Si w pa ka deplase, ou toujou dwe ralanti."], ["On a four-lane highway, a police car is stopped on the shoulder with its lights flashing. What does the move-over law require?", "Nothing, if you stay in your lane", "Stop behind the police car", "Speed up to pass it quickly", "Slow down and, if safe, move over to leave an empty lane beside it", "Approaching a stopped emergency, highway or recovery vehicle with flashing lights, slow to a safe speed and move to a lane not next to it. If you cannot move over, you must still slow down."]], ["pm729", 2, ["parking on a hill", "pake sou mòn"], ["Ou pake fas desann bò yon twotwa. Ki bò ou dwe vire wou devan yo?", "Tou dwat", "Nan direksyon opoze twotwa a", "Nan direksyon twotwa a", "Sa pa enpòtan si fren pakin nan mete", "Desann bò yon twotwa: wou yo vire nan direksyon twotwa a. Monte bò yon twotwa: wou yo vire nan direksyon opoze twotwa a, sou bò vwa a. San twotwa: wou yo vire sou bò wout la. Toujou mete fren pakin nan."], ["You park facing downhill next to a curb. Which way should you turn your front wheels?", "Straight ahead", "Away from the curb", "Toward the curb", "It does not matter with the parking brake on", "Downhill against a curb: wheels toward the curb. Uphill against a curb: wheels away from the curb, toward the travel lane. No curb: wheels toward the edge of the road. Always set the parking brake."]], ["pm730", 0, ["fire hydrant", "bouch ponpye"], ["Ki distans ou ka pake bò yon bouch ponpye?", "Pa pi pre pase 10 pye", "Pa pi pre pase 3 pye", "Kole ak li, si w rete nan machin nan", "Pa pi pre pase 50 pye", "Ou pa ka pake nan 10 pye yon bouch ponpye oswa yon vwa ponpye, ni nan 20 pye yon kafou."], ["How close to a fire hydrant may you park?", "No closer than 10 feet", "No closer than 3 feet", "Right next to it, if you stay in the car", "No closer than 50 feet", "You may not park within 10 feet of a fire hydrant or fire lane, or within 20 feet of an intersection."]], ["pm731", 3, ["intersection", "kafou"], ["Ki distans ou ka pake bò yon kafou?", "5 pye", "10 pye", "Nenpòt kote andeyò pasaj pyeton an", "Pa pi pre pase 20 pye", "Pa pake nan 20 pye yon kafou, nan yon pasaj pyeton, ni devan yon antre kay."], ["How close to an intersection may you park?", "5 feet", "10 feet", "Anywhere outside the crosswalk", "No closer than 20 feet", "Do not park within 20 feet of an intersection, in a crosswalk, or in front of a driveway."]], ["pm732", 1, ["parking brake", "fren pakin"], ["Ou kite machin ou pake nan ri a. Kisa lwa leta a mande?", "Fèmen pòt yo sèlman", "Etenn motè a, mete fren pakin nan, bloke kontak la, retire kle a epi fèmen pòt la a kle", "Kite motè a ap mache si w pa pral pran tan", "Limen limyè ijans yo", "Lè w kite machin ou, lwa leta a mande pou w etenn motè a, mete fren pakin nan, bloke kontak la, retire kle a epi fèmen pòt la a kle."], ["You leave your car parked on the street. What does state law require?", "Only lock the doors", "Stop the motor, set the parking brake, lock the ignition, remove the key and lock the door", "Leave the engine running if you will be quick", "Turn on the emergency flashers", "When you leave your vehicle, state law requires you to stop the motor, set the parking brake, lock the ignition, remove the key and lock the door."]]]},
{"ch": 8, "bp": ["Chapit 5 nan mànyèl la, paj 119–131. Nan egzamen RMV a: règ wout yo.", "Manual chapter 5, pages 119–131. On the RMV test: rules of the road."], "title": ["Ijans, lè lapolis kanpe w, ak aksidan", "Emergencies, police stops and crashes"], "src": ["S7"], "sections": [{"h": ["Veyikil ijans", "Emergency vehicles"], "src": ["S7"], "pg": "120–121", "b": [["li", "Lè yon veyikil ijans sèvi ak siren oswa limyè l, kèlkeswa direksyon l ap vini, rale toutotan ou kapab sou bò dwat wout la epi kanpe jiskaske l pase. Woule dousman pa ase. Pa janm kanpe nan mitan yon kafou: travèse l, apre sa rale sou kote.", "When an emergency vehicle uses its siren or lights, from any direction, pull as close as you can to the right side of the road and stop until it passes. Slowly rolling is not enough. Never stop in an intersection: drive through, then pull over."], ["li", "Apre l fin pase, mete siyal agoch epi retounen nan sikilasyon an lè vwa a klè. Pa swiv pi pre pase 300 pye dèyè yon veyikil ijans k ap reponn yon alam, epi pa kondui ni pake nan 800 pye yon dife.", "After it passes, signal left and merge back when the lane is clear. Do not follow closer than 300 feet behind an emergency vehicle answering an alarm, and do not drive or park within 800 feet of a fire."]]}, {"h": ["Si lapolis kanpe w", "If police stop you"], "src": ["S7"], "pg": "121–123", "b": [["li", "Mete siyal, gade miwa yo epi rale nèt sou bò dwat, pa nan yon kafou ni devan yon antre kay. Mete machin nan nan pak, etenn motè ak radyo a, epi lannwit limen limyè anndan an.", "Signal, check mirrors and pull completely to the right, not into an intersection or in front of a driveway. Put the car in park, turn off the engine and radio, and at night turn on the interior light."], ["li", "Rete nan machin nan ak men w kote yo ka wè yo. Chèche lisans ak anrejistreman w sèlman lè yo mande w. Si w pa ka montre yo, se $35 amann premye fwa.", "Stay in the car with your hands in plain sight. Reach for your license and registration only when asked. Failing to produce them is a $35 fine for a first offense."], ["li", "Si yo ba w yon kontravansyon, pa diskite: ou ka konteste l nan tribinal. Massachusetts pa mande w siyen yon kontravansyon.", "If you get a ticket, do not argue: you can challenge it in court. Massachusetts does not require you to sign a citation."]]}, {"h": ["Ijans pandan w ap kondui", "Driving emergencies"], "src": ["S7"], "pg": "123–125", "b": [["li", "Derapaj: lage gaz la dousman, pa fren, epi vire volan an nan direksyon dèyè machin nan ap glise. Si w soti sou asfalt la: kenbe volan an fèm, lage gaz la, fren dousman, apre sa dirije tou dousman retounen sou wout la.", "Skid: ease off the gas, do not brake, and steer in the direction the rear of the car is sliding. Running off the pavement: hold the wheel firmly, ease off the gas, brake gently, then steer gently back."], ["li", "Kawoutchou pete: kenbe volan an fèm, lage gaz la epi fren dousman lè w fin kontwole machin nan. Fren ki pa mache san ABS: ponpe pedal la vit; ak ABS, desann vitès epi mete fren pakin nan dousman. Pedal gaz ki kole: mete machin nan nan net epi fren.", "Blowout: grip the wheel, ease off the gas and brake gently once you have control. Brake failure without antilock brakes: pump the pedal quickly; with antilock brakes, downshift and apply the parking brake gently. Stuck gas pedal: shift to neutral and brake."], ["li", "Yon machin k ap vin fas a fas nan vwa w: ralanti, rale adwat epi klaksonnen. Limyè devan yo etenn: limen ti limyè yo oswa limyè ijans epi soti sou wout la.", "A car coming head-on in your lane: slow down, pull right and sound your horn. Headlights fail: turn on parking lights or flashers and pull off the road."], ["li", "Machin nan kanpe sou ray tren epi gen yon tren k ap vini: fè tout moun desann touswit epi kouri lwen ray yo nan yon ang 45 degre nan direksyon tren an ap soti a, apre sa rele 911.", "Stalled on railroad tracks with a train coming: get everyone out immediately and run away from the tracks at a 45-degree angle toward the direction the train is coming from, then call 911."]]}, {"h": ["Pàn, dife ak dlo", "Breakdowns, fire and water"], "src": ["S7"], "pg": "125–128", "b": [["li", "Sou otowout, kanpe toutotan ou kapab lwen machin yo epi rete nan veyikil la ak limyè ijans limen. Triyang avètisman: sou yon otowout divize, 10 ak 100 pye dèyè; sou yon wout de sans, 100 pye devan tou.", "On a highway, stop as far from traffic as you can and stay in the vehicle with hazard lights on. Warning triangles: on a divided highway, 10 and 100 feet behind; on a two-way road, also 100 feet in front."], ["li", "Lafimen ki soti anba kapo a: rale sou kote, etenn kontak la, deplase lwen machin nan epi rele ponpye.", "Smoke from under the hood: pull off, turn off the ignition, move away and call the fire department."], ["li", "Si machin ou tonbe nan dlo, demare senti w epi soti pa yon fenèt. Pa louvri yon pòt. Si l desann anba dlo anvan, ale nan chèz dèyè a kote ka gen lè, apre sa soti pa yon fenèt.", "If your car goes into water, unfasten your belt and escape through a window. Do not open a door. If it sinks first, move to the back seat where air may be trapped, then escape through a window."]]}, {"h": ["Aksidan", "Crashes"], "src": ["S7"], "pg": "128–131", "b": [["li", "Apre nenpòt aksidan ou dwe kanpe. Kite sèn nan san w pa idantifye tèt ou se yon krim (frape epi kouri).", "After any crash you must stop. Leaving the scene without identifying yourself is a crime (hit and run)."], ["li", "Si pa gen moun ki blese, retire machin yo nan vwa sikilasyon yo (Lwa sou Retire Machin). Bay youn lòt non, adrès, nimewo lisans, anrejistreman ak asirans.", "If no one is hurt, move the vehicles out of travel lanes (the Driver Removal Law). Exchange names, addresses, license numbers, registration and insurance."], ["li", "Nan senk jou, ranpli yon rapò aksidan pou RMV ak lapolis lokal si yon moun blese oswa mouri, oswa si domaj yo $1,000 oswa plis. Di konpayi asirans ou sèlman pa ase.", "Within five days, file a crash report with the RMV and the local police if anyone was hurt or killed, or damage is $1,000 or more. Telling your insurer is not enough."], ["li", "Pa deplase yon moun ki blese sof si sa nesesè; peze dirèkteman sou kote k ap senyen an. Si fil kouran tonbe sou yon machin, moun ki andedan yo dwe rete andedan jiskaske èd rive. Si w se temwen, pa ralanti pou w gade.", "Do not move an injured person unless necessary; press directly on bleeding. If wires fall on a car, the people inside should stay inside until help arrives. As a witness, do not slow down to look."]]}], "terms": [["emergency vehicle", "veyikil ijans"], ["skid", "derapaj"], ["blowout", "kawoutchou pete"], ["hit and run", "frape epi kouri"], ["crash report", "rapò aksidan"], ["warning triangle", "triyang avètisman"]], "qs": [["p13", 0, ["emergency vehicle", "veyikil ijans"], ["Yon anbilans ak limyè k ap limen etèn ak siren ap vini dèyè w. Kisa ou fè?", "Rale sou bò dwat epi kanpe", "Akselere pou soti devan l", "Kanpe kote w ye a nan vwa w", "Kontinye kondui menm vitès la", "Rale toutotan ou kapab sou bò dwat epi kanpe jiskaske l pase. Woule dousman pa aksepte. Pa janm kanpe nan mitan yon kafou: travèse l, apre sa rale sou kote."], ["An ambulance with flashing lights and a siren comes up behind you. What do you do?", "Pull to the right and stop", "Speed up to get out of its way", "Stop where you are in your lane", "Keep driving at the same speed", "Pull as close as you can to the right side and stop until it passes. Slowly rolling is not acceptable. Never stop in an intersection: drive through, then pull over."]], ["pm801", 2, ["following distance", "distans dèyè"], ["A ki distans ou ka swiv yon kamyon ponpye k ap reponn yon alam?", "100 pye", "Nenpòt distans, si limyè w limen", "Pa pi pre pase 300 pye", "50 pye", "Li ilegal pou w swiv pi pre pase 300 pye dèyè yon veyikil ijans k ap reponn yon alam. Rete omwen 800 pye lwen yon dife tou."], ["How close may you follow a fire truck answering an alarm?", "100 feet", "Any distance, if your lights are on", "No closer than 300 feet", "50 feet", "It is illegal to follow closer than 300 feet behind an emergency vehicle responding to an alarm. Also stay at least 800 feet from a fire."]], ["pm802", 1, ["intersection", "kafou"], ["Ou nan mitan yon kafou lè w tande yon siren dèyè w. Kisa ou dwe fè?", "Kanpe la menm", "Travèse kafou a, apre sa rale sou bò dwat epi kanpe", "Fè bak pou soti nan kafou a", "Rale sou bò goch", "Pa janm kanpe nan mitan yon kafou. Travèse l, apre sa rale sou bò dwat depi l san danje. Pa rale agoch ni fren sanzatann."], ["You are in the middle of an intersection when you hear a siren behind you. What should you do?", "Stop right there", "Drive through the intersection, then pull to the right and stop", "Back up out of the intersection", "Pull to the left", "Never stop in the middle of an intersection. Drive through it, then pull over to the right as soon as it is safe. Do not pull left or slam on the brakes."]], ["pm803", 3, ["traffic stop", "lè lapolis kanpe w"], ["Yon polisye fè w rale sou kote epi l ap mache vin bò machin ou. Kisa ou dwe fè?", "Desann epi mache al jwenn machin lapolis la", "Chèche papye w yo anba chèz la", "Rele yon moun nan telefòn ou", "Rete nan machin nan ak men w kote yo ka wè yo", "Rete nan veyikil la, kenbe men w vizib, etenn motè a, epi tann polisye a mande anvan w chèche lisans ak anrejistreman w. Pa sèvi ak telefòn ou."], ["A police officer has pulled you over and is walking to your car. What should you do?", "Get out and walk to the police car", "Reach under the seat for your papers", "Call someone on your phone", "Stay in the car with your hands in plain sight", "Stay in the vehicle, keep your hands visible, turn off the engine, and wait until the officer asks before reaching for your license and registration. Do not use your phone."]], ["pm804", 0, ["skid", "derapaj"], ["Machin ou kòmanse derape sou yon wout ki glise. Kisa pye w dwe fè an premye?", "Lage gaz la dousman epi pa fren", "Fren fò", "Peze gaz la pou machin nan kenbe wout la", "Kenbe tou de pye w atè", "Lè w ap derape, lage gaz la dousman epi pa sèvi ak fren, apre sa vire nan direksyon dèyè machin nan ap glise a. Ou ka bezwen vire de bò kèk fwa."], ["Your car starts to skid on a slippery road. What should your feet do first?", "Ease off the gas and do not brake", "Brake hard", "Press the gas to regain grip", "Keep both feet on the floor", "In a skid, ease off the gas and do not use the brakes, then steer in the direction the rear of the car is sliding. You may need to steer back and forth a few times."]], ["pm805", 3, ["shoulder", "bò wout"], ["Wou dwat ou yo soti sou asfalt la epi tonbe sou bò wout la. Kisa ou dwe fè?", "Vire volan an fò agoch touswit", "Fren fò", "Akselere pou w remonte", "Kenbe volan an fèm, lage gaz la, fren dousman, apre sa dirije tou dousman retounen", "Kenbe volan an fèm, retire pye w sou gaz la dousman, fren dousman pou ralanti, gade machin ki dèyè w, apre sa dirije tou dousman retounen sou wout la."], ["Your right wheels drift off the pavement onto the shoulder. What should you do?", "Jerk the wheel back to the left right away", "Brake hard", "Speed up to climb back on", "Hold the wheel firmly, ease off the gas, brake gently, then steer gently back", "Hold the steering wheel tightly, slowly take your foot off the gas, brake gently to reduce speed, check traffic behind you, then steer gently back onto the road."]], ["pm806", 2, ["brake failure", "fren ki pa mache"], ["Machin ou PA gen fren antiblokaj, epi fren yo pa reponn toudenkou. Kisa ou dwe eseye an premye?", "Etenn motè a", "Mete l nan pak", "Ponpe pedal fren an plizyè fwa vit", "Louvri pòt la epi trennen pye w", "San fren antiblokaj, ponpe pedal la vit pou fè presyon. Pa janm ponpe fren antiblokaj. Si sa pa mache, desann vitès epi mete fren pakin nan dousman, epi sèvi ak klaksòn ak limyè pou avèti lòt moun."], ["Your car does NOT have antilock brakes, and the brakes suddenly do not respond. What should you try first?", "Turn off the engine", "Shift into park", "Pump the brake pedal several times quickly", "Open the door and drag your foot", "Without antilock brakes, pump the pedal quickly to build pressure. Never pump antilock brakes. If that fails, downshift and apply the parking brake gently, and use horn and lights to warn others."]], ["pm807", 0, ["stuck gas pedal", "pedal gaz ki kole"], ["Pedal gaz ou kole anba. Kisa ou dwe fè an premye?", "Mete machin nan nan net epi peze fren an", "Etenn kle a nèt pandan machin nan ap mache", "Ponpe pedal gaz la", "Bese pou w libere l ak men w", "Mete machin nan nan net epi fren pou ralanti. Eseye libere pedal la ak pye w, kenbe je w sou wout la, epi soti sou kote epi kanpe lè l san danje."], ["Your gas pedal sticks down. What should you do first?", "Shift into neutral and press the brake", "Turn the key all the way off while moving", "Pump the gas pedal", "Reach down with your hand to free it", "Put the car in neutral and brake to slow down. Try to free the pedal with your foot, keep your eyes on the road, and pull off and stop when it is safe."]], ["pm808", 1, ["head-on", "fas a fas"], ["Yon machin ap vin dirèkteman sou ou nan vwa w. Kisa ou dwe fè?", "Devye agoch", "Ralanti, rale adwat epi klaksonnen", "Akselere", "Kanpe nan vwa w", "Si yon veyikil ap vin fas a fas sou ou nan vwa w, ralanti, rale adwat, epi klaksonnen pou avèti lòt chofè a."], ["A car is coming straight at you in your lane. What should you do?", "Swerve to the left", "Slow down, pull to the right and sound your horn", "Speed up", "Stop in your lane", "If a vehicle comes toward you head on in your lane, slow down, pull to the right, and sound your horn to alert the other driver."]], ["pm809", 3, ["railroad tracks", "ray tren"], ["Machin ou kanpe sou ray tren epi gen yon tren k ap vini. Kisa ou fè?", "Kontinye eseye demare motè a", "Rete nan machin nan ak senti mare", "Pouse machin nan soti sou ray yo", "Fè tout moun desann epi kouri lwen ray yo an dyagonal nan direksyon tren k ap vini an, apre sa rele 911", "Fè tout moun desann touswit. Kouri lwen ray yo nan yon ang 45 degre nan direksyon tren an ap soti a, pou evite debri k ap vole, apre sa rele 911."], ["Your car stalls on railroad tracks and a train is coming. What do you do?", "Keep trying to start the engine", "Stay in the car with belts on", "Push the car off the tracks", "Get everyone out and run away from the tracks at an angle toward the oncoming train, then call 911", "Get everyone out immediately. Run away from the tracks at a 45-degree angle in the direction the train is coming from, to avoid flying wreckage, then call 911."]], ["pm810", 2, ["vehicle in water", "machin nan dlo"], ["Machin ou tonbe nan yon dlo fon. Kijan ou dwe soti?", "Louvri pòt la touswit", "Tann machin nan plen dlo", "Demare senti w epi soti pa yon fenèt", "Monte sou do machin nan pa twou do a sèlman", "Demare senti w epi soti pa yon fenèt; louvri fenèt elektrik yo vit anvan yo sispann mache. Pa louvri yon pòt: dlo ap antre fò epi machin nan ka vire."], ["Your car goes into deep water. How should you get out?", "Open the door right away", "Wait for the car to fill with water", "Unfasten your belt and escape through a window", "Climb onto the roof through the sunroof only", "Unfasten your seat belt and escape through a window; open power windows quickly before they stop working. Do not open a door: water rushes in and the car can flip."]], ["pm811", 0, ["warning triangle", "triyang avètisman"], ["Machin ou tonbe an pàn sou yon otowout divize. Ki kote ou mete triyang avètisman yo?", "10 pye ak 100 pye dèyè veyikil la", "Sèlman devan veyikil la", "Sou kapo a", "500 pye devan", "Sou yon otowout divize, mete triyang oswa limyè avètisman 10 pye ak 100 pye dèyè veyikil ou. Sou yon wout de sans oswa ki pa divize, ajoute youn 100 pye devan."], ["You break down on a divided highway. Where do you place your warning triangles?", "10 feet and 100 feet behind the vehicle", "Only in front of the vehicle", "On the hood", "500 feet ahead", "On a divided highway, place triangles or flares 10 feet and 100 feet behind your vehicle. On a two-way or undivided road, add one 100 feet in front."]], ["pm812", 1, ["crash report", "rapò aksidan"], ["Ou nan yon aksidan ki fè $1,500 domaj san blese. Kisa ou dwe ranpli, e kilè?", "Anyen, si pa gen moun ki blese", "Yon rapò aksidan pou RMV ak lapolis lokal nan senk jou", "Sèlman yon apèl bay konpayi asirans ou", "Yon rapò nan 30 jou", "Nenpòt aksidan ki gen blese, lanmò oswa $1,000 oswa plis domaj dwe rapòte bay RMV ak lapolis lokal nan senk jou. Di asirans ou sèlman pa ase."], ["You are in a crash that causes $1,500 of damage and no injuries. What must you file, and when?", "Nothing, if no one was hurt", "A crash report with the RMV and local police within five days", "Only a call to your insurance company", "A report within 30 days", "Any crash with injury, death or $1,000 or more in property damage must be reported to the RMV and local police within five days. Telling your insurer is not enough."]], ["pm813", 3, ["Driver Removal Law", "Lwa sou Retire Machin"], ["Ou fè yon ti aksidan epi pèsonn pa blese. Kisa Lwa sou Retire Machin nan mande?", "Kite machin yo egzakteman kote yo ye pou lapolis", "Kondui ale lakay epi rapòte l pita", "Rele yon remòkaj anvan w deplase", "Retire machin yo nan vwa sikilasyon yo pou mete yo yon kote ki san danje", "Si pa gen blese, Lwa sou Retire Machin nan mande pou w retire machin yo nan vwa sikilasyon yo pou mete yo yon kote ki san danje. Apre sa bay youn lòt enfòmasyon. Pa janm kite sèn nan."], ["You have a minor crash and no one is hurt. What does the Driver Removal Law require?", "Leave the cars exactly where they are for police", "Drive home and report it later", "Call a tow truck before moving", "Move the vehicles out of the travel lanes to a safe place", "If there are no injuries, the Driver Removal Law requires moving the vehicles out of travel lanes to a safe place. Then exchange information. Never leave the scene."]], ["pm814", 2, ["downed wires", "fil kouran ki tonbe"], ["Apre yon aksidan, fil kouran tonbe sou yon machin ki gen moun andedan. Kisa yo dwe fè?", "Sote soti touswit", "Eseye deplase fil yo ak yon bwa", "Rete andedan jiskaske moun ijans yo rive", "Kondui machin nan soti anba fil yo", "Pa pwoche fil ki tonbe yo. Si fil yo sou yon veyikil, moun ki andedan yo dwe rete jiskaske moun ijans yo rive, epi pèsonn pa dwe touche veyikil la."], ["After a crash, power lines have fallen on a car with people inside. What should they do?", "Jump out right away", "Try to move the wires with a stick", "Stay inside until emergency personnel arrive", "Drive the car out from under the wires", "Do not go near fallen wires. If wires are on a vehicle, the people inside should stay there until emergency personnel arrive, and no one should touch the vehicle."]], ["pm815", 0, ["hit and run", "frape epi kouri"], ["Ou grate yon machin ki pake epi pa gen pèsonn bò la. Kisa ou dwe fè?", "Eseye jwenn pwopriyetè a, oswa avèti lapolis lokal", "Ale, paske pèsonn pa wè", "Kite yon nòt san non", "Tann 10 minit, apre sa ale", "Si w fè domaj sou yon veyikil ki pake oswa yon pwopriyete, eseye jwenn pwopriyetè a oswa avèti lapolis lokal. Kite sèn nan san w pa idantifye tèt ou se yon vyolasyon kriminèl «frape epi kouri»."], ["You scrape a parked car and no one is around. What must you do?", "Try to find the owner, or notify the local police", "Leave, since no one saw it", "Leave a note with no name", "Wait 10 minutes, then leave", "If you damage a parked vehicle or property, try to locate the owner or notify the local police. Leaving the scene without identifying yourself is a criminal hit-and-run violation."]], ["pm816", 1, ["injured person", "moun ki blese"], ["Ou kanpe pou ede nan yon aksidan. Yon moun ap senyen epi l konsyan. Kisa ou dwe fè?", "Pote l nan machin ou touswit", "Peze dirèkteman sou blesi a epi kenbe l trankil ak cho", "Ba l yon bagay pou l bwè", "Ale lè lapolis rive san w pa bay non w", "Pa deplase yon moun ki blese sof si sa nesesè. Peze dirèkteman sou kote k ap senyen an jiskaske èd rive, epi kouvri l pou l rete cho e pou evite chòk."], ["You stop to help at a crash. A person is bleeding and conscious. What should you do?", "Move them to your car right away", "Press directly on the wound and keep them still and warm", "Give them something to drink", "Leave once police arrive without giving your name", "Do not move an injured person unless necessary. Put pressure directly on bleeding until help arrives, and cover them to keep warm and prevent shock."]]]}];
