window.PERMIT_FAQ = [
["Kiyès ki bezwen yon lisans kondui Massachusetts?", "Who needs a Massachusetts driver's license?", "Tout moun ki rete Massachusetts epi ki kondui Massachusetts. Si w vin rete isit, ou dwe pran yon lisans Massachusetts pou w kontinye kondui: pa gen delè gras.", "Every Massachusetts resident who drives in Massachusetts. If you move here, you must get a Massachusetts license to keep driving: there is no grace period.", ["S7"], "2", "apply"],
["Ki laj mwen dwe genyen?", "How old do I have to be?", "16 an pou yon pèmi apranti Klas D oswa Klas M. Pi bonè, ou ka jwenn yon lisans a 16 an edmi, apre sis mwa ak pèmi w epi yon pwogram edikasyon chofè. Ou dwe gen 18 an pou yon lisans komèsyal (CDL). Pèsonn ki poko gen 16 an pa ka kondui Massachusetts, menm ak yon lisans lòt kote.", "16 for a Class D or Class M learner's permit. You can get a license at 16½ at the earliest, after six months with your permit and a driver's education program. You must be 18 for a commercial license (CDL). No one under 16 may drive in Massachusetts, even with a license from somewhere else.", ["S7"], "3–4", "apply"],
["Ki etap pou m jwenn pèmi m?", "What are the steps to get my permit?", "Etidye mànyèl la, ranpli aplikasyon an (ou ka kòmanse l sou entènèt nan Mass.Gov/RMV), pran yon randevou epi pote l nan yon sant sèvis RMV, satisfè kondisyon idantifikasyon yo, peye $30 pou egzamen an, pran foto w, pase yon tès vizyon, epi pase egzamen pèmi an.", "Study the manual, fill out the application (you can start it online at Mass.Gov/RMV), make a reservation and bring it to an RMV service center, meet the ID requirements, pay the $30 exam fee, have your photo taken, pass a vision test, and pass the permit exam.", ["S7"], "14–16", "apply"],
["Ki diferans ant yon REAL ID ak yon Lisans Estanda?", "What is the difference between a REAL ID and a Standard license?", "Tou de pèmèt ou kondui menm jan, yo koute menm pri a epi yo mande menm egzamen yo. Pou w pran avyon anndan Etazini oswa antre nan kèk bilding federal, ou bezwen yon REAL ID oswa yon lòt pyès yo aksepte tankou yon paspò; yon Lisans Estanda pa bon pou sa. Dokiman ou pote yo pa menm. Ou ka gen yon sèl lisans oswa kat idantite alafwa.", "Both let you drive the same way, cost the same and need the same tests. To fly within the U.S. or enter certain federal buildings, you need a REAL ID or another accepted ID such as a passport; a Standard license does not work for that. The documents you bring are different. You may hold only one license or ID card at a time.", ["S7"], "6", "apply"],
["Ki dokiman mwen bezwen pou yon REAL ID?", "What documents do I need for a REAL ID?", "Yon dokiman ki pwouve ou la legalman Ozetazini, de ki pwouve ou rete Massachusetts, ak youn ki pwouve Nimewo Sekirite Sosyal ou (oswa yon lèt refi Sekirite Sosyal ak paspò etranje w, viza w ak I-94 ou). Pote orijinal yo: yo pa aksepte fotokopi ni dokiman ki plastifye. Lis konplè a nan Mass.Gov/ID.", "One document that proves lawful presence in the U.S., two that prove Massachusetts residency, and one that proves your Social Security Number (or a Social Security denial notice with your non-U.S. passport, visa and I-94). Bring originals: photocopies and laminated documents are not accepted. The full list is at Mass.Gov/ID.", ["S7"], "12–14", "apply"],
["Ki dokiman mwen bezwen pou yon Lisans Estanda?", "What documents do I need for a Standard license?", "Youn oswa de dokiman ki pwouve idantite w ak dat nesans ou, youn ki pwouve ou rete Massachusetts, ak kondisyon Sekirite Sosyal la: yon nimewo yo ka verifye sou òdinatè, yon lèt refi Sekirite Sosyal ak paspò etranje w, viza w ak I-94 ou, oswa, pou kèk moun, yon Afidavi Pa Gen Nimewo Sekirite Sosyal.", "One or two documents that prove your identity and date of birth, one that proves Massachusetts residency, and the Social Security requirement: a number that checks out electronically, a Social Security denial notice with your non-U.S. passport, visa and I-94, or, for certain applicants, a No Social Security Number Affidavit.", ["S7"], "12–14", "apply"],
["Èske m ka jwenn yon lisans kèlkeswa sitiyasyon imigrasyon m?", "Can I get a license whatever my immigration status?", "Wi, yon Lisans Estanda. Depi jiyè 2023, Lwa sou Mobilite pou Travay ak Fanmi (Work and Family Mobility Act) pèmèt tout moun ki rete Massachusetts epi ki kalifye aplike. Ou pwouve idantite w, dat nesans ou, sitiyasyon Sekirite Sosyal ou ak rezidans ou Massachusetts; yon paspò etranje ki valab epi ki poko ekspire se youn nan dokiman yo aksepte. Kat la make li pa pou idantite federal. Nouvo chofè yo toujou pase tès vizyon, egzamen pèmi ak Egzamen Pratik la.", "Yes, a Standard license. Since July 2023, the Work and Family Mobility Act lets every qualified Massachusetts resident apply. You prove identity, date of birth, Social Security status and Massachusetts residency; a valid, unexpired foreign passport is among the accepted documents. The card says it is not for federal ID. New drivers still take the vision test, permit exam and road test.", ["S7", "S31"], "12–14", "apply"],
["Mwen pa gen Nimewo Sekirite Sosyal. Kisa m ka fè?", "I don't have a Social Security Number. What can I do?", "Si w te aplike epi yo te refize w, pote lèt refi a (ki pa gen plis pase 60 jou) ak prèv sitiyasyon viza w, I-94 ou ak paspò etranje w. Si w pa ka aplike pou yon nimewo, ou ka prezante yon Afidavi Pa Gen Nimewo Sekirite Sosyal epi aplike pou yon Lisans Estanda.", "If you applied and were denied, bring the written denial notice (no more than 60 days old) with proof of your visa status, your I-94 and your non-U.S. passport. If you cannot apply for a number, you can present a No Social Security Number Affidavit and apply for a Standard license.", ["S7"], "13–14", "apply"],
["Mwen poko gen 18 an. Kiyès ki dwe siyen aplikasyon m?", "I am under 18. Who has to sign my application?", "Yon paran, yon gadyen legal, yon travayè sosyal oswa direktè yon lekòl pansyon siyen do aplikasyon an. Nenpòt moun ki pa paran dwe montre prèv li se gadyen. Fo siyati ka mennen nan sispansyon oswa revokasyon.", "A parent, legal guardian, social worker or boarding school headmaster signs the back of the application. Anyone other than a parent must show proof of guardianship. Forging a signature can lead to suspension or revocation.", ["S7"], "4", "apply"],
["Ki règ pou foto a?", "What are the photo rules?", "Tout figi w dwe parèt. Pa gen okenn kalite linèt, mouchwa, vwal, mask ni kas Bluetooth. Yo aksepte chapo oswa kouvri tèt sèlman pou rezon medikal oswa relijye, epi sèlman si li pa kache okenn pati nan figi w.", "Your whole face must show. No glasses of any kind, no scarf, veil, mask or Bluetooth headset. A hat or head cover is allowed only for medical or religious reasons, and only if it hides none of your face.", ["S7"], "4", "apply"],
["Ki kondisyon pou vizyon an?", "What is the vision requirement?", "Omwen 20/40 nan pi bon je w (ak linèt oswa lantiy si w mete yo) ak 120 degre vizyon sou kote. Ant 20/50 ak 20/70, ou ka jwenn yon lisans pou kondui lajounen sèlman. Si w pase ak linèt, lisans ou ap di ou dwe mete yo. Olye tès RMV a, ou ka pote yon Sètifika Tès Vizyon doktè je w ranpli.", "At least 20/40 in your better eye (with glasses or contacts if you wear them) and 120 degrees of side vision. Between 20/50 and 20/70, you may get a daylight-only license. If you pass with glasses, your license says you must wear them. Instead of the RMV screening, you can bring a Vision Screening Certificate from your eye doctor.", ["S7"], "4–5, 9", "apply"],
["Èske m dwe di si m gen yon pwoblèm sante?", "Do I have to report a medical condition?", "Wi. Aplikasyon pèmi an ak aplikasyon Egzamen Pratik la mande si w gen yon pwoblèm fizik, mantal oswa medikal, oswa si w pran yon medikaman, ki ka afekte jan w kondui. Si se konsa, ou bezwen yon otorizasyon medikal doktè w anvan Egzamen Pratik la, epi biwo Afè Medikal RMV a ka ajoute restriksyon. Afè Medikal: 857-368-8020.", "Yes. The permit and road test applications ask whether you have a physical, mental or medical condition, or take medicine, that could affect your driving. If so, you need medical clearance from your doctor before the road test, and the RMV's Medical Affairs office may add restrictions. Medical Affairs: 857-368-8020.", ["S7"], "5, 9, 15, 22", "apply"],
["Mwen te gen lisans nan yon lòt eta. Èske sa enpòtan?", "I was licensed in another state. Does that matter?", "Wi. Ou bay lis tout eta kote w te gen lisans nan dis dènye ane yo. RMV a verifye yon baz done nasyonal sispansyon, epi ou pa ka kontinye toutotan yon sispansyon nan yon lòt eta pa regle. Ou pa ka gen lisans nan de eta: lè w jwenn yon lisans Massachusetts, lòt la anile.", "Yes. You list every state where you were licensed in the past ten years. The RMV checks a national database of suspensions, and you cannot continue until any out-of-state suspension is cleared. You cannot hold licenses in two states: getting a Massachusetts license cancels the other one.", ["S7"], "5", "apply"],
["Ki klas lisans ki genyen?", "What are the license classes?", "Klas D se pou machin, SUV, kamyonèt ak ti kamyon. Klas M se pou moto. Klas A, B ak C se lisans komèsyal (CDL) pou gwo kamyon ak bis; ou dwe gen 18 an epi sèvi ak mànyèl CDL la apa.", "Class D is for cars, SUVs, vans and small trucks. Class M is for motorcycles. Classes A, B and C are commercial licenses (CDL) for large trucks and buses; you must be 18 and use the separate CDL manual.", ["S7"], "1, 7", "apply"],
["Kisa k ap pase si yo refize aplikasyon m?", "What if my application is denied?", "Ou ka fè apèl nan dis jou apre RMV a ba w refi a alekri. Yon apèl fòmèl ale bò Komisyon Apèl Divizyon Asirans lan, ak yon chèk oswa manda $50.", "You can appeal within ten days of the RMV's written denial. A formal appeal goes to the Board of Appeal of the Division of Insurance, with a $50 check or money order.", ["S7"], "14", "apply"],
["Kisa ki gen nan egzamen pèmi an?", "What is on the permit exam?", "25 kesyon chwa miltip. Ou bezwen 18 bon nan 25 minit, apeprè yon minit pou chak kesyon. Sijè yo gen ladan move itilizasyon alkòl, sispansyon, vyolasyon Lisans pou Jèn Chofè, règ wout yo ak siy wout yo.", "25 multiple-choice questions. You need 18 right within 25 minutes, about one minute per question. Topics include alcohol misuse, suspensions, Junior Operator License violations, rules of the road and road signs.", ["S7"], "16", "exam"],
["Èske m ka pase egzamen an an Kreyòl, an Fransè oswa an Panyòl?", "Can I take the exam in Haitian Creole, French or Spanish?", "Wi. Egzamen pèmi Klas D a disponib nan anpil lang, tankou Kreyòl ayisyen, Fransè ak Panyòl, ak nan Lang Siy Ameriken (ASL). Mànyèl chofè a pibliye nan lang sa yo tou.", "Yes. The Class D permit exam is offered in many languages, including Haitian Creole, French and Spanish, and in American Sign Language. Driver's manuals are also published in these languages.", ["S7"], "17", "exam"],
["Èske yo ka li kesyon yo pou mwen?", "Can the questions be read aloud to me?", "Wi. Nenpòt moun ka chwazi yon egzamen odyo, nan tout lang yo ofri yo, san randevou ni lòt papye. Pote pwòp kas ekoutè w nan sant sèvis la. Tan an toujou 25 minit.", "Yes. Anyone can choose an audio exam, in every language offered, with no appointment or extra documents. Bring your own headphones to the service center. The time limit is still 25 minutes.", ["S7"], "17", "exam"],
["Èske m ka pase egzamen an sou entènèt?", "Can I take the exam online?", "Wi, apre w fin depoze aplikasyon w nan yon sant sèvis. Ou ka pase l nan sant sèvis la menm jou a tou. Si w pase sou entènèt men ou pa ka enprime pèmi an, rele 857-368-8110 epi RMV a ap voye l ba w pa lapòs nan senk a sèt jou ouvrab.", "Yes, after you have submitted your application at a service center. You can also take it at the service center the same day. If you pass online but cannot print the permit, call 857-368-8110 and the RMV will mail it in five to seven business days.", ["S7"], "16", "exam"],
["Kisa mwen pa gen dwa pote nan egzamen an?", "What am I not allowed to bring into the exam?", "Pa gen mànyèl ni nòt, ni okenn aparèy elektwonik. Kas ekoutè sèlman pou yon egzamen odyo. Pa gen chapo, sof pou rezon medikal oswa relijye. Sèvi ak youn nan bagay sa yo konte kòm triche.", "No manual or notes and no electronic device of any kind. Headphones only for an audio exam. No hat, unless for medical or religious reasons. Using any of these counts as cheating.", ["S7"], "16", "exam"],
["Kisa k ap pase si m echwe?", "What happens if I fail?", "Ou ka repase l, men ou peye $30 la ankò. Si yo kenbe w ap triche, ou echwe epi ou pa ka gen okenn lisans ni pèmi pandan 60 jou.", "You can take it again, but you pay the $30 exam fee again. If you are caught cheating, you fail and cannot hold any license or permit for 60 days.", ["S7"], "16, 31–32", "exam"],
["Èske m ka jwenn èd pou egzamen an si m gen yon andikap?", "Can I get help taking the exam if I have a disability?", "Wi. Ou ka mande plis tan oswa yon moun pou li kesyon yo. Rele RMV nan 857-368-8105 epi kite non w, nimewo telefòn ou, sa w bezwen ak ki sant sèvis ou vle a. Menm nimewo a pou mande yon entèprèt ASL.", "Yes. You can ask for extended time or a reader. Call the RMV at 857-368-8105 and leave your name, phone number, what you need and which service center you want. The same number arranges an ASL interpreter.", ["S7"], "17–18", "exam"],
["Kiyès ki dwe avè m lè m ap kondui ak yon pèmi?", "Who has to be with me when I drive with a permit?", "Yon chofè ki gen lisans, ki gen omwen 21 an ak omwen yon ane eksperyans, chita sou chèz pasaje devan an. Pote pèmi w chak fwa w ap kondui.", "A licensed driver at least 21 years old, with at least one year of driving experience, sitting in the front passenger seat. Carry your permit every time you drive.", ["S7"], "18", "permit"],
["Èske m ka kondui lannwit ak yon pèmi?", "Can I drive at night with a permit?", "Si w poko gen 18 an, non ant 12:00 a.m. ak 5:00 a.m., sof si yon paran oswa gadyen legal ki gen lisans ak omwen yon ane eksperyans avè w.", "If you are under 18, not between 12:00 a.m. and 5:00 a.m. unless a parent or legal guardian who is a licensed driver with at least one year of experience is with you.", ["S7"], "18", "permit"],
["Pou konbyen tan pèmi m bon?", "How long is my permit good for?", "Jiska dezan. Si l ekspire, ou dwe repase egzamen pèmi an epi peye ankò. Yon pèmi se pa yon pyès idantite pou vwayaje: pifò konpayi avyon pap aksepte l.", "Up to two years. If it expires, you must take the permit exam again and pay the fee again. A permit is not a travel ID: most airlines will not accept it.", ["S7"], "14–16", "permit"],
["Èske m ka kondui nan yon lòt eta ak pèmi m?", "Can I drive in another state with my permit?", "Wi, depi sa pa vyole lwa eta sa a. Verifye règ eta sa a pou chofè apranti anvan w ale.", "Yes, as long as it does not break that state's laws. Check that state's rules for learner drivers before you go.", ["S7"], "18", "permit"],
["Ki règ pou yon pèmi moto (Klas M)?", "What are the rules for a motorcycle (Class M) permit?", "Pa gen pasaje, monte sèlman ant solèy leve ak solèy kouche, yon kas DOT, ak linèt pwoteksyon oswa yon visyè sof si moto a gen yon vit devan. Mànyèl Moto RMV a apa pale sou egzamen Klas M lan.", "No passengers, riding only between sunrise and sunset, a U.S. DOT helmet, and goggles, glasses or a face shield unless the motorcycle has a windshield. The RMV's separate Motorcycle Manual covers the Class M exam.", ["S7"], "18, 21", "permit"],
["Kisa m bezwen anvan m ka jwenn yon lisans si m poko gen 18 an?", "What do I need before I can get a license if I am under 18?", "Gen omwen 16 an edmi, kenbe pèmi w sis mwa youn dèyè lòt san okenn pwoblèm sou dosye w, epi fini yon pwogram edikasyon chofè RMV apwouve: 30 èdtan klas, 12 èdtan dèyè volan ak 6 èdtan obsève, plis yon egzamen final. Ou bezwen tou 40 èdtan kondui sipèvize yon paran siyen (30 si w fè yon pwogram devlopman konpetans), epi yon paran oswa gadyen dwe asiste de èdtan nan kou a. Ou resevwa yon Lisans pou Jèn Chofè (JOL).", "Be at least 16½, hold your permit for six months in a row with a clean record, and finish an RMV-approved driver's education program: 30 hours of class, 12 hours behind the wheel and 6 hours observing, plus a final exam. You also need 40 hours of supervised driving signed by a parent (30 with a driver skills program), and a parent or guardian must attend two hours of the course. You get a Junior Operator License (JOL).", ["S7"], "9–10, 19", "jol"],
["Ki règ ki aplike pou yon Lisans pou Jèn Chofè?", "What rules apply to a Junior Operator License?", "Pandan sis premye mwa yo: pa gen pasaje ki poko gen 18 an sof fanmi pwòch, sof si yon chofè 21 an oswa plis ki gen yon ane eksperyans chita bò kote w. Pa kondui ant 12:30 a.m. ak 5:00 a.m. san yon paran oswa gadyen legal. Pa sèvi ak telefòn ni okenn aparèy mobil, sof pou rapòte yon ijans. Pa kondui okenn veyikil ki mande yon lisans komèsyal.", "For the first six months: no passengers under 18 except immediate family, unless a licensed driver 21 or older with a year of experience sits beside you. No driving from 12:30 a.m. to 5:00 a.m. without a parent or legal guardian. No phone or other mobile device at all, except to report an emergency. No vehicle that needs a commercial license.", ["S7"], "10–11", "jol"],
["Kisa k ap pase si m vyole règ pasaje oswa règ lannwit lan?", "What happens if I break the passenger or night rule?", "Sispansyon lisans: 60 jou premye fwa, 180 jou dezyèm fwa, yon ane apre sa, plis yon kou Refòmasyon Atitid Chofè apati dezyèm fwa a. Kondui nan lè lannwit yo san paran ka konte tou kòm kondui san lisans, yon krim.", "License suspension: 60 days the first time, 180 days the second, one year after that, plus a Driver Attitudinal Retraining course from the second time. Driving during night hours without a parent can also be charged as driving without a license, a criminal offense.", ["S7"], "10–11", "jol"],
["Kisa sa vle di pou dosye w pwòp anvan Egzamen Pratik la?", "What does a clean record mean before my road test?", "Si w poko gen 18 an, sis mwa anvan egzamen an pa dwe gen okenn evènman ki ka fè w peye plis (tankou aksidan se ou ki an tò oswa vyolasyon pandan w ap kondui), okenn sispansyon pèmi pou enfraksyon kondui ak dwòg oswa alkòl, ni okenn kondanasyon pou dwòg oswa alkòl. Yon nouvo evènman, menm apre w fin pran randevou, anile egzamen an jiskaske w gen sis mwa pwòp oswa ou gen 18 an.", "If you are under 18, the six months before the test must have no surchargeable events (such as at-fault crashes or moving violations), no permit suspension for drug or alcohol driving offenses, and no drug or alcohol convictions. A new event, even after you book, cancels the test until you have six clean months or turn 18.", ["S7"], "22", "jol"],
["Kilè règ Jèn Chofè yo fini?", "When do the Junior Operator rules end?", "Règ pasaje a fini apre sis mwa oswa lè w gen 18 an, sa ki rive anvan an; yon sispansyon kanpe sis mwa yo pou yon tan. Lòt règ JOL yo aplike jiskaske w gen 18 an. Ou dwe fin fè yon sispansyon ou te resevwa kòm jèn chofè anvan w ka jwenn yon lisans konplè.", "The passenger rule ends after six months or at 18, whichever comes first; a suspension pauses the six months. The other JOL rules apply until you turn 18. A suspension received as a junior operator must be finished before you can get a full license.", ["S7"], "10–11", "jol"],
["Kijan Egzamen Pratik la mache?", "How does the road test work?", "Ou bezwen yon pèmi bon klas la. Pran, anile oswa chanje randevou nan Mass.Gov/RMV oswa nan Sant Kontak la. Frè a se $35. Rive apeprè 15 minit davans: si w an reta, yo pap fè egzamen an epi w ap peye frè a kanmenm. Ou ka pase pi plis sis Egzamen Pratik Klas D nan 12 mwa.", "You need a permit of the right class. Schedule, cancel or reschedule at Mass.Gov/RMV or through the Contact Center. The fee is $35. Arrive about 15 minutes early: if you are late, you will not be tested and still pay the fee. You can take at most six Class D road tests in 12 months.", ["S7"], "20–21, 24, 32", "road"],
["Kisa m bezwen pote nan Egzamen Pratik la?", "What do I need to bring to the road test?", "Yon aplikasyon Egzamen Pratik ranpli (ak konsantman paran oswa gadyen si w poko gen 18 an), pèmi apranti w enprime, yon sipèvizè ki kalifye ak lisans li ki valab, ak yon machin ki an bon eta, ki anrejistre, ki enspekte, ak sètifika anrejistreman li.", "A completed road test application (with parent or guardian consent if you are under 18), your printed learner's permit, a qualified sponsor with their valid license, and a safe, registered, inspected vehicle with its registration certificate.", ["S7"], "22", "road"],
["Kiyès ki ka sipèvizè m?", "Who can be my sponsor?", "Yon chofè ki gen lisans, ki gen omwen 21 an, omwen yon ane eksperyans ak yon lisans valab yon eta ameriken. Yon moun ki gen sèlman yon lisans etranje pa ka sipèvizè. Ou bezwen yon sipèvizè menm si w gen yon lisans etranje. Sipèvizè a chita dèyè w, epi yon moun ka sipèvizè pou pi plis twa moun pa ane san otorizasyon RMV. Pa bezwen sipèvizè pou egzamen moto.", "A licensed driver at least 21 years old, with at least one year of experience and a valid license from a U.S. state. Someone with only a foreign license cannot sponsor. You need a sponsor even if you have a foreign license. The sponsor sits behind you, and a person may sponsor at most three applicants a year without RMV approval. No sponsor is needed for a motorcycle test.", ["S7"], "22–23", "road"],
["Kisa machin pou egzamen an bezwen?", "What does the test vehicle need?", "Li dwe an bon eta, anrejistre epi enspekte, ak yon chèz pou egzaminatè a bò kote w ak youn pou sipèvizè w dèyè w, epi yon fren pakin egzaminatè a ka rive jwenn (yon fren nan mitan an pi sèten). Pa gen kawoutchou 'donut' derechany. Yon machin ki anrejistre nan yon lòt eta bezwen prèv asirans nan minimòm Massachusetts. Yon machin lwe bezwen kontra a ak yon lèt konpayi lokasyon an. Machin ki gen plak reparasyon pa aksepte; plak konsesyonè sèlman si se ou ki konsesyonè a oswa ou travay la.", "It must be safe, registered and inspected, with a seat for the examiner beside you and one for your sponsor behind you, and a parking brake the examiner can reach (a center brake is safest). No spare 'donut' tire. An out-of-state vehicle needs proof of insurance at Massachusetts minimums. A rental needs the agreement and a letter from the rental company. Vehicles with repair plates are not allowed; dealer plates only if you are the dealer or work there.", ["S7"], "23–24", "road"],
["Kisa m pral gen pou m fè nan Egzamen Pratik la?", "What will I have to do on the road test?", "Fè siy ak men, demare motè a, demare ak kanpe, pake an paralèl, fè bak apeprè 50 pye, vire agoch ak adwat, demare, kanpe ak vire sou yon mòn, fè yon vire an twa mouvman, antre ak soti nan kafou, epi respekte siy, siyal ak règ wout yo. Egzaminatè a gade tou jan w chita, pozisyon w nan vwa a, siyal ou, distans ou, vitès ou ak jan w bay dwa de pasaj.", "Use hand signals, start the engine, start and stop, parallel park, back up about 50 feet, make left and right turns, start, stop and turn on a hill, do a three-point turn, enter and leave intersections, and obey signs, signals and rules of the road. The examiner also watches your posture, lane position, signals, following distance, speed and yielding.", ["S7"], "25–26", "road"],
["Machin mwen gen kamera pou fè bak ak pakin otomatik. Èske m ka sèvi ak yo?", "My car has a backup camera and self-parking. Can I use them?", "Ou pa bezwen etenn yo, men egzaminatè a teste pwòp konpetans ou san w pa konte sèlman sou yo. Si w bezwen fonksyon sa yo oswa ekipman adapte pou rezon medikal pou w kondui, yo ajoute yon restriksyon sou lisans ou.", "They do not need to be turned off, but the examiner tests your own skills without relying only on them. If you need these features or medical adaptive equipment to drive, a restriction is added to your license.", ["S7"], "25", "road"],
["Kiyès ki ka nan machin nan pandan egzamen an?", "Who can be in the car during the test?", "Sèlman ou menm, egzaminatè a bò kote w ak sipèvizè w dèyè w. Yo ka pèmèt yon entèprèt lang. Bèt sèvis ki fòme aksepte; timoun, bèt kay ak bèt sipò emosyonèl pa aksepte. Ou pa ka pale ak sipèvizè w oswa entèprèt la sof si egzaminatè a pèmèt sa.", "Only you, the examiner beside you and your sponsor behind you. A language interpreter may be allowed. Trained service animals are allowed; children, pets and emotional support animals are not. You may not talk with your sponsor or interpreter unless the examiner allows it.", ["S7"], "25", "road"],
["Ki rezon moun konn echwe pi souvan?", "What are common reasons for failing?", "Kondui yon fason ki danjere oswa ki ka lakoz yon aksidan, vyole yon lwa sikilasyon, montre twò piti eksperyans, pa swiv enstriksyon egzaminatè a, pa konnen siy ak men yo, oswa se ou ki an tò nan yon aksidan pandan egzamen an.", "Driving dangerously or in a way that could cause a crash, breaking a traffic law, showing too little experience, not following the examiner's instructions, not knowing the hand signals, or being at fault in a crash during the test.", ["S7"], "26", "road"],
["Kisa k ap pase si m echwe oswa si m rate Egzamen Pratik la?", "What if I fail or miss the road test?", "Ou peye $35 la ankò epi ou dwe tann omwen 14 jou pou yon lòt egzamen. Ou peye frè a tou si w anile mwens pase 72 èdtan davans, rive an reta oswa pa prepare, pa vini ak yon sipèvizè ki kalifye, oswa si machin ou pa pase enspeksyon egzaminatè a.", "You pay the $35 again and must wait at least 14 days for another test. You also pay the fee if you cancel with less than 72 hours' notice, arrive late or unprepared, bring no qualified sponsor, or your vehicle fails the examiner's inspection.", ["S7"], "20–21, 32", "road"],
["Kilè yo anile oswa refize yon Egzamen Pratik?", "When is a road test cancelled or refused?", "Yo anile egzamen yo lè gen yon eta ijans ofisyèl oswa move tan ki danjere, epi ou pran yon lòt randevou gratis. Egzaminatè a refize egzamen an si ou menm oswa sipèvizè w gen siy enfliyans oswa santi alkòl oswa kannabis, oswa si gen timoun oswa bèt ki pa ka rete pou kont yo nan machin nan.", "Tests are cancelled for a declared state of emergency or unsafe weather, and you rebook for free. The examiner refuses the test if you or your sponsor show signs of impairment or smell of alcohol or cannabis, or if children or animals who cannot be left alone are in the car.", ["S7"], "21", "road"],
["Mwen soud oswa mwen gen difikilte pou tande. Kijan pou m pran randevou Egzamen Pratik la?", "I am Deaf or hard of hearing. How do I book the road test?", "Rele 1-877-768-8833 (TTY RMV) ak demann ou, kote w vle a, ak telefòn, adrès ak imèl ou. RMV a pran randevou a epi fè aranjman pou yon entèprèt. Pandan egzamen an, ou ka rale sou kote san danje pou w kominike ak egzaminatè a.", "Call 1-877-768-8833 (RMV TTY) with your request, the location you want, and your phone, address and email. The RMV books the test and arranges an interpreter. You may pull over safely during the test to communicate with the examiner.", ["S7"], "26", "road"],
["Kijan pou m jwenn yon lisans moto?", "How do I get a motorcycle license?", "Pran yon pèmi Klas M, apre sa pase yon Egzamen Pratik RMV oswa fini kou Pwogram Edikasyon Motosiklis Massachusetts (MREP), ki ranplase Egzamen Pratik la. Si w poko gen 18 an, kou debaz MREP la ak yon sètifika edikasyon chofè obligatwa. Apre de echèk nan Egzamen Pratik Klas M, ou dwe fini yon kou pou motosiklis debitan.", "Get a Class M permit, then pass an RMV road test or finish the Massachusetts Rider Education Program (MREP) course, which replaces the road test. Under 18, the MREP basic course and a driver's education certificate are required. After two failed Class M road tests, you must complete a beginner rider course.", ["S7"], "20–22", "road"],
["Kilè m resevwa lisans mwen apre m fin pase?", "When do I get my license after I pass?", "Si w te peye frè yo davans, egzaminatè a valide pèmi w kòm yon lisans tanporè pou jiska 60 jou, epi lisans plastik la vin pa lapòs; rele RMV si l pa rive nan 30 jou. Si w pa t peye davans, peye sou entènèt oswa nan yon sant sèvis nan 60 jou, sinon ou ka oblije repase Egzamen Pratik la.", "If you prepaid the fees, the examiner validates your permit as a temporary license for up to 60 days, and the plastic license comes by mail; call the RMV if it has not arrived in 30 days. If you did not prepay, pay online or at a service center within 60 days, or you may have to retake the road test.", ["S7"], "27", "lic"],
["Pou konbyen tan yon lisans valab?", "How long is a license valid?", "Jiska senk an, epi l konn ekspire jou fèt ou. Yon Lisans Estanda toujou senk an. Yon REAL ID ka pi kout si tan yo otorize w rete Ozetazini pi kout, epi frè a kalkile selon tan an. Si w jwenn oswa renouvle yon lisans anvan 21 an, se yon kat vètikal 'Under 21', ki valab jiskaske l ekspire.", "Up to five years, usually expiring on your birthday. A Standard license is always five years. A REAL ID can be shorter if your authorized stay in the U.S. is shorter, with the fee prorated. If you get or renew a license before 21, it is a vertical 'Under 21' card, valid until it expires.", ["S7"], "7–8", "lic"],
["Kijan e kilè pou m renouvle?", "How and when do I renew?", "Jiska yon ane anvan l ekspire; frè a se $50. RMV a pap renouvle si w gen kontravansyon pakin ou pa peye, taks esiz ou pa peye, manda tribinal ki poko regle, vyolasyon E-ZPass oswa Tobin Bridge ou pa peye, kontravansyon pou machin abandone, oswa yon lisans ki sispann oswa revoke. Ou dwe pote fòm liberasyon ofisyèl ki montre tout sa regle.", "Up to one year before it expires; the fee is $50. The RMV will not renew if you have unpaid parking tickets, unpaid excise tax, outstanding court warrants, unpaid E-ZPass or Tobin Bridge violations, citations for an abandoned vehicle, or a suspended or revoked license. You must bring official release forms showing these are cleared.", ["S7"], "8, 32, 75–76", "lic"],
["Kisa lèt ki anba 'Restrictions' yo vle di?", "What do the letters under 'Restrictions' mean?", "Se limit sou jan w ka kondui. Sa ki pi komen yo: B, ou dwe mete linèt oswa lantiy; G, lajounen sèlman; I, Jèn Chofè (poko gen 18 an); Q, machin otomatik sèlman; T, aparèy ki bloke demaraj (ignition interlock). Afè Medikal ka ajoute lòt pou yon pwoblèm sante oswa ekipman adapte.", "They are limits on your driving. Common ones: B, you must wear corrective lenses; G, daylight only; I, Junior Operator (under 18); Q, automatic transmission only; T, ignition interlock. Medical Affairs may add others for a medical condition or adaptive equipment.", ["S7"], "8–9", "lic"],
["Èske m oblije pote lisans mwen?", "Do I have to carry my license?", "Wi. Chak fwa w ap kondui Massachusetts, lalwa mande pou lisans valab ou sou ou oswa kote w ka rive jwenn li fasil nan machin nan. Si w pa ka montre l bay lapolis, se $35 amann premye fwa.", "Yes. Whenever you drive in Massachusetts, the law requires your valid license on you or within easy reach in the vehicle. Failing to show it to police is a $35 fine for a first offense.", ["S7"], "27, 122", "lic"],
["Mwen demenaje. Kijan pou m chanje adrès mwen?", "I moved. How do I change my address?", "Avèti RMV nan 30 jou, sou entènèt nan Mass.Gov/RMV oswa pa telefòn. Ou ka ekri nouvo adrès la dèyè lisans ou ak lank ki pa efase, oswa kòmande yon kopi lisans ak nouvo adrès la.", "Tell the RMV within 30 days, online at Mass.Gov/RMV or by phone. You can write the new address on the back of your license in permanent ink, or order a duplicate license with the new address.", ["S30"], "", "lic"],
["Mwen pèdi lisans mwen, li domaje, oswa non m chanje. Kisa pou m fè?", "My license is lost or damaged, or my name changed. What do I do?", "Kòmande yon kopi oswa yon lisans korije. Frè a se $25 pou nenpòt chanjman ki mande yon nouvo kat.", "Order a duplicate or amended license. The fee is $25 for any change that requires a new card.", ["S7"], "32", "lic"],
["Èske lè m jwenn lisans sa enskri m pou vote?", "Does getting a license register me to vote?", "Si w se sitwayen ameriken epi w kalifye, enfòmasyon w ale bò ofisyèl eleksyon yo, ki enskri w oswa mete enskripsyon w ajou epi voye yon avi ba w pa lapòs ki pèmèt ou refize tou. Ou ka enskri a 16 an epi vote a 18 an.", "If you are a U.S. citizen and eligible, your information goes to election officials, who register you or update your registration and mail you a notice that also lets you decline. You can register at 16 and vote at 18.", ["S7"], "29", "lic"],
["Èske yo ka ekri 'Veteran' sou lisans mwen?", "Can 'Veteran' be printed on my license?", "Wi, gratis, si w te kite Fòs Lame Ameriken yo onorableman. Pote yon DD-214, DD-215 oswa fòm Egzeyat Onorab ki montre sa nan yon sant sèvis, ak randevou.", "Yes, free, if you were honorably discharged from the U.S. Armed Forces. Bring a DD-214, DD-215 or Honorable Discharge form showing honorable discharge to a service center, with a reservation.", ["S7"], "29–30", "lic"],
["Kisa kè ki sou yon lisans lan vle di?", "What does the heart on a license mean?", "Ou nan rejis donatè ògàn ak tisi Massachusetts. Ou ka enskri oswa chanje desizyon w nenpòt lè nan Mass.Gov/RMV. Lè w ap renouvle, ou dwe tcheke 'wi' ankò pou w rete nan rejis la. Don an pa koute fanmi w anyen.", "You are in the Massachusetts organ and tissue donor registry. You can join or change your choice anytime at Mass.Gov/RMV. When you renew, you must check 'yes' again to stay in the registry. Donation costs your family nothing.", ["S7"], "30–31", "lic"],
["M ap vizite soti nan yon lòt eta oswa yon lòt peyi. Èske m ka kondui isit?", "I am visiting from another state or country. Can I drive here?", "Wi, si w gen 16 an oswa plis ak yon lisans valab eta oswa peyi w pou menm kalite veyikil la. Pote l lè w ap kondui, ak yon tradiksyon an Anglè si lisans lan pa an Anglè. Kondui san li ka bay $500 amann. Sa se pou vizitè; moun ki rete isit dwe pran yon lisans Massachusetts.", "Yes, if you are 16 or older with a valid license from your home state or country for the same type of vehicle. Carry it when you drive, with an English translation if the license is not in English. Driving without it can bring a $500 fine. This applies to visitors; residents must get a Massachusetts license.", ["S7"], "2", "move"],
["Mwen vin rete isit ak yon lisans yon lòt eta ameriken. Kisa pou m fè?", "I moved here with a license from another U.S. state. What do I do?", "Pran yon lisans Massachusetts touswit; pa gen delè gras. Ou ka konvèti lisans ou san egzamen. Frè konvèsyon Klas D a se $115. Lisans lòt eta a anile lè Massachusetts ba w pa w la.", "Get a Massachusetts license right away; there is no grace period. You may be able to convert your license without testing. The Class D conversion fee is $115. Your other state's license is cancelled when Massachusetts issues yours.", ["S7"], "2, 5, 14, 32", "move"],
["Mwen gen yon lisans yon lòt peyi. Èske m oblije pase egzamen yo?", "I have a license from another country. Do I have to take the tests?", "Anjeneral wi: tès vizyon, egzamen pèmi ak Egzamen Pratik, ak yon sipèvizè. Massachusetts gen akò resipwòk ak Kore di Sid, Lafrans, Taywann ak Almay, ki gen pwòp pwosesis yo. Lisans Kanada, Meksik ak teritwa ameriken yo ka konvèti ak yon dosye kondui sètifye orijinal ki pa gen plis pase 30 jou.", "Usually yes: the vision test, permit exam and road test, with a sponsor. Massachusetts has reciprocal agreements with South Korea, France, Taiwan and Germany, handled through a separate process. Licenses from Canada, Mexico and U.S. territories can be converted with an original certified driving record no more than 30 days old.", ["S7", "S31"], "23, 28", "move"],
["Èske m ka transfere yon pèmi apranti yon lòt eta?", "Can I transfer a learner's permit from another state?", "Wi, si yo te ba ou l gen mwens pase dezan. Pote l ak yon dosye kondui sètifye ki pa gen plis pase 30 jou epi satisfè kondisyon idantifikasyon yo. Pa bezwen egzamen; frè a se $30. Pèmi Massachusetts ou a kenbe premye dat li te bay la, ki konte pou sis mwa yo pou chofè ki poko gen 18 an.", "Yes, if it was issued less than two years ago. Bring it with a certified driving record no more than 30 days old and meet the ID requirements. No exam is needed; the fee is $30. Your Massachusetts permit keeps the original issue date, which counts toward the six months for drivers under 18.", ["S7"], "28, 32", "move"],
["Mwen poko gen 18 an epi m gen yon lisans yon lòt eta. Èske m ka konvèti l?", "I am under 18 and have a license from another state. Can I convert it?", "Wi, kòm yon Lisans pou Jèn Chofè. Pote yon dosye kondui sètifye ansyen eta w la, gen yon sètifika edikasyon chofè Massachusetts nan dosye RMV (yo ka aksepte yon pwogram lòt eta si l satisfè minimòm Massachusetts), epi fè 40 èdtan kondui sipèvize (30 ak yon pwogram devlopman konpetans). Tout règ JOL yo aplike; règ pasaje a pa aplike si w deja gen yon lisans valab pandan sis mwa san sispansyon.", "Yes, as a Junior Operator License. Bring a certified driving record from your old state, have a Massachusetts driver's education certificate on file (an out-of-state program can be accepted if it meets Massachusetts minimums), and log 40 hours of supervised driving (30 with a driver skills program). All JOL rules apply; the passenger rule is skipped if you have already had a valid license for six months without suspension.", ["S7"], "19, 27–28", "move"],
["Ki règ pou moun ki nan militè?", "What are the rules for military members?", "Si w nan sèvis aktif, ou ka kondui isit ak yon lisans valab eta w; moun ki rete Massachusetts bezwen yon lisans Massachusetts. Yon lisans Fòs Lame yo bay lòtbò dlo bon isit pandan 45 jou apre w retounen. Yon lisans Massachusetts ki ekspire pandan sèvis aktif bon pandan 60 jou apre yon egzeyat onorab, si w pote prèv egzeyat la.", "On active duty, you may drive here with a valid license from your home state; Massachusetts residents need a Massachusetts license. A license issued by the Armed Forces overseas is good here for 45 days after you return. A Massachusetts license that expired during active service is good for 60 days after honorable discharge, if you carry proof of discharge.", ["S7"], "2–3", "move"],
["Konbyen tout bagay koute?", "How much does everything cost?", "Egzamen pèmi $30 (ou peye ankò apre yon echèk oswa si pèmi a ekspire). Egzamen Pratik $35. Lisans Klas D, nouvo oswa renouvle, $50. Kopi oswa lisans korije $25. Konvèti yon lisans Klas D lòt eta $115; konvèti yon pèmi $30. Yo pa ranbouse frè yo epi yo ka chanje. Veteran andikape ki gen plak Veteran Andikape (oswa ki kalifye pou yo) pa peye frè lisans.", "Permit exam $30 (paid again after a failed exam or an expired permit). Road test $35. Class D license, new or renewal, $50. Duplicate or amended license $25. Converting an out-of-state Class D license $115; converting a permit $30. Fees are non-refundable and can change. Disabled veterans with Disabled Veteran plates (or qualified for them) pay no license fees.", ["S7"], "31–32", "fees"],
["Kijan pou m kontakte RMV?", "How do I contact the RMV?", "Sant Kontak: 857-368-8000 (pou kòd 339, 617, 781 ak 857 oswa deyò Massachusetts) oswa 800-858-3926 (lòt kòd Massachusetts), lendi rive vandredi, 9 a.m. rive 5 p.m. TTY: 1-877-768-8833. Sou entènèt: Mass.Gov/RMV ak Mass.Gov/AsktheRMV. Sèvi sèlman ak sit ofisyèl la: sit ki sanble l yo ka fè w peye plis epi yo pa san danje pou enfòmasyon w.", "Contact Center: 857-368-8000 (from 339, 617, 781 and 857 area codes or outside Massachusetts) or 800-858-3926 (other Massachusetts area codes), Monday to Friday, 9 a.m. to 5 p.m. TTY: 1-877-768-8833. Online: Mass.Gov/RMV and Mass.Gov/AsktheRMV. Use only the official site: look-alike sites may charge extra fees and are not safe for your information.", ["S7"], "3, 15", "fees"]];
window.PERMIT_FAQ_GROUPS = {"apply": ["Anvan w aplike", "Before you apply"], "exam": ["Egzamen pèmi an", "The permit exam"], "permit": ["Kondui ak yon pèmi", "Driving with a permit"], "jol": ["Chofè ki poko gen 18 an (Lisans pou Jèn Chofè)", "Drivers under 18 (Junior Operator License)"], "road": ["Egzamen Pratik la", "The road test"], "lic": ["Lisans ou", "Your license"], "move": ["Ou fèk demenaje oswa ou gen lisans yon lòt kote", "Moving here or licensed elsewhere"], "fees": ["Frè ak kijan pou kontakte RMV", "Fees and contacting the RMV"]};
